// Foundations quizzes — high-school-to-intro-undergrad level (fls/fps/fbs prefixes).
// Deliberately introductory: general biology, intro chemistry/physics, and intro
// psychology/sociology, distinct from the MCAT-level bioBiochem/chemPhys/psychSoc
// banks. Categories match the existing three MCAT sections (Life Sciences,
// Physical Sciences, Behavioral & Social Sciences) so they slot into the same
// pathway/course/recommendation wiring without any schema changes.
export const FOUNDATIONS_QUIZZES = [
{"id":"fls01","cat":"Life Sciences","title":"Scientific Method Basics","diff":"Easy","qs":[{"q":"What is typically the first step of the scientific method?","ch":["Forming a conclusion","Running an experiment","Making an observation and asking a question","Publishing the results"],"ans":2,"exp":"Science typically begins with observing something in the world and asking a question about it, before a hypothesis is formed."},{"q":"What is a hypothesis?","ch":["A testable, educated guess that explains an observation","A proven scientific law","The final conclusion of an experiment","A random guess with no reasoning"],"ans":0,"exp":"A hypothesis is a testable explanation based on prior knowledge or observation, not a proven fact."},{"q":"In an experiment testing how sunlight affects plant growth, what is the independent variable?","ch":["The height of the plant measured","The amount of sunlight the plant receives","The type of soil used","The temperature of the room"],"ans":1,"exp":"The independent variable is the factor the experimenter deliberately changes, which here is the amount of sunlight."},{"q":"Why do scientists include a control group in an experiment?","ch":["To make the experiment take longer","To test more than one variable at once","To ensure the results support the hypothesis","To provide a baseline for comparison with the experimental group"],"ans":3,"exp":"A control group is kept under normal, unchanged conditions so results in the experimental group can be compared against it."},{"q":"Why is it important for other scientists to be able to repeat (replicate) an experiment?","ch":["To confirm that the results are reliable and not due to chance","So the original scientist gets credit","To make the experiment more expensive","To change the hypothesis each time"],"ans":0,"exp":"Replication helps confirm that results are consistent and trustworthy rather than a one-time fluke."},{"q":"What is 'data' in the context of a scientific experiment?","ch":["The scientist's opinion about the results","The hypothesis being tested","The information and measurements collected during an experiment","The title of the research paper"],"ans":2,"exp":"Data refers to the factual measurements and observations gathered while conducting an experiment."},{"q":"For a hypothesis to be scientific, it must be:","ch":["Impossible to test","Always proven true","Agreed upon by everyone","Testable and falsifiable (able to be proven wrong)"],"ans":3,"exp":"A scientific hypothesis must be able to be tested and potentially shown false through experimentation or observation."},{"q":"In science, what is a theory?","ch":["A guess with little evidence","A well-supported explanation for a set of observations, backed by extensive evidence","An untested idea","A law that never changes"],"ans":1,"exp":"Unlike the everyday use of the word, a scientific theory is a thoroughly tested and well-supported explanation of natural phenomena."}]},
{"id":"fls02","cat":"Life Sciences","title":"Cell Theory & Cell Discovery","diff":"Easy","qs":[{"q":"Who is credited with first observing and naming 'cells' after looking at cork under a microscope?","ch":["Anton van Leeuwenhoek","Robert Hooke","Louis Pasteur","Gregor Mendel"],"ans":1,"exp":"Robert Hooke observed the small box-like compartments in cork and named them 'cells' in the 1660s."},{"q":"Which scientist observed living microorganisms ('animalcules') using early microscopes he built himself?","ch":["Robert Hooke","Charles Darwin","Rudolf Virchow","Anton van Leeuwenhoek"],"ans":3,"exp":"Anton van Leeuwenhoek used his own handcrafted microscopes to become the first person to observe living microorganisms."},{"q":"Which of the following is NOT one of the three main parts of cell theory?","ch":["All cells contain the exact same organelles in equal numbers","All living things are made of one or more cells","The cell is the basic unit of structure and function in living things","All cells come from pre-existing cells"],"ans":0,"exp":"Cell theory does not claim all cells are identical; different cell types have different structures suited to their function."},{"q":"Which scientist contributed the idea that 'all cells arise from pre-existing cells'?","ch":["Robert Hooke","Anton van Leeuwenhoek","Rudolf Virchow","Isaac Newton"],"ans":2,"exp":"Rudolf Virchow proposed that new cells form only from the division of existing cells, completing modern cell theory."},{"q":"What tool was essential for the discovery of cells?","ch":["Telescope","Microscope","Barometer","Centrifuge"],"ans":1,"exp":"Cells are too small to see with the naked eye, so the invention and improvement of microscopes made their discovery possible."},{"q":"According to cell theory, what is considered the basic unit of life?","ch":["The cell","The organ","The tissue","The organ system"],"ans":0,"exp":"Cell theory states that the cell is the fundamental structural and functional unit of all living organisms."},{"q":"Matthias Schleiden and Theodor Schwann are best known for proposing that:","ch":["Cells reproduce by mitosis only","DNA is the genetic material","Cells can spontaneously generate from nonliving matter","Plants and animals are both made of cells"],"ans":3,"exp":"Schleiden studied plant cells and Schwann studied animal cells; together they concluded all living things are composed of cells."},{"q":"Which statement about cell theory is TRUE?","ch":["Cells can form spontaneously from nonliving material","Only animals are made of cells","Cells are the basic building blocks of all living organisms","Bacteria are not made of cells"],"ans":2,"exp":"Cell theory holds that every living organism, from bacteria to humans, is composed of one or more cells."}]},
{"id":"fls03","cat":"Life Sciences","title":"Prokaryotic vs Eukaryotic Cells","diff":"Easy","qs":[{"q":"Which type of cell lacks a nucleus?","ch":["Prokaryotic cell","Eukaryotic cell","Plant cell only","Animal cell only"],"ans":0,"exp":"Prokaryotic cells, such as bacteria, do not have a membrane-bound nucleus."},{"q":"Which of these organisms has eukaryotic cells?","ch":["Bacteria","Archaea","Fungi","E. coli"],"ans":2,"exp":"Fungi are eukaryotes, meaning their cells contain a true, membrane-bound nucleus and other organelles."},{"q":"Where is the DNA located in a prokaryotic cell?","ch":["Inside a membrane-bound nucleus","Inside mitochondria","Inside the Golgi apparatus","Free-floating in the cytoplasm, in a region called the nucleoid"],"ans":3,"exp":"Prokaryotes lack a nucleus, so their DNA is concentrated in a region of the cytoplasm called the nucleoid."},{"q":"Which structure is found in eukaryotic cells but NOT in prokaryotic cells?","ch":["Cell membrane","Membrane-bound organelles such as mitochondria","Cytoplasm","Ribosomes"],"ans":1,"exp":"Eukaryotic cells contain membrane-bound organelles like mitochondria, while prokaryotic cells do not."},{"q":"Generally, how do the sizes of prokaryotic and eukaryotic cells compare?","ch":["Prokaryotic cells are always larger","They are exactly the same size","Prokaryotic cells are typically smaller than eukaryotic cells","Eukaryotic cells have no consistent size"],"ans":2,"exp":"Prokaryotic cells are generally much smaller and simpler in structure than eukaryotic cells."},{"q":"Bacteria are an example of which type of cell?","ch":["Prokaryotic","Eukaryotic","Fungal","Plant"],"ans":0,"exp":"Bacteria are single-celled prokaryotes, lacking a nucleus and other membrane-bound organelles."},{"q":"Which domain(s) of life consist of eukaryotic organisms?","ch":["Bacteria and Archaea","Eukarya (plants, animals, fungi, protists)","Bacteria only","Archaea only"],"ans":1,"exp":"Eukaryotic organisms belong to the domain Eukarya, which includes plants, animals, fungi, and protists."},{"q":"Which of the following is shared by BOTH prokaryotic and eukaryotic cells?","ch":["A nucleus","Mitochondria","A Golgi apparatus","A cell membrane and cytoplasm"],"ans":3,"exp":"All cells, prokaryotic or eukaryotic, have a cell membrane enclosing their cytoplasm."}]},
{"id":"fls04","cat":"Life Sciences","title":"DNA & RNA Structure Basics","diff":"Easy","qs":[{"q":"What shape does a DNA molecule form?","ch":["A single straight chain","A branched tree","A flat sheet","A double helix"],"ans":3,"exp":"DNA is made of two strands that wind around each other to form a double helix shape."},{"q":"Which of the following is a nitrogenous base found in DNA but NOT in RNA?","ch":["Adenine","Thymine","Cytosine","Guanine"],"ans":1,"exp":"DNA uses thymine, while RNA uses uracil in its place."},{"q":"What sugar is found in the backbone of DNA?","ch":["Ribose","Glucose","Deoxyribose","Fructose"],"ans":2,"exp":"DNA's backbone contains the sugar deoxyribose, which is where the 'D' in DNA comes from."},{"q":"In DNA base pairing, adenine always pairs with:","ch":["Thymine","Guanine","Cytosine","Uracil"],"ans":0,"exp":"In DNA, adenine pairs with thymine, and cytosine pairs with guanine, held together by hydrogen bonds."},{"q":"What is the main function of RNA in a cell?","ch":["To store all of the cell's genetic information permanently","To provide energy for the cell","To form the cell membrane","To help carry out the instructions in DNA, such as building proteins"],"ans":3,"exp":"RNA helps translate the genetic instructions stored in DNA, playing a key role in building proteins."},{"q":"Which base replaces thymine in RNA?","ch":["Adenine","Guanine","Uracil","Cytosine"],"ans":2,"exp":"RNA contains uracil instead of the thymine found in DNA."},{"q":"What are the building blocks of DNA and RNA called?","ch":["Nucleotides","Amino acids","Fatty acids","Monosaccharides"],"ans":0,"exp":"DNA and RNA are polymers made of repeating subunits called nucleotides."},{"q":"Which best describes the structural difference between DNA and RNA?","ch":["DNA is single-stranded and RNA is double-stranded","DNA is typically double-stranded and RNA is typically single-stranded","DNA and RNA have identical structures","RNA contains deoxyribose while DNA contains ribose"],"ans":1,"exp":"DNA usually exists as a double-stranded helix, while RNA is usually single-stranded."}]},
{"id":"fls05","cat":"Life Sciences","title":"Basic Genetics — Mendelian Inheritance","diff":"Medium","qs":[{"q":"Who is known as the 'father of genetics' for his experiments with pea plants?","ch":["Charles Darwin","Gregor Mendel","James Watson","Rosalind Franklin"],"ans":1,"exp":"Gregor Mendel's pea plant experiments in the 1800s established the basic laws of inheritance."},{"q":"What is an allele?","ch":["A different version of a gene","A type of chromosome","A whole set of genes in an organism","The physical appearance of an organism"],"ans":0,"exp":"An allele is one of two or more alternative versions of a gene, such as different alleles for flower color."},{"q":"In genetics, what does 'genotype' refer to?","ch":["The physical, observable traits of an organism","An organism's environment","The number of chromosomes an organism has","The genetic makeup (allele combination) of an organism"],"ans":3,"exp":"Genotype describes the specific combination of alleles an organism carries for a trait."},{"q":"If a plant has one dominant allele (T) for tallness and one recessive allele (t) for shortness, what is its phenotype?","ch":["Short","Half tall and half short","Tall, because the dominant allele is expressed","Neither tall nor short"],"ans":2,"exp":"When a dominant allele is present, its trait is expressed in the phenotype, masking the recessive allele."},{"q":"A cross between two heterozygous parents (Tt x Tt) is expected to produce what phenotype ratio in offspring?","ch":["3 dominant : 1 recessive","1 dominant : 1 recessive","All dominant","All recessive"],"ans":0,"exp":"A Tt x Tt cross typically yields a 3:1 ratio of dominant to recessive phenotypes in the offspring."},{"q":"What term describes an organism with two identical alleles for a trait (e.g., TT or tt)?","ch":["Heterozygous","Homozygous","Hybrid","Codominant"],"ans":1,"exp":"Homozygous describes having two identical alleles for a given gene, either both dominant or both recessive."},{"q":"A Punnett square is a tool used to:","ch":["Measure the size of chromosomes","Sequence an organism's entire genome","Predict the possible genotype combinations of offspring from a genetic cross","Determine the age of an organism"],"ans":2,"exp":"Punnett squares help predict the probability of different genotype and phenotype combinations resulting from a cross."},{"q":"Mendel's law of segregation states that:","ch":["Traits always blend together in offspring","All alleles are dominant","Genes for different traits are always inherited together","The two alleles for a gene separate during the formation of gametes"],"ans":3,"exp":"The law of segregation states that allele pairs separate during gamete formation, so each gamete carries only one allele per gene."}]},
{"id":"fls06","cat":"Life Sciences","title":"Photosynthesis Basics","diff":"Easy","qs":[{"q":"What is the overall purpose of photosynthesis?","ch":["To break down glucose for energy","To release carbon dioxide into the air","To convert light energy into chemical energy (glucose)","To produce heat for the plant"],"ans":2,"exp":"Photosynthesis converts light energy from the sun into chemical energy stored in glucose."},{"q":"Which organelle is the primary site of photosynthesis in plant cells?","ch":["Mitochondrion","Nucleus","Ribosome","Chloroplast"],"ans":3,"exp":"Chloroplasts contain chlorophyll and are the organelles where photosynthesis takes place."},{"q":"Which pigment gives plants their green color and absorbs light for photosynthesis?","ch":["Chlorophyll","Melanin","Hemoglobin","Carotene"],"ans":0,"exp":"Chlorophyll absorbs light energy, mainly in the red and blue wavelengths, and reflects green light, giving plants their color."},{"q":"What are the raw materials (reactants) needed for photosynthesis?","ch":["Glucose and oxygen","Carbon dioxide and water","Nitrogen and water","Oxygen and nitrogen"],"ans":1,"exp":"Photosynthesis requires carbon dioxide from the air and water absorbed by the roots, along with light energy."},{"q":"What are the products of photosynthesis?","ch":["Carbon dioxide and water","Nitrogen and glucose","Water and carbon dioxide","Glucose and oxygen"],"ans":3,"exp":"Photosynthesis produces glucose, which the plant uses for energy, and oxygen, which is released as a byproduct."},{"q":"Which form of energy is captured and converted during photosynthesis?","ch":["Nuclear energy","Light energy","Sound energy","Electrical energy"],"ans":1,"exp":"Photosynthesis captures light energy from the sun and converts it into stored chemical energy."},{"q":"What gas do plants take in from the atmosphere to use in photosynthesis?","ch":["Oxygen","Nitrogen","Carbon dioxide","Hydrogen"],"ans":2,"exp":"Plants absorb carbon dioxide through tiny pores called stomata to use in building glucose."},{"q":"Which simple word equation correctly summarizes photosynthesis?","ch":["Carbon dioxide + water + light energy → glucose + oxygen","Glucose + oxygen → carbon dioxide + water + energy","Glucose → carbon dioxide + light energy","Oxygen + water → glucose + carbon dioxide"],"ans":0,"exp":"Photosynthesis combines carbon dioxide, water, and light energy to produce glucose and release oxygen."}]},
{"id":"fls07","cat":"Life Sciences","title":"Cellular Respiration Basics","diff":"Easy","qs":[{"q":"What is the main purpose of cellular respiration?","ch":["To break down glucose and release usable energy (ATP)","To make glucose from carbon dioxide","To produce chlorophyll","To store DNA"],"ans":0,"exp":"Cellular respiration breaks down glucose to release energy that cells store and use in the form of ATP."},{"q":"Which organelle is often called the 'powerhouse of the cell' because it is the main site of cellular respiration?","ch":["Chloroplast","Mitochondrion","Nucleus","Ribosome"],"ans":1,"exp":"Mitochondria carry out most of the reactions of cellular respiration, producing ATP for the cell."},{"q":"What are the reactants (starting materials) of cellular respiration?","ch":["Carbon dioxide and water","Glucose and carbon dioxide","Glucose and oxygen","Water and oxygen"],"ans":2,"exp":"Cellular respiration uses glucose and oxygen to release energy for the cell."},{"q":"What are the products of cellular respiration?","ch":["Glucose and oxygen","Chlorophyll and sunlight","Nitrogen and water","Carbon dioxide, water, and energy (ATP)"],"ans":3,"exp":"Cellular respiration produces carbon dioxide and water as waste, along with usable energy in the form of ATP."},{"q":"Cellular respiration can be thought of as roughly the opposite process of:","ch":["Digestion","Photosynthesis","Excretion","Circulation"],"ans":1,"exp":"Photosynthesis stores energy in glucose using carbon dioxide and water, while cellular respiration releases that energy, producing carbon dioxide and water."},{"q":"What molecule serves as the main energy currency produced by cellular respiration?","ch":["DNA","Glucose","Chlorophyll","ATP"],"ans":3,"exp":"ATP is the molecule cells use to store and transfer usable energy for cellular activities."},{"q":"Which type of cells carry out cellular respiration?","ch":["Nearly all living cells, including plant and animal cells","Only plant cells","Only muscle cells","Only bacterial cells"],"ans":0,"exp":"Cellular respiration occurs in nearly all living cells, both plant and animal, to produce energy."},{"q":"When you exhale, the carbon dioxide you release is mainly a waste product of:","ch":["Photosynthesis","Digestion","Cellular respiration","Blood clotting"],"ans":2,"exp":"Carbon dioxide is a waste product generated when cells break down glucose during cellular respiration."}]},
{"id":"fls08","cat":"Life Sciences","title":"Human Body Systems Overview","diff":"Easy","qs":[{"q":"Which body system is primarily responsible for transporting oxygen and nutrients throughout the body?","ch":["Digestive system","Nervous system","Skeletal system","Circulatory system"],"ans":3,"exp":"The circulatory system uses the heart and blood vessels to transport oxygen, nutrients, and waste throughout the body."},{"q":"Which body system breaks down food into nutrients the body can absorb?","ch":["Respiratory system","Excretory system","Digestive system","Muscular system"],"ans":2,"exp":"The digestive system mechanically and chemically breaks down food so nutrients can be absorbed into the body."},{"q":"Which body system controls and coordinates the body's activities using electrical signals?","ch":["Endocrine system","Nervous system","Immune system","Skeletal system"],"ans":1,"exp":"The nervous system uses electrical and chemical signals through neurons to control and coordinate body activities."},{"q":"Which body system is responsible for gas exchange, bringing oxygen in and removing carbon dioxide?","ch":["Respiratory system","Circulatory system","Digestive system","Muscular system"],"ans":0,"exp":"The respiratory system, through the lungs, exchanges oxygen and carbon dioxide with the air."},{"q":"Which system provides structural support and protects internal organs using bones?","ch":["Muscular system","Nervous system","Skeletal system","Endocrine system"],"ans":2,"exp":"The skeletal system's bones give the body structure and protect vital organs like the brain and heart."},{"q":"Which body system works with the skeletal system to produce movement?","ch":["Muscular system","Digestive system","Excretory system","Respiratory system"],"ans":0,"exp":"Muscles attach to bones and contract to produce body movement, working together with the skeletal system."},{"q":"Which system defends the body against pathogens such as bacteria and viruses?","ch":["Circulatory system","Digestive system","Skeletal system","Immune system"],"ans":3,"exp":"The immune system identifies and fights off harmful pathogens that enter the body."},{"q":"Which system uses hormones released into the blood to regulate body processes over time?","ch":["Nervous system","Endocrine system","Muscular system","Skeletal system"],"ans":1,"exp":"The endocrine system releases hormones into the bloodstream to regulate processes like growth and metabolism."}]},
{"id":"fls09","cat":"Life Sciences","title":"The Digestive System","diff":"Easy","qs":[{"q":"Where does mechanical and chemical digestion of food both begin?","ch":["The stomach","The mouth","The small intestine","The large intestine"],"ans":1,"exp":"Chewing begins mechanical digestion, and saliva contains enzymes that start chemical digestion, both in the mouth."},{"q":"Which organ produces most stomach acid to help break down food and kill bacteria?","ch":["Liver","Pancreas","Stomach","Gallbladder"],"ans":2,"exp":"The stomach lining produces hydrochloric acid, which helps break down food and destroy harmful bacteria."},{"q":"Where does most nutrient absorption into the bloodstream occur?","ch":["Small intestine","Large intestine","Esophagus","Stomach"],"ans":0,"exp":"The small intestine's large surface area, lined with villi, allows most nutrient absorption to happen there."},{"q":"What is the main function of the large intestine?","ch":["Absorbing most nutrients","Producing digestive enzymes","Breaking down proteins with acid","Absorbing water and forming solid waste"],"ans":3,"exp":"The large intestine mainly absorbs water from indigestible material and compacts the remaining waste for elimination."},{"q":"Which organ produces bile, which helps digest fats?","ch":["Pancreas","Stomach","Liver","Esophagus"],"ans":2,"exp":"The liver produces bile, which is stored in the gallbladder and helps break down fats in the small intestine."},{"q":"What is the tube called that carries food from the mouth to the stomach?","ch":["Trachea","Esophagus","Bronchus","Larynx"],"ans":1,"exp":"The esophagus is the muscular tube that moves swallowed food from the mouth down to the stomach."},{"q":"Which organ produces enzymes that help digest carbohydrates, proteins, and fats in the small intestine?","ch":["Gallbladder","Large intestine","Stomach","Pancreas"],"ans":3,"exp":"The pancreas releases digestive enzymes into the small intestine to help break down carbohydrates, proteins, and fats."},{"q":"What is peristalsis?","ch":["Wave-like muscle contractions that move food through the digestive tract","The absorption of nutrients","The production of stomach acid","The breakdown of fats by bile"],"ans":0,"exp":"Peristalsis is the rhythmic squeezing of muscles that pushes food along the digestive tract."}]},
{"id":"fls10","cat":"Life Sciences","title":"The Circulatory System & Blood","diff":"Easy","qs":[{"q":"What is the main function of the circulatory system?","ch":["To transport blood, nutrients, oxygen, and waste throughout the body","To digest food","To produce hormones","To filter air"],"ans":0,"exp":"The circulatory system moves blood carrying oxygen, nutrients, and waste products throughout the body."},{"q":"Which chamber of the heart pumps oxygen-rich blood out to the rest of the body?","ch":["Right atrium","Right ventricle","Left atrium","Left ventricle"],"ans":3,"exp":"The left ventricle is the heart's strongest chamber, pumping oxygen-rich blood out to the entire body."},{"q":"Which blood vessels carry blood away from the heart?","ch":["Veins","Arteries","Capillaries only","Lymph vessels"],"ans":1,"exp":"Arteries carry blood away from the heart, usually under higher pressure than veins."},{"q":"Which blood cells are primarily responsible for carrying oxygen throughout the body?","ch":["White blood cells","Platelets","Red blood cells","Plasma cells"],"ans":2,"exp":"Red blood cells contain hemoglobin, a protein that binds oxygen and carries it through the bloodstream."},{"q":"Which component of blood helps the blood clot to stop bleeding?","ch":["Red blood cells","White blood cells","Plasma","Platelets"],"ans":3,"exp":"Platelets are small cell fragments that gather at a wound site and help form clots to stop bleeding."},{"q":"Which type of blood vessel allows exchange of oxygen, nutrients, and waste with body tissues?","ch":["Capillaries","Arteries","Veins","Aorta"],"ans":0,"exp":"Capillaries have thin walls that allow oxygen, nutrients, and waste to pass between blood and body tissues."},{"q":"Which blood vessels carry blood back toward the heart?","ch":["Arteries only","Capillaries","Veins","Aorta"],"ans":2,"exp":"Veins return blood to the heart, generally under lower pressure than arteries."},{"q":"What is the liquid, straw-colored part of blood that carries cells, nutrients, and waste called?","ch":["Hemoglobin","Plasma","Marrow","Serum only"],"ans":1,"exp":"Plasma is the liquid portion of blood that carries blood cells, nutrients, hormones, and waste products."}]},
{"id":"fls11","cat":"Life Sciences","title":"The Respiratory System","diff":"Easy","qs":[{"q":"Where does gas exchange (oxygen and carbon dioxide) actually take place in the lungs?","ch":["Trachea","Bronchi","Alveoli (tiny air sacs)","Larynx"],"ans":2,"exp":"Alveoli are tiny, thin-walled air sacs where oxygen and carbon dioxide are exchanged with the blood."},{"q":"What is the main muscle involved in breathing that separates the chest and abdominal cavities?","ch":["Bicep","Diaphragm","Trapezius","Heart"],"ans":1,"exp":"The diaphragm is the dome-shaped muscle below the lungs that contracts and relaxes to drive breathing."},{"q":"What is the common name for the 'windpipe' that carries air toward the lungs?","ch":["Esophagus","Bronchiole","Larynx","Trachea"],"ans":3,"exp":"The trachea, or windpipe, carries air from the throat down toward the bronchi and lungs."},{"q":"During inhalation, what happens to the diaphragm?","ch":["It contracts and moves downward","It relaxes and moves upward","It stops moving entirely","It contracts and moves upward"],"ans":0,"exp":"During inhalation, the diaphragm contracts and flattens downward, expanding the chest cavity so air flows in."},{"q":"What gas do humans primarily need to take in through breathing to survive?","ch":["Carbon dioxide","Oxygen","Nitrogen","Helium"],"ans":1,"exp":"Cells need oxygen to carry out cellular respiration and produce usable energy."},{"q":"The trachea branches into two smaller tubes that lead into the lungs called:","ch":["Alveoli","Capillaries","Bronchi","Cilia"],"ans":2,"exp":"The trachea splits into the left and right bronchi, which carry air into each lung."},{"q":"What waste gas does the body primarily remove through exhalation?","ch":["Carbon dioxide","Oxygen","Nitrogen","Water only"],"ans":0,"exp":"Carbon dioxide, a waste product of cellular respiration, is removed from the blood and exhaled from the lungs."},{"q":"Alveoli are surrounded by a dense network of tiny blood vessels called:","ch":["Veins","Arteries","Ventricles","Capillaries"],"ans":3,"exp":"Capillaries surround the alveoli, allowing oxygen and carbon dioxide to diffuse between air and blood."}]},
{"id":"fls12","cat":"Life Sciences","title":"The Nervous System Basics","diff":"Easy","qs":[{"q":"What are the two main parts of the central nervous system?","ch":["Brain and nerves","Spinal cord and nerves","Nerves and muscles","Brain and spinal cord"],"ans":3,"exp":"The central nervous system consists of the brain and spinal cord, which process and relay information."},{"q":"What is the basic functional cell of the nervous system called?","ch":["Neuron","Neutron","Erythrocyte","Osteocyte"],"ans":0,"exp":"Neurons are specialized cells that transmit electrical and chemical signals throughout the nervous system."},{"q":"Which part of the neuron receives signals from other neurons?","ch":["Axon","Cell body only","Dendrites","Myelin sheath"],"ans":2,"exp":"Dendrites are branch-like extensions of a neuron that receive incoming signals from other neurons."},{"q":"What is the small gap between two neurons where signals are transmitted called?","ch":["Node of Ranvier","Synapse","Axon terminal","Ventricle"],"ans":1,"exp":"The synapse is the small gap between neurons across which chemical signals, called neurotransmitters, pass."},{"q":"Which part of the brain is primarily responsible for coordinating balance and muscle coordination?","ch":["Cerebellum","Cerebrum","Medulla","Hypothalamus"],"ans":0,"exp":"The cerebellum, located at the back of the brain, coordinates balance, posture, and fine muscle movements."},{"q":"A reflex, such as pulling your hand away from something hot, is controlled mainly by the:","ch":["Cerebrum","Endocrine system","Cerebellum","Spinal cord (a reflex arc)"],"ans":3,"exp":"Many reflexes are processed directly by the spinal cord in a quick reflex arc, without needing to involve the brain first."},{"q":"Which part of the nervous system includes the nerves that branch out from the brain and spinal cord to the rest of the body?","ch":["Central nervous system","Peripheral nervous system","Endocrine system","Skeletal system"],"ans":1,"exp":"The peripheral nervous system consists of nerves branching from the central nervous system to the rest of the body."},{"q":"Which largest part of the brain is responsible for higher functions like thinking, memory, and voluntary movement?","ch":["Cerebellum","Medulla oblongata","Cerebrum","Spinal cord"],"ans":2,"exp":"The cerebrum is the largest part of the brain and handles higher-level functions such as thought, memory, and voluntary movement."}]},
{"id":"fls13","cat":"Life Sciences","title":"The Skeletal System","diff":"Easy","qs":[{"q":"About how many bones does an adult human skeleton typically have?","ch":["106","206","306","406"],"ans":1,"exp":"An adult human skeleton typically has 206 bones, fewer than a baby's due to some bones fusing together during growth."},{"q":"Which of the following is NOT a main function of the skeletal system?","ch":["Supporting the body's structure","Protecting internal organs","Storing minerals such as calcium","Pumping blood throughout the body"],"ans":3,"exp":"Pumping blood is the job of the heart and circulatory system, not the skeletal system."},{"q":"Where in the body are most blood cells produced?","ch":["The liver","The lungs","Bone marrow","The stomach"],"ans":2,"exp":"Bone marrow, found inside many bones, is the primary site where red and white blood cells are produced."},{"q":"What type of connective tissue connects bone to bone at a joint?","ch":["Ligaments","Tendons","Cartilage only","Muscle fibers"],"ans":0,"exp":"Ligaments are tough connective tissues that connect one bone to another bone at a joint."},{"q":"Which of the following bones is part of the axial skeleton?","ch":["Femur","Humerus","Skull","Radius"],"ans":2,"exp":"The skull is part of the axial skeleton, which also includes the spine and rib cage, forming the body's central axis."},{"q":"What type of joint is the shoulder, allowing movement in almost all directions?","ch":["Hinge joint","Pivot joint","Fixed joint","Ball-and-socket joint"],"ans":3,"exp":"The shoulder is a ball-and-socket joint, allowing a wide range of motion in multiple directions."},{"q":"What is the largest bone in the human body?","ch":["Femur (thigh bone)","Humerus","Tibia","Radius"],"ans":0,"exp":"The femur, or thigh bone, is the longest and largest bone in the human body."},{"q":"What flexible connective tissue cushions joints and makes up structures like the ear and nose tip?","ch":["Bone","Cartilage","Tendon","Ligament"],"ans":1,"exp":"Cartilage is a flexible connective tissue that cushions joints and gives shape to structures like the ear and nose."}]},
{"id":"fls14","cat":"Life Sciences","title":"The Muscular System","diff":"Easy","qs":[{"q":"Which type of muscle is attached to bones and is under voluntary (conscious) control?","ch":["Skeletal muscle","Smooth muscle","Cardiac muscle","Involuntary muscle"],"ans":0,"exp":"Skeletal muscles attach to bones via tendons and are consciously controlled to produce movement."},{"q":"Which type of muscle makes up the walls of the heart?","ch":["Skeletal muscle","Smooth muscle","Cardiac muscle","Voluntary muscle"],"ans":2,"exp":"Cardiac muscle is the specialized, involuntary muscle tissue that makes up the walls of the heart."},{"q":"Which type of muscle is found in the walls of organs like the stomach and intestines and works involuntarily?","ch":["Skeletal muscle","Smooth muscle","Cardiac muscle","Striated voluntary muscle"],"ans":1,"exp":"Smooth muscle lines the walls of internal organs and contracts involuntarily, such as during digestion."},{"q":"What connective tissue attaches muscle to bone?","ch":["Ligament","Cartilage","Synovial fluid","Tendon"],"ans":3,"exp":"Tendons are tough connective tissues that attach muscles to bones, allowing muscle contractions to move the skeleton."},{"q":"When a muscle contracts to bend a joint, what is this type of muscle action called?","ch":["Extension","Flexion","Relaxation","Rotation"],"ans":1,"exp":"Flexion refers to the bending motion at a joint caused by muscle contraction, such as bending the elbow."},{"q":"Skeletal muscles typically work in pairs because a muscle can only:","ch":["Pull (contract), not push","Push, not pull","Stretch on its own","Contract and push equally"],"ans":0,"exp":"Muscles can only actively pull by contracting; they cannot push, so opposing muscle pairs are needed to move a joint both ways."},{"q":"Which of these is an example of an involuntary muscle action?","ch":["Waving your hand","Kicking a ball","Writing your name","Your heart beating"],"ans":3,"exp":"The heartbeat is controlled by cardiac muscle, which contracts involuntarily without conscious effort."},{"q":"What is the term for a muscle contraction that generates force even though the muscle does not visibly shorten (e.g., holding a heavy object still)?","ch":["Isotonic contraction","Reflex contraction","Isometric contraction","Peristaltic contraction"],"ans":2,"exp":"An isometric contraction generates muscular tension and force without a noticeable change in the muscle's length."}]},
{"id":"fls15","cat":"Life Sciences","title":"The Immune System Basics","diff":"Easy","qs":[{"q":"What is the main job of the immune system?","ch":["To pump blood through the body","To digest nutrients","To defend the body against pathogens like bacteria and viruses","To control muscle movement"],"ans":2,"exp":"The immune system's main role is identifying and defending the body against harmful pathogens."},{"q":"Which white blood cells produce antibodies to help fight specific pathogens?","ch":["Lymphocytes (a type of white blood cell)","Red blood cells","Platelets","Neurons"],"ans":0,"exp":"Lymphocytes, including B cells, are white blood cells that produce antibodies targeting specific pathogens."},{"q":"What is a pathogen?","ch":["A type of blood cell","A hormone that regulates the body","An antibody","A microorganism, such as a bacterium or virus, that causes disease"],"ans":3,"exp":"A pathogen is any microorganism, like certain bacteria or viruses, capable of causing disease."},{"q":"What is the skin's role in the immune system?","ch":["It produces antibodies","It acts as a physical barrier that keeps most pathogens out of the body","It filters pathogens from the blood","It produces white blood cells"],"ans":1,"exp":"Skin serves as the body's first line of defense, forming a physical barrier that blocks many pathogens from entering."},{"q":"How do vaccines help protect the body against disease?","ch":["They directly kill pathogens already in the body","They replace damaged blood cells","They remove all bacteria from the body","They expose the immune system to a harmless form of a pathogen so it can learn to recognize and fight it"],"ans":3,"exp":"Vaccines train the immune system to recognize a pathogen safely, so it can respond quickly if exposed to the real pathogen later."},{"q":"What is a fever an example of?","ch":["A pathogen invading the body","The body's immune response trying to fight off an infection","A sign of a broken bone","A digestive process"],"ans":1,"exp":"A fever raises body temperature as part of the immune response, which can help slow the growth of some pathogens."},{"q":"Which blood component increases in number when the body is fighting an infection?","ch":["White blood cells","Red blood cells","Platelets only","Plasma proteins only"],"ans":0,"exp":"White blood cell counts typically rise during an infection as the body mobilizes to fight off the pathogen."},{"q":"Antibodies are proteins that specifically:","ch":["Carry oxygen throughout the body","Clot the blood","Recognize and help neutralize specific pathogens or foreign substances","Contract to move the skeleton"],"ans":2,"exp":"Antibodies are proteins produced by the immune system that recognize and bind to specific pathogens to help neutralize them."}]},
{"id":"fls16","cat":"Life Sciences","title":"The Endocrine System Basics","diff":"Medium","qs":[{"q":"What do endocrine glands release directly into the bloodstream to regulate body processes?","ch":["Enzymes","Hormones","Antibodies","Neurotransmitters"],"ans":1,"exp":"Endocrine glands secrete hormones directly into the bloodstream to regulate processes throughout the body."},{"q":"Which gland is often called the 'master gland' because it controls many other endocrine glands?","ch":["Thyroid gland","Adrenal gland","Pituitary gland","Pancreas"],"ans":2,"exp":"The pituitary gland is called the 'master gland' because its hormones regulate the activity of several other endocrine glands."},{"q":"Which gland produces insulin, a hormone that helps regulate blood sugar levels?","ch":["Thyroid gland","Pituitary gland","Adrenal gland","Pancreas"],"ans":3,"exp":"The pancreas produces insulin, which helps cells absorb glucose from the blood and lowers blood sugar levels."},{"q":"Which gland releases adrenaline during the 'fight or flight' stress response?","ch":["Adrenal glands","Thyroid gland","Pancreas","Pituitary gland"],"ans":0,"exp":"The adrenal glands release adrenaline (epinephrine) in response to stress, preparing the body for quick action."},{"q":"Which gland in the neck produces hormones that regulate metabolism?","ch":["Thyroid gland","Pancreas","Adrenal gland","Pituitary gland"],"ans":0,"exp":"The thyroid gland, located in the neck, produces hormones that regulate the body's metabolic rate."},{"q":"Compared to the nervous system, hormone signals from the endocrine system typically act:","ch":["Faster and last a shorter time","Instantaneously, like a nerve impulse","Only within a single organ","More slowly but tend to have longer-lasting effects"],"ans":3,"exp":"Hormones generally travel through the bloodstream and act more slowly than nerve impulses, but their effects often last longer."},{"q":"Which of these is a hormone rather than an organ?","ch":["Pancreas","Thyroid gland","Insulin","Pituitary gland"],"ans":2,"exp":"Insulin is a hormone produced by the pancreas; the others listed are glands, not hormones."},{"q":"What happens if the pancreas does not produce enough insulin?","ch":["Body temperature drops dangerously","Blood sugar levels can become too high, as in diabetes","Bones become brittle","Heart rate slows permanently"],"ans":1,"exp":"Without enough insulin, cells cannot properly absorb glucose from the blood, causing blood sugar levels to rise, as seen in diabetes."}]},
{"id":"fls17","cat":"Life Sciences","title":"Homeostasis & Feedback Loops","diff":"Medium","qs":[{"q":"What does the term 'homeostasis' refer to?","ch":["The process of digestion","The production of new cells","The exchange of gases in the lungs","The maintenance of a stable internal environment despite external changes"],"ans":3,"exp":"Homeostasis is the body's ability to maintain a stable internal environment, such as temperature and pH, despite outside changes."},{"q":"Shivering when you are cold is an example of the body trying to:","ch":["Lower its internal temperature","Maintain homeostasis by generating heat to raise body temperature","Increase blood sugar","Remove waste products"],"ans":1,"exp":"Shivering generates heat through rapid muscle contractions, helping raise body temperature back toward its normal set point."},{"q":"In a negative feedback loop, when a change is detected, the body's response typically:","ch":["Counteracts the change to bring the variable back to normal","Amplifies the change further","Has no effect on the variable","Stops all bodily functions"],"ans":0,"exp":"Negative feedback loops work to reverse a detected change and restore the variable to its normal range."},{"q":"Which of the following is a classic example of a negative feedback loop in the human body?","ch":["Blood clotting during childbirth contractions","Nerve impulses speeding up during exercise","Regulation of blood sugar by insulin and glucagon","Growth of hair over time"],"ans":2,"exp":"Insulin and glucagon work together in a negative feedback loop to keep blood sugar levels within a normal range."},{"q":"Positive feedback loops differ from negative feedback loops because they:","ch":["Always maintain a constant internal state","Are more common than negative feedback loops in daily body regulation","Amplify a change rather than reverse it, such as during childbirth contractions","Only occur in plants"],"ans":2,"exp":"Positive feedback loops intensify a change rather than reversing it, as seen with the strengthening contractions during childbirth."},{"q":"Sweating when you are overheated is a homeostatic response that helps:","ch":["Cool the body down through evaporation","Raise body temperature further","Increase heart rate only","Slow down digestion"],"ans":0,"exp":"Sweat evaporating from the skin removes heat from the body, helping cool it back toward a normal temperature."},{"q":"Which body system, working with the nervous system, plays a major role in maintaining homeostasis through hormones?","ch":["Skeletal system","Endocrine system","Muscular system","Integumentary system alone"],"ans":1,"exp":"The endocrine system releases hormones that help regulate and maintain homeostasis alongside the nervous system."},{"q":"Why is homeostasis important for living organisms?","ch":["It allows organisms to change species over time","It only matters for plants, not animals","It causes disease if maintained too well","It keeps internal conditions (like temperature and pH) stable enough for cells to function properly"],"ans":3,"exp":"Cells and enzymes function best within narrow ranges of temperature, pH, and other conditions, so homeostasis keeps these stable."}]},
{"id":"fls18","cat":"Life Sciences","title":"Ecology Basics — Ecosystems & Biomes","diff":"Easy","qs":[{"q":"What is an ecosystem?","ch":["A community of living organisms interacting with each other and their physical environment","Only the living organisms in an area","Only the nonliving parts of an environment","A single species living alone"],"ans":0,"exp":"An ecosystem includes both the living organisms (biotic factors) and the nonliving environment (abiotic factors) in an area, interacting together."},{"q":"What term describes all the members of one species living in the same area?","ch":["Ecosystem","Community","Biome","Population"],"ans":3,"exp":"A population refers to all individuals of the same species living in a particular area at the same time."},{"q":"What term describes all the different populations of different species living and interacting in the same area?","ch":["Biome","Population","Community","Habitat"],"ans":2,"exp":"A community consists of all the different species populations that live and interact together in one area."},{"q":"What is a biome?","ch":["A single organism's home","A large region characterized by a specific climate and community of plants and animals, such as a desert or rainforest","A single food chain","A type of cell"],"ans":1,"exp":"A biome is a large geographic region defined by its climate and the characteristic organisms that live there, like deserts or rainforests."},{"q":"Which of the following is an example of an abiotic (nonliving) factor in an ecosystem?","ch":["Bacteria","Sunlight","Trees","Insects"],"ans":1,"exp":"Sunlight is a nonliving, or abiotic, factor that affects organisms in an ecosystem, unlike bacteria, trees, and insects, which are living things."},{"q":"A desert biome is generally characterized by:","ch":["High rainfall and dense forests","Constant freezing temperatures","Very low precipitation and sparse vegetation","Deep ocean water"],"ans":2,"exp":"Deserts are defined mainly by very low precipitation, resulting in sparse vegetation adapted to dry conditions."},{"q":"What is a habitat?","ch":["The total energy flow through an ecosystem","A group of different species","A single organism's genetic makeup","The specific place or environment where an organism naturally lives"],"ans":3,"exp":"A habitat is the natural environment where a particular organism typically lives and finds what it needs to survive."},{"q":"Which of these is considered a biotic (living) factor in an ecosystem?","ch":["A population of deer","Rainfall amount","Soil type","Average temperature"],"ans":0,"exp":"A population of deer is a living, or biotic, factor, while rainfall, soil type, and temperature are nonliving, abiotic factors."}]},
{"id":"fls19","cat":"Life Sciences","title":"Food Chains, Food Webs & Energy Flow","diff":"Easy","qs":[{"q":"What is the ultimate source of energy for almost all food chains on Earth?","ch":["Soil nutrients","Water","The sun","Oxygen in the atmosphere"],"ans":2,"exp":"Sunlight provides the energy that producers capture through photosynthesis, forming the base of almost all food chains."},{"q":"In a food chain, which organisms are called 'producers'?","ch":["Animals that eat only meat","Organisms like plants that make their own food through photosynthesis","Organisms that break down dead matter","Animals that eat both plants and animals"],"ans":1,"exp":"Producers, such as plants and algae, make their own food using photosynthesis and form the base of food chains."},{"q":"An organism that eats only plants is called a(n):","ch":["Herbivore","Carnivore","Omnivore","Decomposer"],"ans":0,"exp":"Herbivores are consumers that eat only plant material for energy."},{"q":"What role do decomposers, such as fungi and bacteria, play in an ecosystem?","ch":["They produce their own food using sunlight","They only eat other animals","They are always the largest organisms in a food chain","They break down dead organisms and waste, recycling nutrients back into the ecosystem"],"ans":3,"exp":"Decomposers break down dead organic matter, releasing nutrients back into the soil and ecosystem for producers to reuse."},{"q":"A food web differs from a single food chain because a food web:","ch":["Only shows producers","Contains no consumers","Is always simpler than a food chain","Shows multiple interconnected food chains and feeding relationships in an ecosystem"],"ans":3,"exp":"A food web combines many overlapping food chains, showing the more complex, realistic feeding relationships in an ecosystem."},{"q":"As energy moves from one trophic (feeding) level to the next in a food chain, the amount of usable energy available generally:","ch":["Decreases at each higher level","Increases at each higher level","Stays exactly the same","Doubles at each higher level"],"ans":0,"exp":"Much energy is lost as heat at each feeding level, so less usable energy is available to organisms higher up the food chain."},{"q":"Which of these is an example of a secondary consumer?","ch":["A plant","A fox that eats a rabbit that ate grass","A mushroom decomposing a log","Grass"],"ans":1,"exp":"A secondary consumer eats a primary consumer; here, the fox eats a rabbit (the primary consumer), which ate grass (the producer)."},{"q":"A pyramid of energy in an ecosystem is typically widest at the:","ch":["Top, showing top predators","Middle, showing secondary consumers","Bottom, showing producers","It is the same width throughout"],"ans":2,"exp":"Energy pyramids are widest at the base, representing producers, since they hold the most available energy in the ecosystem."}]},
{"id":"fls20","cat":"Life Sciences","title":"Classification & the Tree of Life","diff":"Easy","qs":[{"q":"What is taxonomy?","ch":["The study of cell structures","The science of classifying and naming living organisms","The study of ecosystems","The study of genetics"],"ans":1,"exp":"Taxonomy is the branch of science focused on classifying and naming living organisms based on shared characteristics."},{"q":"Who developed the modern system of naming organisms using two-part Latin names (binomial nomenclature)?","ch":["Carl Linnaeus","Charles Darwin","Gregor Mendel","Robert Hooke"],"ans":0,"exp":"Carl Linnaeus developed the binomial nomenclature system, giving each species a two-part Latin name."},{"q":"In binomial nomenclature, an organism's scientific name consists of its:","ch":["Kingdom and phylum","Class and order","Genus and species","Family and order"],"ans":2,"exp":"A scientific name is made of two parts: the genus name followed by the species name, such as Homo sapiens."},{"q":"From broadest to most specific, which is the correct order of the major taxonomic ranks?","ch":["Species, Genus, Family, Kingdom, Phylum, Class, Order, Domain","Kingdom, Domain, Phylum, Class, Order, Family, Genus, Species","Genus, Species, Family, Order, Class, Phylum, Kingdom, Domain","Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species"],"ans":3,"exp":"The standard order from broadest to most specific is Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species."},{"q":"How many kingdoms are traditionally recognized in many biology courses (e.g., Animalia, Plantae, Fungi, Protista, and Bacteria/Monera)?","ch":["Five (or six, depending on the classification system used)","Two","Ten","Three"],"ans":0,"exp":"Many introductory biology courses teach a five- or six-kingdom system, including Animalia, Plantae, Fungi, Protista, and Bacteria (sometimes split further)."},{"q":"Which kingdom includes organisms like mushrooms, which absorb nutrients from their surroundings rather than making their own food?","ch":["Plantae","Animalia","Fungi","Protista"],"ans":2,"exp":"Fungi, such as mushrooms, absorb nutrients from their environment rather than photosynthesizing or ingesting food like animals."},{"q":"A 'tree of life' diagram is used to show:","ch":["The food chains in a single ecosystem","The parts of a single organism's body","The layers of the atmosphere","The evolutionary relationships and shared ancestry between different groups of organisms"],"ans":3,"exp":"A tree of life diagram illustrates how different groups of organisms are related through evolutionary history and shared ancestry."},{"q":"Which of these organisms belongs to the kingdom Plantae?","ch":["Mushroom","Oak tree","Human","E. coli bacterium"],"ans":1,"exp":"An oak tree is a plant, placing it in the kingdom Plantae, unlike fungi, animals, or bacteria."}]},
{"id":"fls21","cat":"Life Sciences","title":"Evolution & Natural Selection Basics","diff":"Easy","qs":[{"q":"Who is credited with developing the theory of evolution by natural selection?","ch":["Gregor Mendel","Charles Darwin","Louis Pasteur","Isaac Newton"],"ans":1,"exp":"Charles Darwin proposed the theory of evolution by natural selection after observing variation among species, notably during his voyage on the HMS Beagle."},{"q":"What is natural selection?","ch":["The process by which organisms with helpful traits survive and reproduce more successfully","The process of an organism changing its body during its lifetime","A method scientists use to classify organisms","The random mixing of genes during fertilization"],"ans":0,"exp":"Natural selection is the process where individuals with traits better suited to their environment tend to survive and pass those traits to offspring."},{"q":"A trait that helps an organism survive and reproduce in its environment is called a(n)","ch":["Mutation","Adaptation","Extinction","Fossil"],"ans":1,"exp":"An adaptation is an inherited trait that increases an organism's chance of survival and reproduction in its environment."},{"q":"What is the main source of new genetic variation in a population?","ch":["Migration only","Mutation","Natural selection itself","Camouflage"],"ans":1,"exp":"Mutations are changes in DNA that create new versions of genes, providing the raw material for genetic variation."},{"q":"Which of these is the best example of natural selection in action?","ch":["A dog learning to sit for a treat","Peppered moths becoming darker in color as pollution increased, since darker moths were better camouflaged","A person getting a suntan in the summer","A plant bending toward sunlight"],"ans":1,"exp":"The peppered moth example shows how a population's traits shifted over generations because moths that blended in with darker, soot-covered trees survived predation better."},{"q":"What term describes the process by which one species splits into two or more distinct species over time?","ch":["Speciation","Domestication","Hibernation","Fertilization"],"ans":0,"exp":"Speciation occurs when populations become so genetically different, often due to isolation, that they can no longer interbreed and form separate species."},{"q":"Fossils are important to the study of evolution because they","ch":["Prove that all species are unrelated","Show a record of how organisms have changed over long periods of time","Are always found in living organisms","Only form in aquatic environments"],"ans":1,"exp":"Fossils provide a physical record of organisms from the past, allowing scientists to trace how species have changed over millions of years."},{"q":"Bat wings and human arms have similar bone structures despite different functions. These are called","ch":["Analogous structures","Vestigial structures","Homologous structures","Convergent structures"],"ans":2,"exp":"Homologous structures share a similar underlying anatomy inherited from a common ancestor, even though they may be used for different purposes."}]},
{"id":"fls22","cat":"Life Sciences","title":"Plant Biology Basics","diff":"Easy","qs":[{"q":"What process do plants use to convert sunlight into chemical energy?","ch":["Respiration","Photosynthesis","Transpiration","Fermentation"],"ans":1,"exp":"Photosynthesis is the process by which plants use sunlight, water, and carbon dioxide to produce glucose and oxygen."},{"q":"Which plant structure absorbs water and minerals from the soil?","ch":["Leaves","Stem","Roots","Flowers"],"ans":2,"exp":"Roots anchor the plant and absorb water and dissolved minerals from the soil."},{"q":"What gas do plants release as a byproduct of photosynthesis?","ch":["Carbon dioxide","Nitrogen","Oxygen","Methane"],"ans":2,"exp":"During photosynthesis, plants release oxygen as a byproduct while converting carbon dioxide and water into glucose."},{"q":"Which pigment in plant cells captures light energy for photosynthesis?","ch":["Melanin","Chlorophyll","Hemoglobin","Keratin"],"ans":1,"exp":"Chlorophyll, found in chloroplasts, gives plants their green color and absorbs light energy used in photosynthesis."},{"q":"What is the primary function of a flower in a plant?","ch":["Photosynthesis","Water storage","Reproduction","Gas exchange"],"ans":2,"exp":"Flowers contain the reproductive structures of the plant and are involved in producing seeds through pollination and fertilization."},{"q":"What is transpiration?","ch":["The loss of water vapor from a plant's leaves","The absorption of sunlight by leaves","The process of seeds germinating","The movement of a plant's roots"],"ans":0,"exp":"Transpiration is the evaporation of water from small openings in the leaves, called stomata, which helps pull water up from the roots."},{"q":"Small pores on the underside of leaves that allow gas exchange are called","ch":["Xylem","Stomata","Petals","Nodules"],"ans":1,"exp":"Stomata are tiny openings, mainly on leaf surfaces, that allow carbon dioxide, oxygen, and water vapor to pass in and out of the plant."},{"q":"Which plant tissue is responsible for transporting water from the roots to the leaves?","ch":["Phloem","Xylem","Epidermis","Cortex"],"ans":1,"exp":"Xylem tissue transports water and dissolved minerals upward from the roots to the rest of the plant."}]},
{"id":"fls23","cat":"Life Sciences","title":"Basic Microbiology — Bacteria","diff":"Easy","qs":[{"q":"Bacteria are classified as which type of organism?","ch":["Multicellular eukaryotes","Unicellular prokaryotes","Viruses","Fungi"],"ans":1,"exp":"Bacteria are single-celled prokaryotic organisms, meaning they lack a nucleus and membrane-bound organelles."},{"q":"Which structure allows some bacteria to move?","ch":["Flagella","Chloroplasts","Mitochondria","Nucleus"],"ans":0,"exp":"Many bacteria have whip-like structures called flagella that rotate to propel the cell through liquid."},{"q":"What is the rigid outer layer that gives most bacterial cells their shape and protection called?","ch":["Cell membrane","Cytoplasm","Cell wall","Ribosome"],"ans":2,"exp":"The bacterial cell wall, often made of peptidoglycan, provides structural support and protects the cell."},{"q":"Bacteria that require oxygen to survive are called","ch":["Anaerobic","Aerobic","Autotrophic","Heterotrophic"],"ans":1,"exp":"Aerobic bacteria need oxygen to carry out cellular respiration and produce energy."},{"q":"How do most bacteria reproduce?","ch":["Meiosis","Sexual reproduction","Binary fission","Budding only"],"ans":2,"exp":"Most bacteria reproduce asexually through binary fission, where one cell divides into two identical daughter cells."},{"q":"Which of the following is an example of a helpful bacterium for humans?","ch":["Bacteria in the gut that aid digestion","Bacteria that cause strep throat","Bacteria that cause tuberculosis","Bacteria that cause food poisoning"],"ans":0,"exp":"Many bacteria living in the human gut help digest food, produce vitamins, and support the immune system."},{"q":"Medicines used to kill or stop the growth of bacteria are called","ch":["Antivirals","Vaccines","Antibiotics","Antihistamines"],"ans":2,"exp":"Antibiotics are drugs specifically designed to kill bacteria or prevent them from multiplying; they do not work against viruses."},{"q":"What shape describes a spherical bacterium?","ch":["Bacillus","Spirillum","Coccus","Vibrio"],"ans":2,"exp":"Coccus describes round or spherical-shaped bacteria, as opposed to rod-shaped (bacillus) or spiral-shaped (spirillum) bacteria."}]},
{"id":"fls24","cat":"Life Sciences","title":"Basic Virology — Viruses & Vaccines","diff":"Easy","qs":[{"q":"Are viruses considered living organisms?","ch":["Yes, they meet all criteria for life","No, they cannot reproduce without a host cell","Yes, but only in water","No, because they are too small to see"],"ans":1,"exp":"Viruses cannot carry out life processes like reproduction on their own; they must invade a host cell and use its machinery to make copies of themselves."},{"q":"What is the basic structure of a virus?","ch":["A cell wall and cytoplasm","Genetic material surrounded by a protein coat","A nucleus and mitochondria","Multiple organs working together"],"ans":1,"exp":"A virus consists of genetic material (DNA or RNA) enclosed in a protective protein coat called a capsid."},{"q":"How do viruses reproduce?","ch":["By binary fission like bacteria","By dividing their protein coat in half","By hijacking a host cell's machinery to make copies of themselves","By absorbing nutrients from soil"],"ans":2,"exp":"Viruses cannot reproduce on their own; they must infect a living host cell and use that cell's machinery to replicate."},{"q":"What is a vaccine designed to do?","ch":["Kill bacteria directly","Train the immune system to recognize a specific pathogen","Replace damaged cells","Provide nutrients to fight infection"],"ans":1,"exp":"Vaccines expose the immune system to a harmless piece or weakened form of a pathogen so it can learn to recognize and fight it quickly in the future."},{"q":"Which of these illnesses is caused by a virus, not bacteria?","ch":["Strep throat","Common cold","Tuberculosis","Salmonella food poisoning"],"ans":1,"exp":"The common cold is caused by viruses, most often rhinoviruses, whereas the other listed illnesses are caused by bacteria."},{"q":"Why are antibiotics ineffective against viral infections?","ch":["Antibiotics only work on plants","Antibiotics target structures and processes found in bacteria, not viruses","Viruses are too large for antibiotics to affect","Antibiotics only work in the bloodstream"],"ans":1,"exp":"Antibiotics work by disrupting bacterial structures like cell walls, which viruses do not have, so antibiotics have no effect on them."},{"q":"White blood cells that produce antibodies to fight infections are called","ch":["Red blood cells","Platelets","Lymphocytes","Neurons"],"ans":2,"exp":"Lymphocytes, a type of white blood cell, include B cells that produce antibodies to help the body fight off pathogens like viruses."},{"q":"What does it mean when a population achieves 'herd immunity' against a virus?","ch":["Every single person has been infected","Enough people are immune that the virus has difficulty spreading through the population","Only animals are immune, not humans","The virus has mutated to become harmless"],"ans":1,"exp":"Herd immunity occurs when a large enough portion of a population is immune, through vaccination or prior infection, making it hard for the disease to spread."}]},
{"id":"fls25","cat":"Life Sciences","title":"The Water Cycle & Biogeochemical Cycles","diff":"Easy","qs":[{"q":"What is the process called when water vapor turns into liquid water, forming clouds?","ch":["Evaporation","Condensation","Precipitation","Transpiration"],"ans":1,"exp":"Condensation occurs when water vapor cools and changes into tiny liquid droplets, forming clouds."},{"q":"What process describes water falling from clouds as rain, snow, or hail?","ch":["Precipitation","Runoff","Sublimation","Infiltration"],"ans":0,"exp":"Precipitation is any form of water, such as rain, snow, sleet, or hail, that falls from the atmosphere to the Earth's surface."},{"q":"Which process turns liquid water into water vapor using heat from the sun?","ch":["Condensation","Precipitation","Evaporation","Respiration"],"ans":2,"exp":"Evaporation occurs when the sun's energy heats liquid water, such as in oceans and lakes, turning it into water vapor that rises into the atmosphere."},{"q":"Plants release water vapor into the atmosphere through a process called","ch":["Photosynthesis","Transpiration","Germination","Pollination"],"ans":1,"exp":"Transpiration is the release of water vapor from small pores in plant leaves, contributing water to the atmosphere similarly to evaporation."},{"q":"In the carbon cycle, which process do plants use to remove carbon dioxide from the atmosphere?","ch":["Respiration","Combustion","Photosynthesis","Decomposition"],"ans":2,"exp":"Plants use photosynthesis to take in carbon dioxide from the air and convert it into glucose, storing the carbon in their tissues."},{"q":"Which process returns carbon dioxide to the atmosphere as living organisms break down glucose for energy?","ch":["Cellular respiration","Photosynthesis","Condensation","Nitrogen fixation"],"ans":0,"exp":"During cellular respiration, organisms break down glucose and release carbon dioxide as a byproduct back into the atmosphere."},{"q":"Bacteria that convert nitrogen gas in the air into a form plants can use are involved in","ch":["The water cycle","Nitrogen fixation","Photosynthesis","Transpiration"],"ans":1,"exp":"Nitrogen-fixing bacteria, often found in soil or plant root nodules, convert atmospheric nitrogen gas into compounds like ammonia that plants can absorb and use."},{"q":"Which of the following best describes runoff in the water cycle?","ch":["Water vapor rising into the atmosphere","Water soaking into the ground","Water flowing over land's surface into streams, rivers, and lakes","Water molecules splitting into hydrogen and oxygen"],"ans":2,"exp":"Runoff is precipitation that flows over the land's surface rather than soaking into the ground, eventually reaching streams, rivers, and larger bodies of water."}]},
{"id":"fls26","cat":"Life Sciences","title":"Basic Nutrition & Macronutrients","diff":"Easy","qs":[{"q":"Which macronutrient is the body's primary and quickest source of energy?","ch":["Protein","Vitamins","Water","Carbohydrates"],"ans":3,"exp":"Carbohydrates are broken down into glucose, which cells use as their primary and most readily available source of energy."},{"q":"Which macronutrient is most important for building and repairing muscle tissue?","ch":["Protein","Carbohydrates","Fiber","Sugar"],"ans":0,"exp":"Proteins are made of amino acids, which the body uses to build and repair tissues such as muscle."},{"q":"Which nutrient provides the most energy per gram?","ch":["Carbohydrates","Protein","Fat","Water"],"ans":2,"exp":"Fats provide about 9 calories per gram, more than double the roughly 4 calories per gram provided by carbohydrates or protein."},{"q":"Which of the following is considered a micronutrient rather than a macronutrient?","ch":["Protein","Fat","Carbohydrate","Vitamin C"],"ans":3,"exp":"Vitamins and minerals are micronutrients needed in small amounts, unlike macronutrients like protein, fat, and carbohydrates which are needed in larger quantities."},{"q":"What type of carbohydrate cannot be digested by the human body but aids digestion?","ch":["Fiber","Starch","Glucose","Sucrose"],"ans":0,"exp":"Dietary fiber passes through the digestive system largely undigested, helping move food through the intestines and supporting healthy digestion."},{"q":"Which of these is an example of a healthy unsaturated fat source?","ch":["Butter","Bacon grease","Olive oil","Lard"],"ans":2,"exp":"Olive oil is rich in unsaturated fats, which are generally considered healthier than the saturated fats found in butter, bacon grease, and lard."},{"q":"Which mineral is especially important for building strong bones and teeth?","ch":["Iron","Sodium","Potassium","Calcium"],"ans":3,"exp":"Calcium is a key mineral used to build and maintain strong bones and teeth throughout life."},{"q":"Which of the following best describes a 'balanced diet'?","ch":["Eating only fruits and vegetables","Eating a variety of foods that provide appropriate amounts of all necessary nutrients","Eating the same meal every day for consistency","Avoiding all fats and sugars completely"],"ans":1,"exp":"A balanced diet includes a variety of foods in the right proportions to supply the body with all the carbohydrates, proteins, fats, vitamins, and minerals it needs."}]},
{"id":"fls27","cat":"Life Sciences","title":"Bones & Joints Basics","diff":"Easy","qs":[{"q":"What is the primary function of the human skeletal system?","ch":["Digesting food","Providing structure and support for the body","Pumping blood","Producing sound"],"ans":1,"exp":"The skeletal system provides the framework that supports the body, protects internal organs, and allows movement in conjunction with muscles."},{"q":"Which type of joint, found in the skull, allows little to no movement?","ch":["Ball-and-socket joint","Hinge joint","Pivot joint","Fixed (fused) joint"],"ans":3,"exp":"The joints between the bones of the skull are fixed, or fused, joints that allow little to no movement, protecting the brain."},{"q":"Which type of joint allows the arm to move like a door hinge, such as at the elbow?","ch":["Hinge joint","Ball-and-socket joint","Gliding joint","Fixed joint"],"ans":0,"exp":"A hinge joint, like the one at the elbow or knee, allows movement in one direction, similar to how a door hinge works."},{"q":"The shoulder and hip use which type of joint that allows movement in almost all directions?","ch":["Hinge joint","Fixed joint","Ball-and-socket joint","Gliding joint"],"ans":2,"exp":"Ball-and-socket joints, found at the shoulder and hip, allow a wide range of motion including rotation."},{"q":"What connective tissue attaches muscle to bone?","ch":["Ligament","Cartilage","Nerve","Tendon"],"ans":3,"exp":"Tendons are tough connective tissues that attach muscles to bones, allowing muscle contractions to move the skeleton."},{"q":"What connective tissue connects bone to bone at a joint?","ch":["Ligament","Tendon","Nerve","Cartilage"],"ans":0,"exp":"Ligaments are strong bands of connective tissue that connect one bone to another, stabilizing joints."},{"q":"What is the smooth, flexible tissue that cushions the ends of bones at joints?","ch":["Marrow","Cartilage","Tendon","Ligament"],"ans":1,"exp":"Cartilage is a smooth, flexible connective tissue that covers the ends of bones at joints, reducing friction and absorbing shock."},{"q":"Where are most red blood cells produced in the body?","ch":["Cartilage","Ligaments","Bone marrow","Tendons"],"ans":2,"exp":"Red blood cells, along with white blood cells and platelets, are produced in the bone marrow found inside many bones."}]},
{"id":"fls28","cat":"Life Sciences","title":"Human Reproduction & Life Cycle Basics","diff":"Easy","qs":[{"q":"Which organ produces eggs in the human female reproductive system?","ch":["Uterus","Ovary","Fallopian tube","Vagina"],"ans":1,"exp":"The ovaries are the organs responsible for producing and releasing egg cells (ova) in the female reproductive system."},{"q":"Where does a fertilized egg typically implant and develop during pregnancy?","ch":["Ovary","Fallopian tube","Uterus","Cervix"],"ans":2,"exp":"After fertilization, the embryo travels to the uterus, where it implants in the uterine lining and develops throughout pregnancy."},{"q":"Which cells are produced by the testes in the male reproductive system?","ch":["Sperm cells","Egg cells","Red blood cells","Nerve cells"],"ans":0,"exp":"The testes produce sperm cells, the male reproductive cells needed for fertilization."},{"q":"What is fertilization?","ch":["The division of a cell into two identical cells","The union of a sperm cell and an egg cell to form a zygote","The growth of a baby inside the uterus","The release of an egg from the ovary"],"ans":1,"exp":"Fertilization occurs when a sperm cell joins with an egg cell, combining their genetic material to form a single-celled zygote."},{"q":"Approximately how long does a typical human pregnancy last?","ch":["1 month","3 months","18 months","9 months"],"ans":3,"exp":"A typical human pregnancy lasts about nine months, or roughly 40 weeks, from fertilization to birth."},{"q":"What term describes the stage of human development from birth through the first year of life?","ch":["Infancy","Adolescence","Puberty","Prenatal stage"],"ans":0,"exp":"Infancy refers to the earliest stage of life after birth, generally covering the first year, marked by rapid growth and development."},{"q":"What is puberty?","ch":["The period before birth when organs form","The stage of life when a person becomes physically able to reproduce","The final stage of aging","The process of cell division in embryos"],"ans":1,"exp":"Puberty is the developmental stage, typically occurring in the teenage years, during which the body matures and becomes capable of sexual reproduction."},{"q":"Which of the following best describes the release of an egg from the ovary?","ch":["Fertilization","Menstruation","Implantation","Ovulation"],"ans":3,"exp":"Ovulation is the process in which a mature egg is released from an ovary, making it available for fertilization."}]},
{"id":"fls29","cat":"Life Sciences","title":"Punnett Squares & Basic Heredity","diff":"Medium","qs":[{"q":"In a Punnett square, what does a capital letter typically represent?","ch":["A dominant allele","A recessive allele","A chromosome","A phenotype"],"ans":0,"exp":"By convention, a capital letter represents a dominant allele, while a lowercase letter represents a recessive allele."},{"q":"If a pea plant has the genotype 'Tt' for height, what is this called?","ch":["Homozygous dominant","Homozygous recessive","Heterozygous","Codominant"],"ans":2,"exp":"A genotype with two different alleles, such as Tt, is called heterozygous."},{"q":"In a cross between two heterozygous parents (Aa x Aa), what fraction of offspring is expected to show the recessive phenotype?","ch":["1/4","1/2","3/4","All of them"],"ans":0,"exp":"In an Aa x Aa cross, the expected genotype ratio is 1 AA : 2 Aa : 1 aa, so 1/4 of offspring are expected to be aa and show the recessive phenotype."},{"q":"What is a phenotype?","ch":["The genetic makeup of an organism","The physical or observable trait of an organism","A diagram showing possible gene combinations","A type of chromosome"],"ans":1,"exp":"Phenotype refers to the observable physical characteristics of an organism, such as eye color, which result from its genotype and environment."},{"q":"What term describes an organism with two identical alleles for a trait, such as 'BB' or 'bb'?","ch":["Heterozygous","Hybrid","Homozygous","Recessive trait"],"ans":2,"exp":"Homozygous describes a genotype with two identical alleles for a given gene, either both dominant or both recessive."},{"q":"In humans, brown eye color allele (B) is dominant over blue eye color allele (b). What eye color would a person with genotype 'Bb' most likely have?","ch":["Blue","Green","Brown","A mix of both, appearing as a new color"],"ans":2,"exp":"Because brown (B) is dominant, an individual with one dominant and one recessive allele (Bb) will show the dominant brown-eye phenotype."},{"q":"A Punnett square is primarily used to","ch":["Measure the size of chromosomes","Predict the possible genotype combinations of offspring from a genetic cross","Show the location of genes on a chromosome","Determine an organism's exact age"],"ans":1,"exp":"A Punnett square is a diagram used to predict the probability of different genotype and phenotype combinations resulting from a genetic cross."},{"q":"If both parents have the genotype 'bb' for a recessive trait, what percentage of their offspring will show the dominant trait?","ch":["100%","75%","50%","0%"],"ans":3,"exp":"Since both parents can only pass on the recessive allele b, all offspring will be bb and show the recessive trait, meaning 0% will show the dominant trait."}]},
{"id":"fls30","cat":"Life Sciences","title":"Mitosis & the Cell Cycle","diff":"Medium","qs":[{"q":"What is the main purpose of mitosis?","ch":["To produce two genetically identical daughter cells for growth and repair","To produce sex cells with half the chromosome number","To create genetic variation through crossing over","To break down old cells for recycling"],"ans":0,"exp":"Mitosis is a type of cell division that produces two genetically identical daughter cells, used for growth, development, and repair of tissues."},{"q":"During which phase of the cell cycle does DNA replication occur?","ch":["G1 phase","Prophase","Metaphase","S phase"],"ans":3,"exp":"DNA replication occurs during the S (synthesis) phase of interphase, before the cell enters mitosis."},{"q":"During which stage of mitosis do chromosomes line up along the middle of the cell?","ch":["Prophase","Anaphase","Metaphase","Telophase"],"ans":2,"exp":"During metaphase, chromosomes align along the cell's equator, or metaphase plate, in preparation for separation."},{"q":"During which stage of mitosis do sister chromatids separate and move to opposite poles of the cell?","ch":["Prophase","Metaphase","Telophase","Anaphase"],"ans":3,"exp":"During anaphase, the sister chromatids are pulled apart and move toward opposite poles of the cell."},{"q":"What structure pulls chromosomes apart during mitosis?","ch":["Cell membrane","Ribosomes","Cell wall","Spindle fibers"],"ans":3,"exp":"Spindle fibers, made of microtubules, attach to chromosomes and pull the sister chromatids apart during mitosis."},{"q":"What is the final process that physically divides the cytoplasm into two separate cells after mitosis?","ch":["Interphase","Replication","Cytokinesis","Fertilization"],"ans":2,"exp":"Cytokinesis is the division of the cytoplasm that occurs after mitosis, resulting in two separate daughter cells."},{"q":"During which stage of mitosis does the nuclear membrane break down and chromosomes become visible?","ch":["Telophase","Prophase","Metaphase","Anaphase"],"ans":1,"exp":"During prophase, chromatin condenses into visible chromosomes and the nuclear membrane begins to break down."},{"q":"Which part of the cell cycle takes up the most time in a typical cell?","ch":["Mitosis","Cytokinesis","Interphase","Telophase"],"ans":2,"exp":"Interphase, which includes cell growth and DNA replication, takes up the majority of the cell cycle, often around 90 percent of the total time."}]},
{"id":"fls31","cat":"Life Sciences","title":"Meiosis & Genetic Variation","diff":"Medium","qs":[{"q":"What is the main purpose of meiosis?","ch":["To produce sex cells (gametes) with half the normal chromosome number","To produce two identical body cells for tissue repair","To repair damaged DNA","To combine two cells into one"],"ans":0,"exp":"Meiosis is a specialized type of cell division that produces gametes (sperm and egg cells) with half the normal number of chromosomes."},{"q":"How many daughter cells are produced from one original cell after meiosis is complete?","ch":["One","Two","Three","Four"],"ans":3,"exp":"Meiosis involves two rounds of division, producing four haploid daughter cells from one original diploid cell."},{"q":"What term describes cells, like human gametes, that contain only one set of chromosomes?","ch":["Diploid","Haploid","Somatic","Homozygous"],"ans":1,"exp":"Haploid cells contain a single set of chromosomes, which is half the number found in typical diploid body cells."},{"q":"What process during meiosis involves the exchange of genetic material between homologous chromosomes, increasing genetic variation?","ch":["Crossing over","Mitosis","Fertilization","Cytokinesis"],"ans":0,"exp":"Crossing over occurs during meiosis when homologous chromosomes exchange segments of DNA, creating new combinations of genes."},{"q":"How many chromosomes are found in a typical human body (somatic) cell?","ch":["23","92","69","46"],"ans":3,"exp":"Human somatic (body) cells typically contain 46 chromosomes, arranged in 23 pairs."},{"q":"How many chromosomes are found in a typical human sperm or egg cell?","ch":["46","69","23","92"],"ans":2,"exp":"Human gametes (sperm and egg cells) are haploid and contain 23 chromosomes, half the number found in body cells."},{"q":"Which of the following contributes to genetic variation among offspring produced through sexual reproduction?","ch":["Crossing over and random assortment of chromosomes during meiosis","Identical replication of DNA during mitosis","Binary fission in bacteria","Photosynthesis in plant cells"],"ans":0,"exp":"Crossing over and the random assortment of chromosomes during meiosis both shuffle genetic material, producing genetically varied gametes."},{"q":"Why is meiosis important for sexual reproduction?","ch":["It allows the chromosome number to double each generation","It only occurs in plant cells","It prevents any genetic variation between generations","It ensures that offspring have the same chromosome number as their parents by halving it in gametes before fertilization"],"ans":3,"exp":"Meiosis halves the chromosome number in gametes so that when two gametes combine during fertilization, the offspring has the correct, full chromosome number."}]},
{"id":"fls32","cat":"Life Sciences","title":"Enzymes — Basic Function","diff":"Medium","qs":[{"q":"What is the primary role of enzymes in the body?","ch":["To speed up chemical reactions without being used up","To provide structural support to cells","To store genetic information","To transport oxygen through the blood"],"ans":0,"exp":"Enzymes are biological catalysts that speed up chemical reactions in living things without being permanently changed or consumed themselves."},{"q":"What term describes the specific molecule an enzyme acts upon?","ch":["Substrate","Product","Catalyst","Cofactor"],"ans":0,"exp":"The substrate is the specific molecule that an enzyme binds to and acts upon during a reaction."},{"q":"The region of an enzyme where the substrate binds is called the","ch":["Nucleus","Cell membrane","Active site","Ribosome"],"ans":2,"exp":"The active site is the specific region on an enzyme's surface where the substrate binds and the reaction takes place."},{"q":"Enzymes are most often made of which type of biological molecule?","ch":["Carbohydrates","Lipids","Nucleic acids","Proteins"],"ans":3,"exp":"Most enzymes are proteins, whose specific three-dimensional shapes allow them to bind precisely to their substrates."},{"q":"What happens to an enzyme's function if its shape is altered by extreme heat, a process called denaturation?","ch":["It works faster than before","It becomes a substrate instead","It duplicates itself","It usually stops working properly"],"ans":3,"exp":"Denaturation changes an enzyme's shape, which usually prevents it from binding properly to its substrate, causing it to lose its function."},{"q":"Which factor, if raised too high above an enzyme's optimal level, can denature it and reduce its activity?","ch":["Temperature","Substrate color","Cell size","Chromosome number"],"ans":0,"exp":"Each enzyme has an optimal temperature range; temperatures too far above this range can denature the enzyme and reduce or stop its activity."},{"q":"Why are enzymes often described as being 'reusable'?","ch":["They are destroyed after one use","They change into a different molecule after use","They are not affected by the reactions they help complete and can catalyze many reactions","They only work one time before breaking down"],"ans":2,"exp":"Enzymes are not consumed or permanently altered by the reactions they catalyze, so a single enzyme molecule can be reused to catalyze the same reaction many times."},{"q":"The 'lock and key' model describes","ch":["How an enzyme's active site fits specifically with its substrate","How chromosomes pair during meiosis","How DNA replicates","How cells communicate with hormones"],"ans":0,"exp":"The lock-and-key model illustrates how an enzyme's active site has a specific shape that fits only certain substrate molecules, much like a key fits a specific lock."}]},
{"id":"fls33","cat":"Life Sciences","title":"The Skin — Integumentary System","diff":"Easy","qs":[{"q":"What is the largest organ of the human body?","ch":["The liver","The brain","The heart","The skin"],"ans":3,"exp":"The skin is the largest organ of the human body, covering and protecting everything inside it."},{"q":"Which of the following is NOT a major function of the skin?","ch":["Protecting the body from pathogens","Regulating body temperature","Producing insulin","Sensing touch, pain, and temperature"],"ans":2,"exp":"Insulin is produced by the pancreas, not the skin. The skin's major roles include protection, temperature regulation, and sensation."},{"q":"Which layer of the skin is the outermost and provides a waterproof barrier?","ch":["Dermis","Hypodermis","Subcutaneous layer","Epidermis"],"ans":3,"exp":"The epidermis is the thin, outermost layer of skin that provides a waterproof, protective barrier against the environment."},{"q":"Which layer of skin contains blood vessels, nerve endings, and hair follicles?","ch":["Epidermis","Hypodermis","Dermis","Cuticle"],"ans":2,"exp":"The dermis, located beneath the epidermis, contains blood vessels, nerve endings, hair follicles, and sweat glands."},{"q":"What is the deepest layer of skin, made mostly of fat, that helps insulate the body?","ch":["Epidermis","Dermis","Hypodermis (subcutaneous layer)","Melanin layer"],"ans":2,"exp":"The hypodermis, or subcutaneous layer, lies beneath the dermis and is composed largely of fat tissue that insulates and cushions the body."},{"q":"Which glands in the skin help cool the body by releasing fluid onto the skin's surface?","ch":["Sweat glands","Sebaceous glands","Thyroid glands","Salivary glands"],"ans":0,"exp":"Sweat glands release fluid onto the skin's surface, and its evaporation helps cool the body down."},{"q":"What pigment, produced by cells in the epidermis, gives skin its color and helps protect against UV radiation?","ch":["Hemoglobin","Keratin","Collagen","Melanin"],"ans":3,"exp":"Melanin is a pigment produced by melanocytes in the epidermis that gives skin its color and helps absorb harmful UV radiation."},{"q":"What tough, protective protein makes up much of the outer skin, hair, and nails?","ch":["Melanin","Collagen","Keratin","Hemoglobin"],"ans":2,"exp":"Keratin is a tough, fibrous protein that provides strength and protection in the outer layer of skin, as well as in hair and nails."}]},
{"id":"fls34","cat":"Life Sciences","title":"The Five Senses","diff":"Easy","qs":[{"q":"Which sense organ is primarily responsible for detecting light and allowing vision?","ch":["Ear","Nose","Tongue","Eye"],"ans":3,"exp":"The eye contains specialized cells that detect light, allowing the brain to interpret images, which is the sense of vision."},{"q":"Which part of the eye contains light-sensitive cells called rods and cones?","ch":["Cornea","Pupil","Retina","Iris"],"ans":2,"exp":"The retina, located at the back of the eye, contains rod and cone cells that detect light and send signals to the brain."},{"q":"Which structures inside the ear are responsible for detecting sound vibrations and helping with balance?","ch":["Retina and cornea","Taste buds and papillae","Olfactory receptors","Cochlea and semicircular canals"],"ans":3,"exp":"The cochlea converts sound vibrations into nerve signals for hearing, while the semicircular canals help the body maintain balance."},{"q":"Taste buds, mainly located on the tongue, allow humans to detect which basic tastes?","ch":["Only sweet and sour","Sweet, sour, salty, bitter, and umami","Only spicy and sweet","Only bitter and salty"],"ans":1,"exp":"Taste buds detect five basic tastes: sweet, sour, salty, bitter, and umami (savory)."},{"q":"Which sense organ contains receptors that detect chemicals in the air, contributing heavily to how food tastes?","ch":["Nose","Eye","Ear","Skin"],"ans":0,"exp":"The nose contains olfactory receptors that detect airborne chemicals, and this sense of smell greatly influences our perception of flavor."},{"q":"Which sense allows a person to feel pressure, temperature, and pain through receptors located throughout the body?","ch":["Sight","Hearing","Touch","Taste"],"ans":2,"exp":"The sense of touch relies on receptors found throughout the skin that detect pressure, temperature, texture, and pain."},{"q":"Which colored part of the eye controls how much light enters by adjusting the size of the pupil?","ch":["Retina","Cornea","Lens","Iris"],"ans":3,"exp":"The iris is the colored, muscular part of the eye that contracts or expands to control the size of the pupil and the amount of light entering the eye."},{"q":"The clear, curved front part of the eye that helps focus incoming light is called the","ch":["Retina","Cornea","Iris","Optic nerve"],"ans":1,"exp":"The cornea is the transparent outer layer at the front of the eye that helps focus light onto the retina."}]},
{"id":"fls35","cat":"Life Sciences","title":"Population Ecology Basics","diff":"Easy","qs":[{"q":"In ecology, what is a population?","ch":["All the living and nonliving things in an area","A group of different species living together","The physical environment where organisms live","A group of the same species living in the same area at the same time"],"ans":3,"exp":"A population refers to all the individuals of a single species living in the same geographic area at the same time."},{"q":"What term describes all the different populations living and interacting together in a given area?","ch":["Community","Ecosystem","Biome","Habitat"],"ans":0,"exp":"A community consists of all the different species' populations that live and interact together within a specific area."},{"q":"What is carrying capacity?","ch":["The maximum population size an environment can sustainably support","The total number of species in an ecosystem","The rate at which a population grows each year","The minimum number of individuals needed to avoid extinction"],"ans":0,"exp":"Carrying capacity is the maximum population size that an environment can support long-term given its available resources, like food, water, and space."},{"q":"Which of the following is a limiting factor that could reduce a population's growth?","ch":["Unlimited food supply","Lack of predators","Limited availability of food or water","Ideal climate conditions"],"ans":2,"exp":"Limiting factors, such as a shortage of food, water, or space, restrict population growth by increasing death rates or decreasing birth rates."},{"q":"What term describes organisms of different species living in the same area that compete for the same limited resource?","ch":["Symbiosis","Mutualism","Predation","Competition"],"ans":3,"exp":"Competition occurs when organisms, whether of the same or different species, vie for the same limited resources, such as food or territory."},{"q":"In a predator-prey relationship, what typically happens to the predator population if the prey population suddenly declines sharply?","ch":["The predator population usually declines as well due to less available food","The predator population increases rapidly","The predator population stays exactly the same","The predator population immediately goes extinct"],"ans":0,"exp":"When prey becomes scarce, predators often have less food available, which can lead to a decline in the predator population over time."},{"q":"Which term describes the specific role an organism plays within its ecosystem, including what it eats and how it interacts with other organisms?","ch":["Habitat","Biome","Population density","Niche"],"ans":3,"exp":"A niche describes an organism's specific role in its ecosystem, including its diet, habitat use, and interactions with other species."},{"q":"What is population density?","ch":["The number of individuals of a population per unit of area","The total number of species in an ecosystem","The average lifespan of individuals in a population","The rate of predation within an ecosystem"],"ans":0,"exp":"Population density measures how many individuals of a population live within a specific unit of area, such as per square mile."}]},
{"id":"fls36","cat":"Life Sciences","title":"Genetics Vocabulary & Basic Concepts","diff":"Medium","qs":[{"q":"What is a gene?","ch":["A segment of DNA that codes for a specific protein or trait","An entire chromosome","The physical appearance of an organism","A type of cell organelle"],"ans":0,"exp":"A gene is a specific segment of DNA that contains instructions for producing a particular protein, which influences an organism's traits."},{"q":"What is an allele?","ch":["A different version of a gene","A type of chromosome found only in humans","The location of a gene on a chromosome","A diagram used to predict traits"],"ans":0,"exp":"An allele is one of two or more alternative versions of a gene that can produce different variations of a trait."},{"q":"What term describes the complete set of genetic information an organism carries?","ch":["Phenotype","Karyotype","Species","Genotype"],"ans":3,"exp":"Genotype refers to the specific genetic makeup of an organism, meaning the combination of alleles it carries."},{"q":"A trait is described as dominant if","ch":["It only appears when two recessive alleles are present","It skips a generation entirely","It masks the effect of a recessive allele when both are present","It cannot be passed on to offspring"],"ans":2,"exp":"A dominant allele's trait is expressed, or shown, whenever it is present, effectively masking the recessive allele's trait in a heterozygous individual."},{"q":"A recessive trait will only be expressed in an organism if","ch":["The organism has at least one dominant allele","The organism is male","The trait is a mutation","The organism inherits two recessive alleles, one from each parent"],"ans":3,"exp":"A recessive trait is only expressed when an organism is homozygous recessive, meaning it inherited a recessive allele from both parents."},{"q":"What structures, found in the nucleus of cells, are made of tightly coiled DNA and proteins?","ch":["Ribosomes","Mitochondria","Vacuoles","Chromosomes"],"ans":3,"exp":"Chromosomes are structures made of tightly coiled DNA wrapped around proteins, located in the nucleus of cells."},{"q":"What term describes offspring produced by crossing two different varieties or species?","ch":["Clone","Mutant","Hybrid","Twin"],"ans":2,"exp":"A hybrid is the offspring resulting from crossing two genetically different parents, varieties, or sometimes species."},{"q":"Gregor Mendel's experiments with pea plants helped establish the basic principles of what field of biology?","ch":["Genetics","Ecology","Microbiology","Evolution by natural selection"],"ans":0,"exp":"Gregor Mendel's careful breeding experiments with pea plants in the 1800s laid the foundation for the modern field of genetics."}]},
{"id":"fls37","cat":"Life Sciences","title":"The Urinary & Excretory System Basics","diff":"Easy","qs":[{"q":"What is the main function of the kidneys?","ch":["To pump blood throughout the body","To digest food","To produce sound for communication","To filter waste products and excess water from the blood"],"ans":3,"exp":"The kidneys filter blood to remove waste products and excess water, producing urine as a result."},{"q":"What waste product, produced when the body breaks down proteins, is filtered out by the kidneys?","ch":["Urea","Glucose","Oxygen","Carbon dioxide"],"ans":0,"exp":"Urea is a nitrogen-containing waste product formed when the body breaks down proteins, and it is filtered out of the blood by the kidneys."},{"q":"What tube carries urine from each kidney to the bladder?","ch":["Urethra","Esophagus","Trachea","Ureter"],"ans":3,"exp":"Each ureter is a narrow tube that carries urine from a kidney down to the bladder for storage."},{"q":"What organ stores urine until it is ready to be released from the body?","ch":["Kidney","Bladder","Liver","Ureter"],"ans":1,"exp":"The bladder is a muscular, balloon-like organ that stores urine until it is released from the body through urination."},{"q":"What tube carries urine from the bladder out of the body?","ch":["Ureter","Trachea","Urethra","Esophagus"],"ans":2,"exp":"The urethra is the tube that carries urine from the bladder to the outside of the body during urination."},{"q":"Which tiny structures within the kidney are responsible for filtering blood?","ch":["Alveoli","Neurons","Villi","Nephrons"],"ans":3,"exp":"Nephrons are the microscopic filtering units within the kidneys where blood is filtered and urine is formed."},{"q":"Besides the kidneys, which organ helps remove waste through sweat?","ch":["Skin","Heart","Stomach","Brain"],"ans":0,"exp":"The skin helps eliminate some waste products, like excess salts and water, through sweat produced by sweat glands."},{"q":"Which of these is a normal component of healthy human urine?","ch":["Large amounts of protein","Red blood cells in large quantities","Water and dissolved waste products like urea","Undigested food particles"],"ans":2,"exp":"Healthy urine is mostly water along with dissolved waste products such as urea and salts; it should not normally contain significant protein or red blood cells."}]},
{"id":"fls38","cat":"Life Sciences","title":"Basic Botany — Plant Structure","diff":"Easy","qs":[{"q":"Which plant organ typically grows underground and absorbs water and nutrients?","ch":["Leaf","Stem","Root","Flower"],"ans":2,"exp":"Roots typically grow underground, anchoring the plant and absorbing water and nutrients from the soil."},{"q":"What is the main function of leaves in most plants?","ch":["To carry out photosynthesis","To absorb water from soil","To produce seeds","To anchor the plant in the ground"],"ans":0,"exp":"Leaves are the primary site of photosynthesis in most plants, using sunlight to produce food from carbon dioxide and water."},{"q":"What is the function of a plant's stem?","ch":["To produce pollen","To absorb sunlight directly for energy","To store genetic information","To support the plant and transport water and nutrients between roots and leaves"],"ans":3,"exp":"The stem provides structural support for the plant and contains vascular tissue that transports water, nutrients, and sugars between the roots and leaves."},{"q":"Which part of a flowering plant develops into a fruit after fertilization?","ch":["Petal","Ovary","Stamen","Sepal"],"ans":1,"exp":"After fertilization, the ovary of a flower typically develops into a fruit, which encloses and protects the seeds."},{"q":"What is the male reproductive part of a flower called?","ch":["Pistil","Sepal","Ovule","Stamen"],"ans":3,"exp":"The stamen is the male reproductive structure of a flower, consisting of the anther, which produces pollen, and the filament that supports it."},{"q":"What is the female reproductive part of a flower called?","ch":["Stamen","Anther","Pistil","Petal"],"ans":2,"exp":"The pistil is the female reproductive structure of a flower, including the stigma, style, and ovary."},{"q":"What is the primary purpose of a plant's colorful petals?","ch":["To perform photosynthesis","To absorb water from rain","To store extra sugar","To attract pollinators like bees and butterflies"],"ans":3,"exp":"Colorful, often fragrant petals help attract pollinators such as bees and butterflies, increasing the chances of successful pollination."},{"q":"What term describes the transfer of pollen from the male part of a flower to the female part?","ch":["Germination","Fertilization","Pollination","Photosynthesis"],"ans":2,"exp":"Pollination is the transfer of pollen grains from the anther (male part) to the stigma (female part) of a flower, a necessary step before fertilization can occur."}]},
{"id":"fls39","cat":"Life Sciences","title":"Intro to Biotechnology & Genetic Engineering","diff":"Medium","qs":[{"q":"What is genetic engineering?","ch":["The study of fossils to understand evolution","The process of classifying organisms into groups","The natural process of mutation over generations","The direct manipulation of an organism's DNA to change its traits"],"ans":3,"exp":"Genetic engineering involves directly altering an organism's DNA in a lab setting to produce a desired trait or characteristic."},{"q":"What term describes an organism whose genetic material has been altered using genetic engineering techniques?","ch":["Hybrid","Genetically modified organism (GMO)","Clone","Mutant strain"],"ans":1,"exp":"A genetically modified organism, or GMO, has had its DNA altered using biotechnology, often to add a helpful trait."},{"q":"Which enzyme is commonly used in genetic engineering to cut DNA at specific locations?","ch":["DNA polymerase","Restriction enzyme","Ribosome","RNA polymerase"],"ans":1,"exp":"Restriction enzymes act like molecular scissors, cutting DNA at specific sequences, which allows scientists to isolate and insert genes."},{"q":"What is cloning?","ch":["Crossing two different species to make a hybrid","Producing a genetically identical copy of an organism or cell","Randomly mutating an organism's DNA","Filtering DNA from blood samples"],"ans":1,"exp":"Cloning is the process of creating a genetically identical copy of an organism, cell, or piece of DNA."},{"q":"One common agricultural use of genetic engineering is to create crops that are","ch":["Unable to reproduce at all","Only edible by animals","Incapable of photosynthesis","Resistant to certain pests or diseases"],"ans":3,"exp":"Scientists often use genetic engineering to create crops with beneficial traits, such as resistance to pests, diseases, or harsh growing conditions."},{"q":"What is the purpose of using bacteria in some genetic engineering processes, such as producing insulin?","ch":["Bacteria naturally contain human insulin","Bacteria cannot be modified genetically","Bacteria are used only to store DNA samples long-term","Bacteria can be engineered to produce useful proteins in large quantities"],"ans":3,"exp":"Scientists can insert a human gene into bacteria, which then use their own cellular machinery to mass-produce useful proteins like insulin."},{"q":"What is a potential ethical concern often raised about genetic engineering in humans?","ch":["It might be used to alter traits in ways that raise fairness or safety concerns","It always cures every genetic disease immediately","It has no effect on future generations","It is identical to selective breeding in every way"],"ans":0,"exp":"Genetic engineering in humans raises ethical questions about fairness, safety, and the long-term effects of altering traits that can be passed to future generations."},{"q":"Which of the following best describes DNA fingerprinting?","ch":["A technique used to compare unique patterns in an individual's DNA for identification","A way to change an organism's eye color","A method for growing plants without soil","A process used only to identify plant species"],"ans":0,"exp":"DNA fingerprinting is a technique that analyzes unique patterns in a person's DNA, often used in forensics and paternity testing to identify individuals."}]},
{"id":"fls40","cat":"Life Sciences","title":"Biology Lab Safety & Scientific Measurement","diff":"Easy","qs":[{"q":"Before starting any lab experiment, what should students always do first?","ch":["Start mixing chemicals immediately","Skip the instructions to save time","Taste any unknown substances to identify them","Read and follow the safety instructions and procedure"],"ans":3,"exp":"Students should always read and understand the safety instructions and procedure before beginning any lab activity to prevent accidents."},{"q":"What should you do immediately if a chemical spills on your skin during a lab experiment?","ch":["Ignore it if it doesn't hurt","Rinse the affected area with water right away and tell your teacher","Wait to see if a reaction occurs before doing anything","Cover it with a bandage immediately"],"ans":1,"exp":"If a chemical contacts your skin, you should immediately rinse the area with water and notify your teacher to prevent injury."},{"q":"Which piece of safety equipment should be worn to protect the eyes during many lab experiments?","ch":["Gloves","Lab coat","Safety goggles","Closed-toe shoes"],"ans":2,"exp":"Safety goggles protect the eyes from chemical splashes, debris, or other hazards that could occur during a lab experiment."},{"q":"What tool is commonly used to measure the volume of a liquid in a lab?","ch":["Balance","Thermometer","Microscope","Graduated cylinder"],"ans":3,"exp":"A graduated cylinder is a common lab tool used to accurately measure the volume of liquids."},{"q":"Which instrument would a student use to measure the mass of an object in the lab?","ch":["Ruler","Thermometer","Balance (scale)","Graduated cylinder"],"ans":2,"exp":"A balance, or scale, is used to measure the mass of an object in grams or kilograms."},{"q":"In the metric system commonly used in science, what is the standard unit for measuring length?","ch":["Meter","Pound","Gallon","Fahrenheit degree"],"ans":0,"exp":"The meter is the standard base unit for measuring length in the metric system used throughout science."},{"q":"Why do scientists generally prefer the metric system over other measurement systems?","ch":["It cannot be used for small measurements","It is only used in the United States","It does not require any tools to measure","It is based on units of ten, making conversions and calculations simpler"],"ans":3,"exp":"The metric system is based on units of ten, which makes converting between units, such as centimeters and meters, straightforward and consistent for scientific work."},{"q":"If you are unsure whether it's safe to handle a piece of lab equipment or a chemical, what is the best course of action?","ch":["Ask your teacher or supervisor before proceeding","Guess and proceed carefully on your own","Ask a classmate who also seems unsure","Look it up on an unreliable website and proceed"],"ans":0,"exp":"When in doubt about lab safety, always ask your teacher or supervisor before proceeding, since they can provide correct guidance to prevent accidents."}]},
{"id":"fps01","cat":"Physical Sciences","title":"Matter & States of Matter","diff":"Easy","qs":[{"q":"What is the scientific definition of matter?","ch":["Anything that has mass and takes up space","Anything that can be seen with the naked eye","Only substances that are solid at room temperature","Any form of energy, including light and heat"],"ans":0,"exp":"Matter is defined as anything that has mass and takes up space (volume), which includes solids, liquids, and gases."},{"q":"Which state of matter has a definite shape and a definite volume?","ch":["Gas","Plasma","Solid","Liquid"],"ans":2,"exp":"A solid holds both its shape and its volume because its particles are tightly packed and vibrate in fixed positions."},{"q":"Which state of matter takes the shape of its container but keeps a constant volume?","ch":["Solid","Liquid","Gas","Plasma"],"ans":1,"exp":"A liquid's particles can move past one another, so it flows to fill the bottom of a container, but its volume stays the same."},{"q":"Which state of matter has neither a definite shape nor a definite volume?","ch":["Solid","Liquid","None of the states of matter","Gas"],"ans":3,"exp":"Gas particles move freely and spread apart to fill any container completely, so gases have no fixed shape or volume."},{"q":"What is the process called when a solid changes directly into a gas without becoming a liquid first?","ch":["Condensation","Sublimation","Deposition","Melting"],"ans":1,"exp":"Sublimation is the direct change from solid to gas, as seen with dry ice (solid carbon dioxide) turning into vapor."},{"q":"What term describes a liquid changing into a gas?","ch":["Vaporization","Freezing","Deposition","Fusion"],"ans":0,"exp":"Vaporization (which includes boiling and evaporation) is the change of state from liquid to gas."},{"q":"What happens to the particles of a substance as it is heated and changes from solid to liquid to gas?","ch":["The particles lose mass","The particles disappear temporarily","The particles move faster and spread farther apart","The particles change into a different element"],"ans":2,"exp":"Heating adds energy, making particles move faster and spread farther apart, which is why matter expands and changes state as it warms."},{"q":"Which of the following is an example of a physical state change, not a new substance being formed?","ch":["Wood burning to ash","Iron rusting","Bread baking in an oven","Ice melting into water"],"ans":3,"exp":"Ice melting into water is a change of state (solid to liquid) where the substance is still H2O; no new substance is formed."}]},
{"id":"fps02","cat":"Physical Sciences","title":"Atomic Structure Basics","diff":"Easy","qs":[{"q":"What are the three main subatomic particles found in an atom?","ch":["Protons, neutrons, and electrons","Protons, ions, and molecules","Neutrons, electrons, and photons","Atoms, molecules, and compounds"],"ans":0,"exp":"Every atom is made up of protons, neutrons, and electrons; protons and neutrons form the nucleus while electrons orbit around it."},{"q":"Where are protons and neutrons located in an atom?","ch":["In the electron cloud","Scattered throughout the atom equally","In the nucleus, at the center of the atom","Outside the atom entirely"],"ans":2,"exp":"Protons and neutrons are packed tightly together in the nucleus, which sits at the center of the atom."},{"q":"What electric charge does a proton carry?","ch":["Negative","Positive","No charge","It varies by element"],"ans":1,"exp":"A proton carries a positive electric charge, which is balanced by the negative charge of electrons in a neutral atom."},{"q":"What electric charge does a neutron carry?","ch":["Positive","Double positive","Negative","Neutral (no charge)"],"ans":3,"exp":"Neutrons have no electric charge, which is why they are called neutral particles."},{"q":"What determines the atomic number of an element?","ch":["The number of neutrons in the nucleus","The total mass of the atom","The number of protons in the nucleus","The number of electron shells"],"ans":2,"exp":"The atomic number is defined as the number of protons in an atom's nucleus, and it determines which element the atom is."},{"q":"What is an isotope?","ch":["An atom with a different number of protons","An atom of the same element with a different number of neutrons","A charged atom that has gained or lost electrons","A completely different element with similar properties"],"ans":1,"exp":"Isotopes are atoms of the same element (same number of protons) that have different numbers of neutrons, giving them different masses."},{"q":"What happens to an atom when it loses one or more electrons?","ch":["It becomes a positively charged ion","It becomes a negatively charged ion","It turns into a different element","It gains an extra neutron"],"ans":0,"exp":"Losing negatively charged electrons leaves the atom with more protons than electrons, giving it an overall positive charge, called a cation."},{"q":"Where are electrons found relative to the nucleus of an atom?","ch":["Inside the nucleus with the protons","Fused to the neutrons","They are not part of the atom","Orbiting around the nucleus in an electron cloud"],"ans":3,"exp":"Electrons occupy the space surrounding the nucleus, often described as an electron cloud, and move around the nucleus at high speed."}]},
{"id":"fps03","cat":"Physical Sciences","title":"The Periodic Table Basics","diff":"Easy","qs":[{"q":"How is the modern periodic table primarily organized?","ch":["Alphabetically by element name","By increasing atomic number","By the year each element was discovered","By color of the element"],"ans":1,"exp":"The periodic table arranges elements in order of increasing atomic number, which also groups elements with similar properties together."},{"q":"What is a horizontal row on the periodic table called?","ch":["A group","A family","A period","A block"],"ans":2,"exp":"Horizontal rows on the periodic table are called periods, and elements in the same period have the same number of electron shells."},{"q":"What is a vertical column on the periodic table called?","ch":["A group (or family)","A period","A row","A series"],"ans":0,"exp":"Vertical columns are called groups or families, and elements in the same group tend to have similar chemical properties."},{"q":"Which side of the periodic table contains the metals?","ch":["The right side","The top row only","Metals are scattered randomly","The left and middle portion"],"ans":3,"exp":"Most elements, including all metals, are found on the left and middle of the periodic table, while nonmetals cluster on the upper right."},{"q":"What do elements in the same group of the periodic table tend to share?","ch":["The same atomic mass","Similar chemical properties and the same number of valence electrons","The exact same color and texture","The same number of neutrons"],"ans":1,"exp":"Elements in a group share the same number of valence (outer) electrons, which gives them similar chemical behavior."},{"q":"Which group of the periodic table is known as the noble gases?","ch":["Group 1","Group 17","Group 2","Group 18"],"ans":3,"exp":"Group 18 contains the noble gases, such as helium and neon, which have full outer electron shells and rarely react."},{"q":"Which group on the periodic table contains highly reactive metals like sodium and potassium?","ch":["Group 1 (alkali metals)","Group 18 (noble gases)","Group 17 (halogens)","Group 2 (alkaline earth metals)"],"ans":0,"exp":"Group 1 elements, called alkali metals, each have one valence electron and react vigorously, especially with water."},{"q":"In general, what happens to atomic size as you move from left to right across a period?","ch":["Atomic size increases","Atomic size stays exactly the same","Atomic size decreases","Atomic size doubles"],"ans":2,"exp":"Moving left to right across a period, atomic size generally decreases because the increasing nuclear charge pulls electrons closer to the nucleus."}]},
{"id":"fps04","cat":"Physical Sciences","title":"Chemical Bonding Basics","diff":"Easy","qs":[{"q":"What is an ionic bond?","ch":["A bond formed by sharing electrons equally","A bond formed by the attraction between oppositely charged ions","A bond found only in metals","A bond that only forms between two nonmetals"],"ans":1,"exp":"An ionic bond forms when one atom transfers electrons to another, creating oppositely charged ions that attract each other."},{"q":"What is a covalent bond?","ch":["A bond where electrons are transferred completely","A bond formed between a metal and a nonmetal","A bond formed when two atoms share electrons","A bond that exists only in liquids"],"ans":2,"exp":"In a covalent bond, two atoms (usually nonmetals) share one or more pairs of electrons to achieve a stable outer shell."},{"q":"Which type of bond typically forms between a metal and a nonmetal, such as sodium and chlorine?","ch":["Ionic bond","Metallic bond","Covalent bond","Hydrogen bond"],"ans":0,"exp":"Metals tend to lose electrons and nonmetals tend to gain them, so a metal and nonmetal typically form an ionic bond, as in table salt (NaCl)."},{"q":"What are valence electrons?","ch":["Electrons found only in the nucleus","Electrons shared only in metallic bonds","Electrons that have no charge","Electrons in the outermost shell of an atom that are involved in bonding"],"ans":3,"exp":"Valence electrons are the electrons in an atom's outermost shell, and they determine how an atom will bond with other atoms."},{"q":"Why do atoms form chemical bonds?","ch":["To increase their atomic number","To become radioactive","To achieve a more stable electron arrangement, often a full outer shell","To change into a different element"],"ans":2,"exp":"Atoms bond to achieve a more stable, lower-energy electron configuration, often by gaining a full outer shell like the noble gases."},{"q":"What holds the atoms together in a metallic bond?","ch":["A rigid lattice of ions with no free electrons","A sea of shared, mobile electrons surrounding positive metal ions","Strong hydrogen bonds between metal atoms","Static electric charges from outside the metal"],"ans":1,"exp":"Metallic bonding involves positive metal ions surrounded by a 'sea' of freely moving electrons, which explains why metals conduct electricity well."},{"q":"In a water molecule (H2O), what type of bond connects the hydrogen and oxygen atoms?","ch":["Covalent bond","Metallic bond","Ionic bond","No bond; they are just close together"],"ans":0,"exp":"Hydrogen and oxygen are both nonmetals that share electrons, forming covalent bonds within each water molecule."},{"q":"What term describes two atoms of the same element sharing electrons, such as in O2 gas?","ch":["Ionic bond","Hydrogen bond","Metallic bond","Nonpolar covalent bond"],"ans":3,"exp":"When atoms of the same element share electrons equally, the result is a nonpolar covalent bond, as seen in O2 or N2 gas molecules."}]},
{"id":"fps05","cat":"Physical Sciences","title":"Chemical Reactions & Balancing Equations","diff":"Medium","qs":[{"q":"What law requires that a chemical equation be balanced?","ch":["The law of definite proportions","The law of conservation of mass","The law of multiple proportions","Newton's third law"],"ans":1,"exp":"The law of conservation of mass states that matter cannot be created or destroyed, so the number of atoms of each element must be equal on both sides of the equation."},{"q":"In the equation 2H2 + O2 -> 2H2O, how many total hydrogen atoms are on the reactant side?","ch":["4","2","6","8"],"ans":0,"exp":"2H2 means two molecules of H2, and each molecule has 2 hydrogen atoms, giving a total of 4 hydrogen atoms."},{"q":"What are the substances on the left side of a chemical equation called?","ch":["Products","Catalysts","Reactants","Solvents"],"ans":2,"exp":"The substances that start a chemical reaction, written on the left side of the equation, are called reactants."},{"q":"What are the substances formed on the right side of a chemical equation called?","ch":["Reactants","Elements only","Reagents","Products"],"ans":3,"exp":"The new substances formed by a chemical reaction, written on the right side of the equation, are called products."},{"q":"What is the correct balanced form of the equation: N2 + H2 -> NH3?","ch":["N2 + H2 -> NH3","N2 + 3H2 -> 2NH3","2N2 + H2 -> NH3","N2 + 2H2 -> 2NH3"],"ans":1,"exp":"N2 + 3H2 -> 2NH3 balances both nitrogen (2 on each side) and hydrogen (6 on each side)."},{"q":"In a combustion reaction, a fuel typically reacts with what substance?","ch":["Oxygen gas","Hydrogen gas","Nitrogen gas","Carbon dioxide"],"ans":0,"exp":"Combustion reactions involve a fuel reacting with oxygen gas, releasing energy as heat and light, usually producing carbon dioxide and water."},{"q":"What type of reaction is represented by A + B -> AB?","ch":["Decomposition reaction","Single replacement reaction","Synthesis (combination) reaction","Double replacement reaction"],"ans":2,"exp":"A synthesis, or combination, reaction occurs when two or more simple substances combine to form a single more complex product."},{"q":"What type of reaction is represented by AB -> A + B?","ch":["Synthesis reaction","Double replacement reaction","Combustion reaction","Decomposition reaction"],"ans":3,"exp":"A decomposition reaction occurs when a single compound breaks down into two or more simpler substances."}]},
{"id":"fps06","cat":"Physical Sciences","title":"Acids and Bases Basics","diff":"Easy","qs":[{"q":"What taste is commonly associated with acids?","ch":["Bitter","Sour","Sweet","Salty"],"ans":1,"exp":"Acids, like the citric acid in lemons or the acetic acid in vinegar, typically taste sour."},{"q":"What taste is commonly associated with bases?","ch":["Sour","Salty","Bitter","Spicy"],"ans":2,"exp":"Bases, such as soap or baking soda solutions, commonly taste bitter and often feel slippery."},{"q":"What ion do acids release when dissolved in water?","ch":["Hydrogen ions (H+)","Hydroxide ions (OH-)","Sodium ions (Na+)","Chloride ions (Cl-) only"],"ans":0,"exp":"Acids increase the concentration of hydrogen ions (H+) when dissolved in water, which is the defining property of an acid."},{"q":"What ion do bases release when dissolved in water?","ch":["Hydrogen ions (H+)","Carbon ions","Oxygen ions","Hydroxide ions (OH-)"],"ans":3,"exp":"Bases increase the concentration of hydroxide ions (OH-) when dissolved in water."},{"q":"Which of the following is a common household acid?","ch":["Vinegar","Ammonia","Soap","Baking soda"],"ans":0,"exp":"Vinegar contains acetic acid, making it a common mild acid found in most kitchens."},{"q":"Which of the following is a common household base?","ch":["Lemon juice","Vinegar","Orange juice","Ammonia cleaner"],"ans":3,"exp":"Ammonia solutions used in household cleaners are basic (alkaline) substances."},{"q":"What happens when an acid and a base react together?","ch":["They form a precipitate that is always toxic","They neutralize each other, forming water and a salt","They always explode","Nothing happens; acids and bases cannot react"],"ans":1,"exp":"In a neutralization reaction, an acid and a base react to produce water and a salt, reducing the extreme acidity or basicity of the mixture."},{"q":"What tool changes color to indicate whether a solution is acidic or basic?","ch":["A thermometer","A barometer","An indicator, such as litmus paper","A voltmeter"],"ans":2,"exp":"Indicators like litmus paper change color depending on whether they contact an acid or a base, giving a quick visual test."}]},
{"id":"fps07","cat":"Physical Sciences","title":"The Mole & Basic Stoichiometry","diff":"Medium","qs":[{"q":"What number of particles is represented by one mole of a substance?","ch":["6.022 x 10^23","1.0 x 10^10","3.14 x 10^8","9.11 x 10^-31"],"ans":0,"exp":"One mole of any substance contains 6.022 x 10^23 particles, a number known as Avogadro's number."},{"q":"What is the approximate molar mass of water, H2O (H = 1 g/mol, O = 16 g/mol)?","ch":["16 g/mol","17 g/mol","18 g/mol","20 g/mol"],"ans":2,"exp":"Adding 2 hydrogen atoms (2 x 1) and 1 oxygen atom (16) gives 2 + 16 = 18 g/mol for water."},{"q":"How many moles are in 36 grams of water (molar mass = 18 g/mol)?","ch":["1 mole","2 moles","3 moles","18 moles"],"ans":1,"exp":"Moles = mass / molar mass, so 36 g / 18 g/mol = 2 moles."},{"q":"What is the molar mass of carbon dioxide, CO2 (C = 12 g/mol, O = 16 g/mol)?","ch":["28 g/mol","32 g/mol","40 g/mol","44 g/mol"],"ans":3,"exp":"Adding 1 carbon atom (12) and 2 oxygen atoms (2 x 16 = 32) gives 12 + 32 = 44 g/mol."},{"q":"How many grams are in 2 moles of carbon, C (molar mass = 12 g/mol)?","ch":["6 grams","12 grams","24 grams","48 grams"],"ans":2,"exp":"Mass = moles x molar mass, so 2 moles x 12 g/mol = 24 grams."},{"q":"In the balanced equation 2H2 + O2 -> 2H2O, how many moles of water are produced from 2 moles of hydrogen gas?","ch":["1 mole","2 moles","3 moles","4 moles"],"ans":1,"exp":"The mole ratio of H2 to H2O in the balanced equation is 2:2, or 1:1, so 2 moles of H2 produce 2 moles of H2O."},{"q":"What does Avogadro's number allow chemists to do?","ch":["Convert between the number of particles and the number of moles","Measure the temperature of a reaction","Determine the color of a compound","Predict the state of matter of a substance"],"ans":0,"exp":"Avogadro's number (6.022 x 10^23) is the conversion factor that links the number of particles (atoms, molecules) to the number of moles."},{"q":"What is the mole ratio of nitrogen to hydrogen in the balanced equation N2 + 3H2 -> 2NH3?","ch":["1:1","1:2","2:3","1:3"],"ans":3,"exp":"The coefficients in the balanced equation show that 1 mole of N2 reacts with 3 moles of H2, a ratio of 1:3."}]},
{"id":"fps08","cat":"Physical Sciences","title":"Solutions, Concentration & Solubility","diff":"Easy","qs":[{"q":"In a solution, what is the substance being dissolved called?","ch":["The solvent","The solute","The precipitate","The catalyst"],"ans":1,"exp":"The solute is the substance that gets dissolved, while the solvent is the substance doing the dissolving."},{"q":"In a saltwater solution, what is the water considered to be?","ch":["The solvent","The solute","The precipitate","The residue"],"ans":0,"exp":"Water is the solvent because it is present in greater amount and dissolves the salt (the solute)."},{"q":"What does it mean for a solution to be saturated?","ch":["It has no solute dissolved in it at all","It has turned into a solid","It contains the maximum amount of solute that can dissolve at that temperature","It is boiling"],"ans":2,"exp":"A saturated solution has dissolved as much solute as possible at a given temperature; any more added will not dissolve."},{"q":"How does increasing temperature generally affect the solubility of a solid solute in a liquid?","ch":["It generally decreases solubility","It always causes the solute to evaporate","It has no effect on solubility","It generally increases solubility"],"ans":3,"exp":"For most solid solutes, higher temperatures give particles more energy to spread out and dissolve, increasing solubility in a liquid solvent."},{"q":"What does the phrase 'like dissolves like' generally describe?","ch":["Solids only dissolve other solids","Polar solvents tend to dissolve polar solutes, and nonpolar solvents dissolve nonpolar solutes","Gases can never dissolve in liquids","Only water can act as a solvent"],"ans":1,"exp":"This rule of thumb explains that substances with similar polarity tend to dissolve well in each other, such as polar water dissolving polar salt."},{"q":"What term describes a mixture in which the solute is evenly distributed and cannot be seen as separate particles?","ch":["A suspension","A heterogeneous mixture","A homogeneous mixture (solution)","A colloid"],"ans":2,"exp":"A true solution is a homogeneous mixture, meaning the solute is evenly and completely mixed throughout the solvent at a molecular level."},{"q":"What happens to the solubility of a gas in water as temperature increases?","ch":["Solubility of the gas decreases","Solubility of the gas increases","Solubility of the gas stays exactly the same","Gases become solids"],"ans":0,"exp":"Unlike most solids, gases become less soluble in water as temperature increases, which is why warm soda goes flat faster."},{"q":"If sugar is stirred into water and completely disappears, what has happened at the particle level?","ch":["The sugar molecules have chemically reacted with water to form a new compound","The water has evaporated","The sugar has been destroyed","The sugar particles have separated and become evenly spread among the water molecules"],"ans":3,"exp":"Dissolving is a physical process where the sugar particles separate and disperse evenly among the water molecules, without forming a new substance."}]},
{"id":"fps09","cat":"Physical Sciences","title":"Gas Laws Basics","diff":"Medium","qs":[{"q":"According to Boyle's Law, what happens to the volume of a gas when its pressure increases at constant temperature?","ch":["Volume increases","Volume decreases","Volume stays the same","Volume becomes zero"],"ans":1,"exp":"Boyle's Law states that pressure and volume are inversely related at constant temperature, so increasing pressure decreases volume."},{"q":"According to Charles's Law, what happens to the volume of a gas when its temperature increases at constant pressure?","ch":["Volume decreases","Volume stays exactly the same","Volume increases","Volume becomes negative"],"ans":2,"exp":"Charles's Law states that volume and temperature are directly related at constant pressure, so heating a gas causes it to expand."},{"q":"What does the ideal gas law equation PV = nRT relate?","ch":["Pressure, volume, moles, and temperature of a gas","Only the mass and volume of a liquid","The speed and mass of a solid object","The color and density of a gas"],"ans":0,"exp":"The ideal gas law, PV = nRT, relates pressure (P), volume (V), number of moles (n), and temperature (T) of a gas, with R as the gas constant."},{"q":"In gas law calculations, what temperature scale must be used?","ch":["Fahrenheit","Celsius","Any scale works equally well","Kelvin"],"ans":3,"exp":"Gas law equations require temperature in Kelvin because Kelvin has no negative values, which would otherwise cause errors like negative volume."},{"q":"What is standard temperature and pressure (STP) commonly defined as?","ch":["0 degrees C and 1 atm","100 degrees C and 2 atm","25 degrees C and 0.5 atm","-40 degrees C and 1 atm"],"ans":0,"exp":"Standard temperature and pressure is commonly defined as 0 degrees Celsius (273 K) and 1 atmosphere of pressure."},{"q":"According to Avogadro's Law, what happens to the volume of a gas as the number of moles increases at constant temperature and pressure?","ch":["Volume decreases","Volume stays the same","Volume increases","Volume becomes unpredictable"],"ans":2,"exp":"Avogadro's Law states that volume is directly proportional to the number of moles of gas at constant temperature and pressure, so more gas particles means more volume."},{"q":"A balloon is placed in a freezer and shrinks in size. Which gas law best explains this observation?","ch":["Boyle's Law","Charles's Law","Avogadro's Law","The law of conservation of mass"],"ans":1,"exp":"Charles's Law explains that cooling a gas at constant pressure decreases its volume, which is why the balloon shrinks in the cold freezer."},{"q":"What happens to gas pressure inside a rigid, sealed container if the temperature is increased?","ch":["Pressure decreases","Pressure becomes zero","Pressure stays the same","Pressure increases"],"ans":3,"exp":"In a fixed volume, increasing temperature makes gas particles move faster and collide with the container walls more forcefully, increasing pressure."}]},
{"id":"fps10","cat":"Physical Sciences","title":"Energy in Chemical Reactions","diff":"Medium","qs":[{"q":"What is an exothermic reaction?","ch":["A reaction that absorbs energy from its surroundings","A reaction that releases energy to its surroundings, often as heat","A reaction that requires a catalyst to occur","A reaction that never produces products"],"ans":1,"exp":"Exothermic reactions release energy, usually as heat, into the surroundings, which is why the surrounding area often feels warmer."},{"q":"What is an endothermic reaction?","ch":["A reaction that absorbs energy from its surroundings","A reaction that releases energy as light only","A reaction that always happens instantly","A reaction that produces no products"],"ans":0,"exp":"Endothermic reactions absorb energy from their surroundings, which often makes the surrounding area feel colder."},{"q":"Which of the following is a common example of an exothermic reaction?","ch":["Melting an ice cube","Photosynthesis in plants","Burning wood in a campfire","Evaporating water from a puddle"],"ans":2,"exp":"Combustion, such as burning wood, releases a large amount of heat and light energy, making it a classic exothermic reaction."},{"q":"What is a catalyst?","ch":["A device used to measure temperature","A substance that is always a product of a reaction","A type of chemical bond","A substance that speeds up a reaction without being permanently consumed"],"ans":3,"exp":"A catalyst speeds up the rate of a chemical reaction by lowering the activation energy, without being permanently used up in the process."},{"q":"What is activation energy?","ch":["The total energy released by a reaction","The minimum energy needed to start a chemical reaction","The energy stored in a battery","The energy of the products only"],"ans":1,"exp":"Activation energy is the minimum amount of energy required for reactant particles to collide and successfully react, forming products."},{"q":"How does increasing temperature typically affect the rate of a chemical reaction?","ch":["It has no effect on reaction rate","It generally slows down the reaction rate","It generally speeds up the reaction rate","It stops the reaction completely"],"ans":2,"exp":"Higher temperatures give particles more kinetic energy, causing more frequent and forceful collisions, which generally speeds up reaction rate."},{"q":"In a chemical reaction, what happens to the total energy of the system according to the law of conservation of energy?","ch":["Energy is neither created nor destroyed, only converted from one form to another","Energy is destroyed during the reaction","Energy is created during the reaction","Energy has no role in chemical reactions"],"ans":0,"exp":"The law of conservation of energy states energy cannot be created or destroyed during a chemical reaction, only transformed, such as chemical energy converting to heat."},{"q":"Why does increasing the concentration of reactants typically increase the rate of a reaction?","ch":["It decreases the temperature of the system","It changes the reactants into products instantly","It removes the need for activation energy","It increases the frequency of collisions between reactant particles"],"ans":3,"exp":"A higher concentration means more reactant particles are packed into the same space, so they collide more often, increasing the reaction rate."}]},
{"id":"fps11","cat":"Physical Sciences","title":"Introduction to Organic Chemistry","diff":"Easy","qs":[{"q":"What element is the basis of organic chemistry, present in nearly all organic compounds?","ch":["Oxygen","Carbon","Nitrogen","Silicon"],"ans":1,"exp":"Organic chemistry is the study of carbon-containing compounds, since carbon forms the backbone of nearly all organic molecules."},{"q":"Why is carbon especially well suited to forming a huge variety of compounds?","ch":["It can form four bonds and link into chains, rings, and branches","It can only form one bond at a time","It is the heaviest common element","It never bonds with hydrogen"],"ans":0,"exp":"Carbon has four valence electrons, allowing it to form four covalent bonds and create long chains, branches, and rings with other atoms."},{"q":"What is the simplest organic compound, made of only carbon and hydrogen, called CH4?","ch":["Ethanol","Propane","Methane","Glucose"],"ans":2,"exp":"Methane (CH4) is the simplest hydrocarbon, consisting of a single carbon atom bonded to four hydrogen atoms."},{"q":"What term describes organic compounds made up of only carbon and hydrogen atoms?","ch":["Carbohydrates","Amino acids","Alcohols","Hydrocarbons"],"ans":3,"exp":"Hydrocarbons are organic compounds composed entirely of carbon and hydrogen atoms, such as methane and propane."},{"q":"What is the main difference between organic and inorganic compounds in basic terms?","ch":["Organic compounds never contain hydrogen","Organic compounds are generally based on carbon, while most inorganic compounds are not","Inorganic compounds are always liquids","There is no meaningful difference"],"ans":1,"exp":"Organic chemistry focuses on carbon-based compounds, while inorganic chemistry generally covers compounds without carbon-hydrogen backbones, like salts and minerals."},{"q":"Which of the following is an example of a simple organic molecule found in living things?","ch":["Glucose (a sugar)","Table salt (NaCl)","Water (H2O)","Oxygen gas (O2)"],"ans":0,"exp":"Glucose is a carbon-based sugar molecule that living organisms use for energy, making it a classic organic compound."},{"q":"What do we call organic compounds that have the same molecular formula but different arrangements of atoms?","ch":["Isotopes","Ions","Isomers","Elements"],"ans":2,"exp":"Isomers are compounds that share the same molecular formula but have different structural arrangements of their atoms, giving them different properties."},{"q":"Which of these is a functional group commonly found in organic alcohols?","ch":["The carboxyl group","The nitro group","The amino group","The hydroxyl group (-OH)"],"ans":3,"exp":"Alcohols are organic compounds identified by the presence of a hydroxyl group (-OH) attached to a carbon chain."}]},
{"id":"fps12","cat":"Physical Sciences","title":"Physical vs Chemical Changes","diff":"Easy","qs":[{"q":"What is a physical change?","ch":["A change that creates a brand new substance","A change in the form or appearance of a substance without forming a new substance","A change that always involves burning","A change that cannot be reversed"],"ans":1,"exp":"A physical change alters the appearance, shape, or state of matter, but the chemical identity of the substance stays the same."},{"q":"What is a chemical change?","ch":["A change where a new substance with different properties is formed","A change in the shape of an object only","A change that always happens slowly","A change that never releases energy"],"ans":0,"exp":"A chemical change occurs when substances react to form one or more new substances with different chemical properties than the starting materials."},{"q":"Which of the following is an example of a physical change?","ch":["Rusting of an iron nail","Burning a candle wick","Cutting a piece of paper into smaller pieces","Digesting food in the stomach"],"ans":2,"exp":"Cutting paper changes its size and shape, but the paper is still made of the same material, so it is a physical change."},{"q":"Which of the following is an example of a chemical change?","ch":["Melting butter in a pan","Crushing a can","Boiling water into steam","Baking a cake"],"ans":3,"exp":"Baking a cake involves chemical reactions between ingredients that create new substances, making it a chemical change."},{"q":"Which observation is strong evidence that a chemical change has occurred?","ch":["The object changed shape","Bubbles of gas formed along with a color change and heat release","The substance became colder to the touch briefly","The substance was moved to a new container"],"ans":1,"exp":"Gas formation, a color change, and a release of heat together are strong signs that a new substance has formed through a chemical reaction."},{"q":"Is dissolving sugar in water a physical or chemical change?","ch":["A physical change, because the sugar and water can be separated and are still sugar and water","A chemical change, because a new substance forms","Neither, because nothing has changed","A nuclear change"],"ans":0,"exp":"When sugar dissolves in water, no new substance forms; the sugar and water can be separated again by evaporation, so it is a physical change."},{"q":"Which of these changes of state is considered a physical change?","ch":["Milk souring into yogurt","Wood burning into ash and smoke","Water freezing into ice","Bread turning moldy"],"ans":2,"exp":"Freezing water into ice only changes its state, not its chemical identity, since it is still H2O, making it a physical change."},{"q":"Why is burning (combustion) always classified as a chemical change?","ch":["Because it only changes the temperature of the fuel","Because it does not release any energy","Because it can always be reversed easily","Because the fuel combines with oxygen to form entirely new substances like carbon dioxide and water"],"ans":3,"exp":"Combustion reacts a fuel with oxygen to produce new substances, typically carbon dioxide and water, which is why it is a chemical change."}]},
{"id":"fps13","cat":"Physical Sciences","title":"Density & Scientific Measurement","diff":"Easy","qs":[{"q":"What is the formula for calculating density?","ch":["Density = mass x volume","Density = mass / volume","Density = volume / mass","Density = mass + volume"],"ans":1,"exp":"Density is calculated by dividing an object's mass by its volume (D = m/V)."},{"q":"What are common units used to express the density of a liquid?","ch":["Grams per milliliter (g/mL)","Meters per second","Newtons","Degrees Celsius"],"ans":0,"exp":"Density of liquids and solids is commonly expressed in grams per milliliter (g/mL) or grams per cubic centimeter (g/cm^3)."},{"q":"If an object has a density less than that of water (1 g/mL), what will happen when it is placed in water?","ch":["It will sink to the bottom","It will dissolve completely","It will float on the surface","It will explode"],"ans":2,"exp":"Objects less dense than water float on its surface, which is why oil, which has a lower density than water, floats."},{"q":"A block has a mass of 20 grams and a volume of 4 mL. What is its density?","ch":["4 g/mL","80 g/mL","16 g/mL","5 g/mL"],"ans":3,"exp":"Density = mass / volume = 20 g / 4 mL = 5 g/mL."},{"q":"Which laboratory tool is best used to measure the volume of a liquid?","ch":["A triple beam balance","A thermometer","A graduated cylinder","A meter stick"],"ans":2,"exp":"A graduated cylinder is designed with volume markings specifically to measure the volume of liquids accurately."},{"q":"Which laboratory tool is best used to measure the mass of an object?","ch":["A graduated cylinder","A balance (scale)","A ruler","A stopwatch"],"ans":1,"exp":"A balance, such as a triple beam balance or electronic scale, is used to measure the mass of objects in the lab."},{"q":"What is the standard SI unit for measuring length?","ch":["Meter","Liter","Gram","Second"],"ans":0,"exp":"The meter is the standard SI (International System) base unit for measuring length or distance."},{"q":"If you double the mass of a sample while keeping its volume the same, what happens to its density?","ch":["Density stays the same","Density is cut in half","Density becomes zero","Density doubles"],"ans":3,"exp":"Since density = mass / volume, doubling the mass while volume stays constant will double the density."}]},
{"id":"fps14","cat":"Physical Sciences","title":"Elements, Compounds & Mixtures","diff":"Easy","qs":[{"q":"What is an element?","ch":["A pure substance made of only one type of atom","A combination of two or more substances mixed physically","A substance that always exists as a gas","A material with a fixed recipe of ingredients"],"ans":0,"exp":"An element is a pure substance made up of only one type of atom, such as oxygen, gold, or hydrogen, and cannot be broken down into simpler substances chemically."},{"q":"What is a compound?","ch":["Any substance that contains carbon","Two or more elements chemically combined in a fixed ratio","A physical blend of two liquids","A pure element in its natural state"],"ans":1,"exp":"A compound forms when two or more elements chemically bond together in a fixed, definite ratio, such as water (H2O) or table salt (NaCl)."},{"q":"What is a mixture?","ch":["A single pure element","A substance formed only through chemical bonding","Two or more substances physically combined without chemically bonding","A compound that has been heated"],"ans":2,"exp":"A mixture is created when two or more substances are physically combined but not chemically bonded, so each substance keeps its own properties."},{"q":"Which of the following is an example of an element?","ch":["Water","Table salt","Air","Oxygen gas (O2)"],"ans":3,"exp":"Oxygen gas is composed of only one type of atom, oxygen, making it an element rather than a compound or mixture."},{"q":"Which of the following is an example of a compound?","ch":["Iron","Carbon dioxide (CO2)","Nitrogen gas (N2)","Sand and water stirred together"],"ans":1,"exp":"Carbon dioxide is formed from carbon and oxygen chemically bonded together in a fixed 1:2 ratio, making it a compound."},{"q":"Which of the following is an example of a mixture?","ch":["Table salt (NaCl)","Pure gold","Salad, made of lettuce, tomatoes, and other ingredients","Water (H2O)"],"ans":2,"exp":"A salad is a mixture because its ingredients are physically combined but not chemically bonded, and each ingredient keeps its own identity."},{"q":"What distinguishes a homogeneous mixture from a heterogeneous mixture?","ch":["A homogeneous mixture has uniform composition throughout, while a heterogeneous mixture does not","A homogeneous mixture always contains only one substance","A heterogeneous mixture cannot be separated","There is no real difference between the two"],"ans":0,"exp":"A homogeneous mixture, like saltwater, has the same composition throughout, while a heterogeneous mixture, like sand and gravel, has visibly different regions."},{"q":"Which method could be used to separate a mixture of sand and water?","ch":["Nuclear fission","Combustion","Chemical bonding","Filtration"],"ans":3,"exp":"Because sand and water are only physically mixed and not chemically combined, filtration can easily separate the solid sand from the liquid water."}]},
{"id":"fps15","cat":"Physical Sciences","title":"The pH Scale & Indicators","diff":"Easy","qs":[{"q":"What is the typical range of the pH scale?","ch":["0 to 7","0 to 14","1 to 100","-7 to 7"],"ans":1,"exp":"The pH scale commonly ranges from 0 to 14, with lower numbers indicating acids and higher numbers indicating bases."},{"q":"What pH value represents a neutral substance, like pure water?","ch":["7","0","10","14"],"ans":0,"exp":"A pH of 7 is considered neutral, meaning the substance is neither acidic nor basic, as is the case with pure water."},{"q":"A solution with a pH of 3 would be considered what?","ch":["Strongly basic","Neutral","Acidic","Impossible to determine"],"ans":2,"exp":"Any pH value below 7 indicates an acidic solution, and a pH of 3 is fairly strongly acidic."},{"q":"A solution with a pH of 11 would be considered what?","ch":["Acidic","Neutral","Radioactive","Basic (alkaline)"],"ans":3,"exp":"Any pH value above 7 indicates a basic, or alkaline, solution, and a pH of 11 is fairly strongly basic."},{"q":"As pH values decrease from 7 down toward 0, what happens to the acidity of the solution?","ch":["Acidity decreases","Acidity increases","The solution becomes basic","There is no change in acidity"],"ans":1,"exp":"As pH decreases below 7, the solution becomes more acidic, with lower pH numbers indicating stronger acids."},{"q":"What color does blue litmus paper turn when dipped in an acidic solution?","ch":["It turns red","It stays blue","It turns green","It turns black"],"ans":0,"exp":"Blue litmus paper turns red when exposed to an acid, which is a classic simple test used to identify acidic solutions."},{"q":"What color does red litmus paper turn when dipped in a basic solution?","ch":["It stays red","It turns yellow","It turns blue","It turns clear"],"ans":2,"exp":"Red litmus paper turns blue when exposed to a base, which is a simple way to identify basic (alkaline) solutions."},{"q":"Which of the following substances would you expect to have a pH close to 7 (neutral)?","ch":["Lemon juice","Battery acid","Oven cleaner","Pure distilled water"],"ans":3,"exp":"Pure distilled water is neither acidic nor basic, giving it a pH close to 7, the neutral point on the pH scale."}]},
{"id":"fps16","cat":"Physical Sciences","title":"Basic Chemistry Lab Safety & Equipment","diff":"Easy","qs":[{"q":"What should you always wear to protect your eyes during a chemistry lab experiment?","ch":["Sunglasses","Safety goggles","Reading glasses","No eye protection is necessary"],"ans":1,"exp":"Safety goggles are required in the lab to protect your eyes from splashes, fumes, and other hazards during experiments."},{"q":"What should you do first if a chemical splashes into your eyes during a lab experiment?","ch":["Rub your eyes to remove the chemical","Wait a few minutes to see if it stops stinging","Immediately flush your eyes with water at the eyewash station","Cover your eyes and leave the room"],"ans":2,"exp":"Chemical splashes in the eyes require immediate flushing with water at an eyewash station for several minutes, followed by notifying the teacher."},{"q":"What piece of lab equipment is specifically used to measure the volume of a liquid accurately?","ch":["A graduated cylinder","A beaker","A test tube","A watch glass"],"ans":0,"exp":"While beakers give a rough estimate, a graduated cylinder is the appropriate tool for accurately measuring liquid volume."},{"q":"What should you do before starting any new lab experiment?","ch":["Taste any unknown substances to identify them","Mix chemicals randomly to see what happens","Skip the safety instructions to save time","Read the entire lab procedure and safety instructions carefully"],"ans":3,"exp":"Reading the full lab procedure and safety instructions beforehand helps you understand the correct steps and avoid accidents."},{"q":"Why should you never taste or smell chemicals directly in a lab, unless specifically instructed to gently waft the odor?","ch":["It wastes the chemical","Chemicals could be toxic, corrosive, or otherwise harmful if ingested or inhaled directly","It is against school policy for no particular reason","Tasting chemicals is actually encouraged in most labs"],"ans":1,"exp":"Many lab chemicals are toxic or corrosive, so tasting them or inhaling them directly can cause serious harm."},{"q":"What is the correct action to take immediately if your clothing catches fire during a lab activity?","ch":["Stop, drop, and roll, or use a safety shower if available","Run to get help from another room","Fan the flames to put them out","Pour any nearby liquid on yourself"],"ans":0,"exp":"The stop, drop, and roll technique, or use of a safety shower, smothers flames and is the correct emergency response for burning clothing."},{"q":"What piece of equipment is used to hold a test tube safely while heating it over a flame?","ch":["A ruler","Bare hands","A test tube holder (clamp)","A stirring rod"],"ans":2,"exp":"A test tube holder, or clamp, allows you to safely hold a hot test tube without directly touching it with your hands."},{"q":"Where should long hair and loose clothing be kept during a lab experiment involving an open flame?","ch":["It does not matter as long as goggles are worn","Only a concern if using chemicals, not flames","Draped loosely for comfort","Tied back and secured away from the flame"],"ans":3,"exp":"Long hair and loose clothing must be tied back and secured to prevent them from catching fire near an open flame, such as a Bunsen burner."}]},
{"id":"fps17","cat":"Physical Sciences","title":"Motion, Speed & Velocity Basics","diff":"Easy","qs":[{"q":"What is the formula for average speed?","ch":["Distance divided by time","Time divided by distance","Mass divided by time","Force divided by mass"],"ans":0,"exp":"Average speed is calculated by dividing the total distance traveled by the total time taken."},{"q":"Which of the following is a vector quantity?","ch":["Speed","Distance","Velocity","Time"],"ans":2,"exp":"Velocity is a vector because it includes both magnitude (how fast) and direction, unlike speed which is a scalar."},{"q":"What is the SI unit of speed?","ch":["Kilograms","Meters per second","Newtons","Joules"],"ans":1,"exp":"Speed is distance over time, so its SI unit is meters per second (m/s)."},{"q":"A car travels 100 meters in 20 seconds. What is its average speed?","ch":["2 m/s","20 m/s","0.2 m/s","5 m/s"],"ans":3,"exp":"Speed equals distance divided by time: 100 m divided by 20 s equals 5 m/s."},{"q":"What distinguishes velocity from speed?","ch":["Velocity includes direction, speed does not","Velocity is always larger than speed","Speed includes direction, velocity does not","There is no difference"],"ans":0,"exp":"Velocity is speed with a direction attached, making it a vector quantity while speed is a scalar."},{"q":"If a runner covers 400 meters in 50 seconds, what is her average speed?","ch":["4 m/s","50 m/s","400 m/s","8 m/s"],"ans":3,"exp":"Dividing 400 meters by 50 seconds gives an average speed of 8 m/s."},{"q":"An object that is not moving has a speed of...","ch":["1 m/s","0 m/s","Undefined","Negative"],"ans":1,"exp":"An object at rest is not covering any distance over time, so its speed is 0 m/s."},{"q":"A car moving with constant velocity...","ch":["Is accelerating rapidly","Is changing direction constantly","Moves at a constant speed in a straight line","Is speeding up"],"ans":2,"exp":"Constant velocity means both the speed and the direction of motion stay the same, so the object travels in a straight line at a steady speed."}]},
{"id":"fps18","cat":"Physical Sciences","title":"Newton's Laws of Motion","diff":"Easy","qs":[{"q":"According to Newton's First Law, an object at rest will...","ch":["Always start moving","Remain at rest unless acted on by a net force","Accelerate on its own","Increase in mass"],"ans":1,"exp":"Newton's First Law (the law of inertia) states that an object at rest stays at rest unless a net external force acts on it."},{"q":"Newton's Second Law is expressed by the equation...","ch":["v = d/t","p = mv","W = Fd","F = ma"],"ans":3,"exp":"Newton's Second Law states that force equals mass times acceleration, written as F = ma."},{"q":"Newton's Third Law states that...","ch":["For every action there is an equal and opposite reaction","Objects in motion stay in motion","Force equals mass times acceleration","Energy cannot be created or destroyed"],"ans":0,"exp":"Newton's Third Law says that whenever one object exerts a force on another, the second object exerts an equal and opposite force back."},{"q":"A 10 kg object accelerates at 2 m/s^2. What net force is acting on it?","ch":["5 N","2 N","20 N","10 N"],"ans":2,"exp":"Using F = ma, 10 kg multiplied by 2 m/s^2 equals 20 N of net force."},{"q":"Which law explains why a passenger lurches forward when a car suddenly stops?","ch":["Third Law","Second Law","Law of gravity","First Law (inertia)"],"ans":3,"exp":"The passenger's body tends to keep moving forward due to inertia, which is described by Newton's First Law."},{"q":"Inertia is best described as...","ch":["An object's tendency to resist changes in motion","The force of gravity on an object","The speed of an object","The energy stored in an object"],"ans":0,"exp":"Inertia is the natural tendency of any object to resist a change in its state of motion or rest."},{"q":"If a net force of 15 N is applied to a 3 kg object, what is its acceleration?","ch":["45 m/s^2","3 m/s^2","5 m/s^2","15 m/s^2"],"ans":2,"exp":"Rearranging F = ma gives a = F/m, so 15 N divided by 3 kg equals 5 m/s^2."},{"q":"When you push on a wall, the wall pushes back on you with...","ch":["No force at all","An equal and opposite force","A smaller force","A much larger force"],"ans":1,"exp":"By Newton's Third Law, the wall exerts a force on you that is equal in size and opposite in direction to the force you exert on it."}]},
{"id":"fps19","cat":"Physical Sciences","title":"Force & Gravity Basics","diff":"Easy","qs":[{"q":"Weight is best defined as...","ch":["The amount of matter in an object","The resistance of an object to motion","The force of gravity acting on an object's mass","The speed of a falling object"],"ans":2,"exp":"Weight is a force, specifically the pull of gravity on an object's mass, and is measured in Newtons."},{"q":"On Earth, objects in free fall accelerate at approximately...","ch":["9.8 m/s^2","1 m/s^2","100 m/s^2","0 m/s^2"],"ans":0,"exp":"Near Earth's surface, gravity accelerates falling objects at approximately 9.8 meters per second squared."},{"q":"Which of these is NOT a unit of force?","ch":["Newton","Pound","Dyne","Joule"],"ans":3,"exp":"A Joule measures energy or work, not force; Newtons, pounds, and dynes are all units of force."},{"q":"Mass differs from weight because mass...","ch":["Changes depending on gravity","Stays the same regardless of location","Is measured in Newtons","Is a type of force"],"ans":1,"exp":"Mass is the amount of matter in an object and does not change with location, unlike weight, which depends on local gravity."},{"q":"An object with a mass of 5 kg has a weight on Earth of approximately...","ch":["5 N","0.5 N","49 N","500 N"],"ans":2,"exp":"Weight equals mass times gravitational acceleration: 5 kg times 9.8 m/s^2 is approximately 49 N."},{"q":"Friction is a force that...","ch":["Always speeds up motion","Opposes relative motion between surfaces","Only occurs in liquids","Increases an object's mass"],"ans":1,"exp":"Friction is a resistive force that opposes the relative motion or attempted motion between two surfaces in contact."},{"q":"Gravity between two objects gets weaker as...","ch":["The distance between them increases","Their masses increase","Time passes","They get closer together"],"ans":0,"exp":"The gravitational force between two objects decreases as the distance between them increases."},{"q":"A net force of zero acting on an object means the object is...","ch":["Speeding up","Slowing down","Changing direction","In equilibrium (constant velocity or at rest)"],"ans":3,"exp":"When the net force on an object is zero, the object is in equilibrium and moves at constant velocity or remains at rest."}]},
{"id":"fps20","cat":"Physical Sciences","title":"Work, Energy & Power Basics","diff":"Easy","qs":[{"q":"Work is done on an object when...","ch":["The object stays still under force","Energy disappears","Time passes while holding an object","A force causes the object to move in the direction of the force"],"ans":3,"exp":"In physics, work is done only when a force causes displacement in the direction of that force."},{"q":"The SI unit of work and energy is the...","ch":["Newton","Joule","Watt","Pascal"],"ans":1,"exp":"Work and energy are both measured in Joules in the SI system."},{"q":"Power is defined as...","ch":["Force times distance","Mass times velocity","The rate at which work is done","Energy stored in a spring"],"ans":2,"exp":"Power measures how quickly work is done or energy is transferred, calculated as work divided by time."},{"q":"If you push a box with 20 N of force and it moves 5 meters in the direction of the push, how much work is done?","ch":["100 J","4 J","25 J","15 J"],"ans":0,"exp":"Work equals force times distance: 20 N multiplied by 5 m equals 100 J."},{"q":"Kinetic energy depends on an object's...","ch":["Weight and height only","Mass and speed","Temperature","Color"],"ans":1,"exp":"Kinetic energy is calculated as one-half times mass times velocity squared, so it depends on an object's mass and speed."},{"q":"The SI unit of power is the...","ch":["Joule","Newton","Watt","Volt"],"ans":2,"exp":"Power, the rate of doing work, is measured in Watts, where one Watt equals one Joule per second."},{"q":"A machine that does 200 J of work in 4 seconds has a power output of...","ch":["800 W","4 W","200 W","50 W"],"ans":3,"exp":"Power equals work divided by time: 200 J divided by 4 s equals 50 W."},{"q":"Potential energy due to an object's height above the ground is called...","ch":["Gravitational potential energy","Kinetic energy","Thermal energy","Electrical energy"],"ans":0,"exp":"Energy stored because of an object's height in a gravitational field is called gravitational potential energy."}]},
{"id":"fps21","cat":"Physical Sciences","title":"Basic Electricity & Circuits","diff":"Medium","qs":[{"q":"Electric current is measured in...","ch":["Amperes","Volts","Ohms","Watts"],"ans":0,"exp":"Electric current, the flow of charge, is measured in Amperes (amps)."},{"q":"Voltage is best described as...","ch":["The rate of flow of charge","The resistance to current flow","The power used by a circuit","The electrical potential difference that drives current"],"ans":3,"exp":"Voltage is the electrical potential difference between two points that pushes current through a circuit."},{"q":"According to Ohm's Law, V = ...","ch":["I/R","I x R","R/I","I + R"],"ans":1,"exp":"Ohm's Law states that voltage equals current multiplied by resistance, or V = I x R."},{"q":"In a series circuit, if one bulb burns out, the other bulbs...","ch":["Get brighter","Stay the same","Also go out","Change color"],"ans":2,"exp":"A series circuit has only one path for current, so breaking that path at any point stops current everywhere and all bulbs go out."},{"q":"In a parallel circuit, if one bulb burns out, the other bulbs...","ch":["Continue to work normally","Also go out","Get dimmer only","Explode"],"ans":0,"exp":"In a parallel circuit, each bulb has its own separate path, so the other bulbs keep working even if one fails."},{"q":"A circuit with a resistance of 5 ohms and a current of 2 amps has a voltage of...","ch":["2.5 V","7 V","10 V","3 V"],"ans":2,"exp":"Using V = I x R, 2 amps multiplied by 5 ohms equals 10 volts."},{"q":"Which material is a good electrical conductor?","ch":["Rubber","Glass","Wood","Copper"],"ans":3,"exp":"Copper is a metal with free-moving electrons, making it an excellent conductor of electricity."},{"q":"An open switch in a circuit...","ch":["Allows current to flow","Breaks the circuit and stops current flow","Increases the voltage","Has no effect on the circuit"],"ans":1,"exp":"An open switch creates a gap in the circuit path, which stops the flow of current entirely."}]},
{"id":"fps22","cat":"Physical Sciences","title":"Basic Magnetism","diff":"Easy","qs":[{"q":"Like magnetic poles (N-N or S-S)...","ch":["Always attract","Repel each other","Have no effect on each other","Merge together"],"ans":1,"exp":"Two like magnetic poles, such as north-north or south-south, always repel one another."},{"q":"Opposite magnetic poles (N-S)...","ch":["Repel each other","Have no interaction","Attract each other","Cancel each other's field"],"ans":2,"exp":"A north pole and a south pole are opposite poles and always attract each other."},{"q":"A magnetic field is strongest...","ch":["Near the poles of a magnet","At the exact center of a magnet","Far away from the magnet","Only inside a magnet"],"ans":0,"exp":"Magnetic field lines are most concentrated near the poles, which is where the magnetic force is strongest."},{"q":"An electromagnet is created by...","ch":["Heating a piece of iron","Freezing a piece of metal","Rubbing two magnets together","Passing electric current through a coil of wire"],"ans":3,"exp":"An electromagnet is made by running electric current through a coiled wire, which generates a magnetic field."},{"q":"Which of these materials is attracted to a magnet?","ch":["Aluminum foil","Iron nail","Plastic ruler","Glass cup"],"ans":1,"exp":"Iron is a ferromagnetic material and is strongly attracted to magnets, unlike aluminum, plastic, or glass."},{"q":"The Earth behaves like a giant...","ch":["Electric current","Radio wave","Light source","Bar magnet"],"ans":3,"exp":"Earth's core generates a magnetic field similar to that of a giant bar magnet, which is why compasses work."},{"q":"Magnetic field lines around a bar magnet travel from...","ch":["North pole to south pole outside the magnet","South pole to north pole outside the magnet","Only through the middle","They do not form a pattern"],"ans":0,"exp":"Outside a bar magnet, magnetic field lines emerge from the north pole and curve around to enter the south pole."},{"q":"A compass needle points north because...","ch":["It is repelled by the sun","It is attracted to the equator","It aligns with Earth's magnetic field","It contains no magnetic material"],"ans":2,"exp":"A compass needle is a small magnet that aligns itself with Earth's magnetic field, pointing roughly toward magnetic north."}]},
{"id":"fps23","cat":"Physical Sciences","title":"Waves Basics — Sound & Light","diff":"Easy","qs":[{"q":"Sound waves are an example of...","ch":["Electromagnetic waves","Waves that travel through vacuum","Mechanical waves that need a medium","Waves with no frequency"],"ans":2,"exp":"Sound is a mechanical wave that requires a medium like air, water, or solids to travel through."},{"q":"Light waves are an example of...","ch":["Waves that need air to travel","Sound waves","Mechanical waves","Electromagnetic waves that can travel through vacuum"],"ans":3,"exp":"Light is an electromagnetic wave, so unlike sound, it does not need a medium and can travel through empty space."},{"q":"The pitch of a sound is related to its...","ch":["Amplitude","Frequency","Speed","Color"],"ans":1,"exp":"Pitch is determined by the frequency of a sound wave; higher frequency means a higher pitch."},{"q":"The loudness of a sound is related to its...","ch":["Amplitude","Frequency","Wavelength","Wave speed"],"ans":0,"exp":"Loudness depends on the amplitude of a sound wave; larger amplitude produces a louder sound."},{"q":"Wavelength is best defined as...","ch":["The speed of a wave","The loudness of a wave","The distance between two consecutive crests (or troughs) of a wave","The number of waves per second"],"ans":2,"exp":"Wavelength is the physical distance between two successive crests or troughs of a wave."},{"q":"Frequency is measured in units called...","ch":["Hertz","Meters","Newtons","Decibels"],"ans":0,"exp":"Frequency, the number of wave cycles per second, is measured in Hertz (Hz)."},{"q":"Sound cannot travel through...","ch":["Air","A vacuum (empty space)","Water","Solid metal"],"ans":1,"exp":"Sound needs particles of a medium to travel, so it cannot travel through a vacuum, which has no particles."},{"q":"The speed of light is approximately...","ch":["343 m/s","1,000 m/s","9.8 m/s","300,000 km/s"],"ans":3,"exp":"Light travels at about 300,000 kilometers per second in a vacuum, far faster than sound."}]},
{"id":"fps24","cat":"Physical Sciences","title":"Basic Optics — Reflection & Refraction","diff":"Easy","qs":[{"q":"The law of reflection states that...","ch":["Light always bends toward a surface","Light speeds up after reflecting","All light is absorbed by mirrors","The angle of incidence equals the angle of reflection"],"ans":3,"exp":"The law of reflection states that the angle at which light hits a surface equals the angle at which it bounces off."},{"q":"Refraction occurs when light...","ch":["Passes from one medium into another and bends","Reflects off a flat mirror","Is completely absorbed by an object","Travels in a perfect vacuum"],"ans":0,"exp":"Refraction is the bending of light as it passes from one medium into another, caused by a change in speed."},{"q":"A plane mirror produces an image that is...","ch":["Smaller and inverted","Larger and inverted","The same size and upright, but reversed left-right","Blurry and colorless"],"ans":2,"exp":"A flat mirror produces a same-size, upright image that appears reversed left to right, known as a mirror image."},{"q":"Light bends when entering water from air because...","ch":["Water absorbs all light","Light changes speed when moving between media","Water is a light source","Light stops moving in water"],"ans":1,"exp":"Light travels at different speeds in different materials, and this change in speed causes it to bend, or refract."},{"q":"A convex lens (like a magnifying glass) causes light rays to...","ch":["Spread apart","Reflect backward","Stay perfectly parallel","Converge toward a focal point"],"ans":3,"exp":"A convex lens is thicker in the middle and bends light rays inward so they converge at a focal point."},{"q":"A concave lens causes light rays to...","ch":["Converge to a single point","Diverge (spread apart)","Reverse direction completely","Stop entirely"],"ans":1,"exp":"A concave lens is thinner in the middle and causes parallel light rays to spread apart, or diverge."},{"q":"The normal line used in optics diagrams is...","ch":["A line perpendicular to the surface at the point of contact","A line parallel to the surface","The path of the reflected ray only","Always drawn in red"],"ans":0,"exp":"The normal is an imaginary line drawn perpendicular to a surface, used as a reference for measuring angles of incidence and reflection."},{"q":"Which surface reflects light in a scattered (diffuse) way rather than a clear image?","ch":["A smooth polished mirror","Still water","A rough, bumpy surface","Perfectly flat glass"],"ans":2,"exp":"Rough or bumpy surfaces scatter light in many directions, producing diffuse reflection instead of a clear image."}]},
{"id":"fps25","cat":"Physical Sciences","title":"Heat, Temperature & Thermal Energy","diff":"Easy","qs":[{"q":"Temperature is a measure of...","ch":["The average kinetic energy of particles in a substance","The total energy in an object","The mass of an object","The pressure of a gas"],"ans":0,"exp":"Temperature reflects the average kinetic energy of the particles making up a substance."},{"q":"Heat naturally flows from...","ch":["Cold objects to hot objects","Hot objects to cold objects","Objects of equal temperature only","It does not flow, it stays in place"],"ans":1,"exp":"Heat energy naturally flows from a region of higher temperature to a region of lower temperature until equilibrium is reached."},{"q":"Which method of heat transfer occurs through direct contact between particles?","ch":["Radiation","Convection","Evaporation","Conduction"],"ans":3,"exp":"Conduction transfers heat through direct contact, as fast-moving particles collide with and speed up neighboring particles."},{"q":"Convection is the transfer of heat through...","ch":["Empty space","Direct contact of solids","The movement of fluids (liquids or gases)","Sound waves"],"ans":2,"exp":"Convection transfers heat as warmer, less dense regions of a fluid rise and cooler regions sink, creating circulation."},{"q":"Radiation is a method of heat transfer that...","ch":["Does not require a medium and can travel through vacuum","Only occurs in solids","Requires direct contact","Only happens underwater"],"ans":0,"exp":"Radiation transfers heat as electromagnetic waves, which can travel through empty space without needing a medium."},{"q":"Water freezes at what temperature on the Celsius scale?","ch":["100 degrees C","37 degrees C","-40 degrees C","0 degrees C"],"ans":3,"exp":"Under normal atmospheric pressure, water freezes at 0 degrees Celsius."},{"q":"Water boils at what temperature on the Celsius scale at sea level?","ch":["0 degrees C","50 degrees C","100 degrees C","212 degrees C"],"ans":2,"exp":"At sea level, water boils at 100 degrees Celsius; 212 is the equivalent temperature in Fahrenheit, not Celsius."},{"q":"When a substance is heated, its particles generally...","ch":["Stop moving","Move faster and spread apart slightly","Become heavier","Lose mass"],"ans":1,"exp":"Adding heat increases the kinetic energy of particles, causing them to move faster and typically spread further apart."}]},
{"id":"fps26","cat":"Physical Sciences","title":"Simple Machines","diff":"Easy","qs":[{"q":"A simple machine makes work easier mainly by...","ch":["Creating extra energy from nothing","Changing the amount or direction of force needed","Eliminating the need for any force","Increasing the total work done"],"ans":1,"exp":"Simple machines make tasks easier by changing the size or direction of the force needed, not by creating new energy."},{"q":"A lever consists of a rigid bar that pivots around a point called the...","ch":["Fulcrum","Axle","Wedge","Pulley"],"ans":0,"exp":"The fixed pivot point of a lever, around which the bar rotates, is called the fulcrum."},{"q":"An inclined plane makes lifting a heavy object easier by...","ch":["Increasing the object's weight","Removing friction entirely","Allowing the force to be applied over a longer distance","Making the object lighter"],"ans":2,"exp":"An inclined plane lets you apply a smaller force over a longer distance instead of lifting the full weight straight up."},{"q":"A wheel and axle, pulley, wedge, screw, lever, and inclined plane are all examples of...","ch":["Electrical devices","Types of energy","Chemical reactions","Simple machines"],"ans":3,"exp":"These six devices are the classic simple machines that make work easier by redirecting or multiplying force."},{"q":"A pulley is most useful for...","ch":["Cutting objects apart","Changing the direction of an applied force to lift loads","Generating electricity","Measuring temperature"],"ans":1,"exp":"A pulley uses a wheel and rope or cable to change the direction of a force, making it easier to lift heavy loads."},{"q":"A screw can be thought of as...","ch":["A type of pulley","A straight lever","An inclined plane wrapped around a cylinder","A wedge with two sharp edges"],"ans":2,"exp":"A screw is essentially an inclined plane wound around a central cylinder, which converts rotational force into linear motion."},{"q":"A wedge is best described as two inclined planes joined to...","ch":["Push objects apart or split materials","Lift heavy loads vertically","Reduce the total force needed to zero","Spin continuously"],"ans":0,"exp":"A wedge, like an axe head, has two sloped surfaces meeting at an edge, used to push apart or split materials."},{"q":"Mechanical advantage refers to...","ch":["The total energy lost as heat","The weight of the machine itself","The speed at which a machine operates","How much a machine multiplies an input force"],"ans":3,"exp":"Mechanical advantage describes the factor by which a simple machine multiplies the input force applied to it."}]},
{"id":"fps27","cat":"Physical Sciences","title":"Basic Kinematics — Acceleration","diff":"Medium","qs":[{"q":"Acceleration is defined as...","ch":["Distance divided by time","Force divided by area","The rate of change of velocity over time","Mass times velocity"],"ans":2,"exp":"Acceleration measures how quickly velocity changes over time, whether in speed, direction, or both."},{"q":"The SI unit for acceleration is...","ch":["Meters per second","Meters per second squared","Newtons","Kilograms"],"ans":1,"exp":"Since acceleration is the change in velocity (m/s) per unit time, its SI unit is meters per second squared (m/s^2)."},{"q":"A car speeds up from 10 m/s to 30 m/s in 5 seconds. What is its acceleration?","ch":["4 m/s^2","2 m/s^2","20 m/s^2","6 m/s^2"],"ans":0,"exp":"Acceleration equals the change in velocity divided by time: (30 - 10) m/s divided by 5 s equals 4 m/s^2."},{"q":"If an object's velocity is decreasing over time, it is experiencing...","ch":["Zero acceleration","Increasing acceleration in the direction of motion","Constant velocity","Negative acceleration (deceleration)"],"ans":3,"exp":"When velocity decreases over time, the object has negative acceleration, often called deceleration."},{"q":"An object moving in a circle at constant speed is...","ch":["Not accelerating because speed is constant","Moving with zero net force","Accelerating because its direction is constantly changing","Impossible according to physics"],"ans":2,"exp":"Even at constant speed, an object moving in a circle constantly changes direction, so it is continuously accelerating."},{"q":"A ball starts from rest and reaches 20 m/s after 4 seconds. What is its average acceleration?","ch":["80 m/s^2","0.2 m/s^2","4 m/s^2","5 m/s^2"],"ans":3,"exp":"Acceleration equals change in velocity divided by time: 20 m/s divided by 4 s equals 5 m/s^2."},{"q":"On a velocity-time graph, the slope of the line represents...","ch":["Distance traveled","Acceleration","Speed only","Time elapsed"],"ans":1,"exp":"The slope of a velocity-time graph shows how velocity changes per unit time, which is acceleration."},{"q":"If acceleration is zero, an object's velocity is...","ch":["Constant (not changing)","Always zero","Always increasing","Always decreasing"],"ans":0,"exp":"Zero acceleration means the velocity is not changing, so the object moves at a constant velocity, which could be at rest or moving steadily."}]},
{"id":"fps28","cat":"Physical Sciences","title":"Energy Conservation Basics","diff":"Easy","qs":[{"q":"The law of conservation of energy states that energy...","ch":["Is created continuously in the universe","Always increases over time","Can be destroyed if enough force is applied","Cannot be created or destroyed, only transformed from one form to another"],"ans":3,"exp":"The law of conservation of energy states that total energy in a closed system stays constant, only changing form."},{"q":"As a ball falls, its potential energy is converted into...","ch":["Chemical energy","Sound energy only","Kinetic energy","Nuclear energy"],"ans":2,"exp":"As height decreases during a fall, gravitational potential energy converts into kinetic energy of motion."},{"q":"At the very top of a pendulum's swing, its energy is mostly...","ch":["Kinetic energy","Potential energy","Sound energy","Electrical energy"],"ans":1,"exp":"At the highest point of its swing, a pendulum momentarily stops moving, so its energy is almost entirely gravitational potential energy."},{"q":"In an ideal system with no friction, the total mechanical energy (potential plus kinetic)...","ch":["Remains constant","Continuously increases","Continuously decreases to zero","Disappears instantly"],"ans":0,"exp":"Without friction or air resistance, mechanical energy is conserved and the sum of potential and kinetic energy stays constant."},{"q":"Where does most of the 'lost' energy go in real-world systems with friction?","ch":["It is destroyed completely","It converts into mass","It disappears from the universe","It converts into heat (thermal energy)"],"ans":3,"exp":"Friction converts mechanical energy into thermal energy (heat), which is why energy seems 'lost' but is not actually destroyed."},{"q":"A roller coaster car at the bottom of a hill (moving fastest) has mostly...","ch":["Potential energy","Kinetic energy","No energy","Nuclear energy"],"ans":1,"exp":"At the bottom of a hill, the car has minimal height but maximum speed, meaning its energy is mostly kinetic."},{"q":"Which of these is an example of chemical potential energy?","ch":["Energy stored in a battery or food","The motion of a rolling ball","Light from the sun","Heat from a heater"],"ans":0,"exp":"Batteries and food store energy in chemical bonds, which is a form of chemical potential energy."},{"q":"A stretched rubber band or compressed spring stores what kind of energy?","ch":["Kinetic energy","Electrical energy","Elastic potential energy","Nuclear energy"],"ans":2,"exp":"Stretched or compressed elastic materials like rubber bands and springs store elastic potential energy."}]},
{"id":"fps29","cat":"Physical Sciences","title":"Basic Astronomy — The Solar System","diff":"Easy","qs":[{"q":"Which planet is closest to the Sun?","ch":["Venus","Mercury","Earth","Mars"],"ans":1,"exp":"Mercury orbits closest to the Sun, completing one orbit in about 88 days."},{"q":"What is the largest planet in our solar system?","ch":["Saturn","Neptune","Jupiter","Uranus"],"ans":2,"exp":"Jupiter is the largest planet, with a mass greater than all the other planets combined."},{"q":"Which celestial object is at the center of our solar system?","ch":["The Moon","Earth","A black hole","The Sun"],"ans":3,"exp":"The Sun is the star at the center of the solar system, and all the planets orbit around it."},{"q":"What causes Earth's seasons?","ch":["The tilt of Earth's axis as it orbits the Sun","The changing distance between Earth and the Sun","The Moon's gravitational pull","Solar flares"],"ans":0,"exp":"Earth's axial tilt of about 23.5 degrees causes different hemispheres to receive more or less direct sunlight throughout the year."},{"q":"Which of these is classified as a dwarf planet?","ch":["Mars","Mercury","Pluto","Neptune"],"ans":2,"exp":"Pluto was reclassified as a dwarf planet in 2006 because it has not cleared its orbital path of other debris."},{"q":"What is an asteroid belt?","ch":["A region between Mars and Jupiter containing many small rocky bodies","A ring of ice around Saturn","A cluster of comets beyond Neptune","A belt of dust around the Sun"],"ans":0,"exp":"The asteroid belt lies between the orbits of Mars and Jupiter and contains millions of rocky objects."},{"q":"Which planet has the most extensive and visible ring system?","ch":["Mars","Saturn","Mercury","Earth"],"ans":1,"exp":"Saturn's rings, made mostly of ice and rock particles, are the largest and most visible in the solar system."},{"q":"About how long does it take Earth to complete one full orbit around the Sun?","ch":["24 hours","1 month","10 years","1 year"],"ans":3,"exp":"Earth takes about 365.25 days, or one year, to complete a single orbit around the Sun."}]},
{"id":"fps30","cat":"Physical Sciences","title":"States of Matter & Phase Changes","diff":"Easy","qs":[{"q":"What is the process called when a solid changes directly into a gas without becoming a liquid?","ch":["Condensation","Evaporation","Melting","Sublimation"],"ans":3,"exp":"Sublimation is the direct transition from solid to gas, as seen with dry ice."},{"q":"Which state of matter has a definite volume but no definite shape?","ch":["Liquid","Solid","Gas","Plasma"],"ans":0,"exp":"Liquids take the shape of their container but keep a fixed volume."},{"q":"What is the term for a liquid turning into a gas?","ch":["Condensation","Evaporation","Freezing","Deposition"],"ans":1,"exp":"Evaporation occurs when a liquid gains enough energy for particles to escape into the gas phase."},{"q":"What happens to the particles in a substance as it is heated?","ch":["They move slower","They stop moving","They move faster and spread apart","They disappear"],"ans":2,"exp":"Heating adds kinetic energy to particles, causing them to move faster and typically spread further apart."},{"q":"Which term describes a gas turning directly into a solid?","ch":["Deposition","Sublimation","Melting","Boiling"],"ans":0,"exp":"Deposition is the reverse of sublimation, where a gas becomes a solid without passing through the liquid phase."},{"q":"What is the freezing point of water at standard atmospheric pressure, in Celsius?","ch":["100°C","50°C","-32°C","0°C"],"ans":3,"exp":"Water freezes at 0 degrees Celsius under normal atmospheric pressure."},{"q":"Which state of matter has particles that are tightly packed in a fixed arrangement?","ch":["Gas","Plasma","Solid","Liquid"],"ans":2,"exp":"Solids have particles held closely together in a fixed, orderly structure, which gives them a definite shape."},{"q":"During a phase change, such as melting, what happens to temperature while both phases are present?","ch":["It rises steadily","It stays constant","It drops sharply","It fluctuates randomly"],"ans":1,"exp":"During a phase change, added energy goes into breaking intermolecular bonds rather than raising temperature, so the temperature stays constant until the change is complete."}]},
{"id":"fps31","cat":"Physical Sciences","title":"Scientific Notation & Units of Measurement","diff":"Easy","qs":[{"q":"What is 4,500 written in scientific notation?","ch":["4.5 x 10^3","4.5 x 10^2","45 x 10^2","4.5 x 10^-3"],"ans":0,"exp":"Moving the decimal point three places to the left gives 4.5 x 10^3."},{"q":"What is the SI base unit for length?","ch":["Kilogram","Meter","Liter","Second"],"ans":1,"exp":"The meter is the SI base unit used to measure length."},{"q":"What does the prefix \"kilo-\" mean?","ch":["One hundred","One tenth","One thousand","One million"],"ans":2,"exp":"The prefix kilo- means one thousand, as in a kilometer being 1,000 meters."},{"q":"Which of the following is 0.0032 written in scientific notation?","ch":["3.2 x 10^3","32 x 10^-4","3.2 x 10^2","3.2 x 10^-3"],"ans":3,"exp":"Moving the decimal point three places to the right gives 3.2 x 10^-3."},{"q":"What is the SI base unit for mass?","ch":["Pound","Kilogram","Gram","Ounce"],"ans":1,"exp":"The kilogram is the official SI base unit of mass, even though the gram is often used for smaller masses."},{"q":"How many significant figures are in the number 0.00450?","ch":["2","6","3","5"],"ans":2,"exp":"Leading zeros are not significant, so 0.00450 has three significant figures: 4, 5, and the trailing 0."},{"q":"What does the prefix \"milli-\" represent?","ch":["One thousand","One hundred","One millionth","One thousandth"],"ans":3,"exp":"Milli- means one thousandth, as in a millimeter being one thousandth of a meter."},{"q":"Which unit is commonly used to measure temperature in scientific work?","ch":["Celsius","Fahrenheit","Inches","Pounds"],"ans":0,"exp":"Celsius (along with Kelvin) is the standard temperature scale used in scientific measurement worldwide."}]},
{"id":"fps32","cat":"Physical Sciences","title":"Density, Buoyancy & Pressure Basics","diff":"Easy","qs":[{"q":"Density is defined as","ch":["Volume divided by mass","Weight divided by area","Mass divided by volume","Force divided by area"],"ans":2,"exp":"Density is calculated by dividing an object's mass by its volume."},{"q":"An object floats in water if","ch":["Its density equals water's density exactly","Its density is greater than water's density","It is perfectly spherical","Its density is less than water's density"],"ans":3,"exp":"An object floats when it is less dense than the fluid it is placed in, so it displaces enough fluid to support its weight."},{"q":"The buoyant force on a submerged object is described by which principle?","ch":["Archimedes' principle","Newton's third law","Pascal's principle","Bernoulli's principle"],"ans":0,"exp":"Archimedes' principle states that the buoyant force on an object equals the weight of the fluid it displaces."},{"q":"Pressure is defined as","ch":["Mass per unit volume","Force per unit area","Energy per unit time","Weight per unit length"],"ans":1,"exp":"Pressure is the amount of force applied over a given area."},{"q":"Which unit is commonly used to measure pressure?","ch":["Newton","Joule","Watt","Pascal"],"ans":3,"exp":"The Pascal (force per unit area) is the standard SI unit of pressure."},{"q":"As depth increases in a fluid, the pressure","ch":["Increases","Decreases","Stays the same","Becomes zero"],"ans":0,"exp":"Fluid pressure increases with depth because there is more fluid weight pressing down from above."},{"q":"An object with a density of 2 g/cm^3 is placed in water, which has a density of 1 g/cm^3. What will happen?","ch":["It will float completely above the surface","It will sink","It will stay suspended exactly in the middle","It will dissolve"],"ans":1,"exp":"Since the object is denser than water, it will sink rather than float."},{"q":"According to Archimedes' principle, what determines the buoyant force on a submerged object?","ch":["The object's own weight","The object's color","The weight of the fluid displaced by the object","The object's temperature"],"ans":2,"exp":"The buoyant force equals the weight of the fluid that the object pushes out of the way."}]},
{"id":"fps33","cat":"Physical Sciences","title":"Intro to Nuclear Chemistry — Radioactivity Basics","diff":"Medium","qs":[{"q":"An alpha particle is equivalent to","ch":["A single proton","A helium nucleus (2 protons and 2 neutrons)","An electron","A high-energy photon"],"ans":1,"exp":"An alpha particle consists of two protons and two neutrons, identical to the nucleus of a helium atom."},{"q":"Beta decay involves the emission of","ch":["An electron (or positron)","A helium nucleus","A neutron","A proton only"],"ans":0,"exp":"In beta decay, a neutron converts into a proton (or vice versa), releasing a fast-moving electron or positron."},{"q":"Gamma rays are best described as","ch":["Fast-moving electrons","Helium nuclei","Neutrons ejected from the nucleus","High-energy electromagnetic radiation"],"ans":3,"exp":"Gamma rays are a form of high-energy electromagnetic radiation released as a nucleus loses excess energy."},{"q":"Half-life is defined as","ch":["The time for an entire sample to decay","The time for a sample to double in mass","The time for half of a radioactive sample to decay","The energy released during decay"],"ans":2,"exp":"A half-life is the amount of time it takes for half of the atoms in a radioactive sample to decay."},{"q":"A radioactive sample has a half-life of 10 years. If you start with 80 grams, how much remains after 20 years?","ch":["20 g","40 g","10 g","60 g"],"ans":0,"exp":"After one half-life (10 years), 40 g remain; after a second half-life (20 years total), 20 g remain."},{"q":"Which type of radiation is stopped by a single sheet of paper?","ch":["Gamma rays","Alpha particles","Beta particles","X-rays"],"ans":1,"exp":"Alpha particles are large and slow-moving compared to other radiation types, so they are easily blocked by paper or skin."},{"q":"In radioactive decay, an unstable nucleus generally","ch":["Absorbs energy from its surroundings","Splits water molecules","Releases energy and/or particles to become more stable","Gains additional protons spontaneously"],"ans":2,"exp":"Unstable nuclei release energy and particles through decay in order to reach a more stable configuration."},{"q":"Which type of radiation has the greatest penetrating power?","ch":["Alpha particles","Beta particles","Neutrons only","Gamma rays"],"ans":3,"exp":"Gamma rays can pass through many materials, including several centimeters of lead, making them the most penetrating."}]},
{"id":"fps34","cat":"Physical Sciences","title":"Naming Chemical Compounds Basics","diff":"Easy","qs":[{"q":"What is the correct name for NaCl?","ch":["Sodium chlorate","Sodium chlorite","Sodium hypochlorite","Sodium chloride"],"ans":3,"exp":"NaCl is sodium chloride, formed from sodium ions (Na+) and chloride ions (Cl-)."},{"q":"What is the chemical formula for water?","ch":["CO2","H2O2","H2O","O2H"],"ans":2,"exp":"Water is made of two hydrogen atoms bonded to one oxygen atom, giving the formula H2O."},{"q":"In the name \"Iron(III) oxide\", what does the Roman numeral III indicate?","ch":["The number of oxygen atoms","The charge (oxidation state) of the iron ion","The atomic number of iron","The number of electrons in the compound"],"ans":1,"exp":"Roman numerals in compound names show the charge, or oxidation state, of a metal that can form more than one type of ion."},{"q":"What prefix is used for two of an element in a molecular compound name, as in carbon dioxide?","ch":["Di-","Mono-","Tri-","Tetra-"],"ans":0,"exp":"The prefix di- means two, so carbon dioxide has two oxygen atoms."},{"q":"What type of compound generally forms between a metal and a nonmetal?","ch":["Covalent compound","Metallic alloy","Ionic compound","Organic compound"],"ans":2,"exp":"Metals tend to lose electrons and nonmetals tend to gain them, forming oppositely charged ions that create an ionic compound."},{"q":"What is the correct chemical formula for magnesium oxide, given that magnesium forms Mg2+ and oxygen forms O2-?","ch":["Mg2O","MgO2","Mg2O2","MgO"],"ans":3,"exp":"Since Mg2+ and O2- have equal and opposite charges, they combine in a 1:1 ratio to form MgO."},{"q":"What is the name of the polyatomic ion SO4^2-?","ch":["Sulfate","Sulfite","Sulfide","Sulfur oxide"],"ans":0,"exp":"SO4^2- is the sulfate ion, one of the common polyatomic ions containing sulfur and oxygen."},{"q":"When naming an acid derived from a polyatomic ion ending in \"-ate\" (such as sulfate), what suffix is typically used for the acid's name?","ch":["-ous acid","-ic acid","-ide acid","-ite acid"],"ans":1,"exp":"Acids formed from \"-ate\" ions typically end in \"-ic acid\", so sulfate becomes sulfuric acid."}]},
{"id":"fps35","cat":"Physical Sciences","title":"Basic Physics — Momentum & Collisions","diff":"Medium","qs":[{"q":"Momentum is calculated as","ch":["Mass multiplied by velocity","Mass divided by velocity","Force multiplied by time","Mass multiplied by acceleration"],"ans":0,"exp":"Momentum equals an object's mass multiplied by its velocity."},{"q":"A 2 kg object moving at 3 m/s has a momentum of","ch":["1.5 kg·m/s","5 kg·m/s","2 kg·m/s","6 kg·m/s"],"ans":3,"exp":"Momentum = mass x velocity = 2 kg x 3 m/s = 6 kg·m/s."},{"q":"According to the law of conservation of momentum, in a closed system with no external forces, the total momentum","ch":["Always increases","Always decreases","Stays constant before and after a collision","Becomes zero"],"ans":2,"exp":"Total momentum in a closed system is conserved, meaning it remains the same before and after a collision."},{"q":"In a perfectly inelastic collision, the two colliding objects","ch":["Bounce apart with no energy loss","Stick together and move as one object","Pass through each other","Both come to a complete stop"],"ans":1,"exp":"In a perfectly inelastic collision, the objects stick together after impact and move with a shared final velocity."},{"q":"In an elastic collision, which quantity is conserved in addition to momentum?","ch":["Mass alone","Volume","Temperature","Kinetic energy"],"ans":3,"exp":"Elastic collisions conserve both total momentum and total kinetic energy."},{"q":"A 1 kg ball moving at 4 m/s collides and sticks with a stationary 1 kg ball. What is their combined velocity right after the collision?","ch":["2 m/s","4 m/s","1 m/s","8 m/s"],"ans":0,"exp":"Using conservation of momentum: (1 kg x 4 m/s) = (2 kg) x v, so v = 2 m/s."},{"q":"What is the SI unit of momentum?","ch":["Newton","Kilogram-meter per second (kg·m/s)","Joule","Watt"],"ans":1,"exp":"Since momentum is mass times velocity, its SI unit is kilogram-meters per second."},{"q":"Which of Newton's laws is most directly related to how a force changes an object's momentum over time?","ch":["Newton's first law","Newton's law of gravitation","Newton's second law","Newton's zeroth law"],"ans":2,"exp":"Newton's second law relates force to the rate of change of momentum, often simplified as F = ma."}]},
{"id":"fps36","cat":"Physical Sciences","title":"Wave Properties — Frequency, Wavelength & Amplitude","diff":"Easy","qs":[{"q":"Wavelength is best described as","ch":["The height of a wave","The speed at which a wave travels","The distance between two consecutive crests (or troughs)","The number of waves passing a point per second"],"ans":2,"exp":"Wavelength is the distance from one crest (or trough) to the next crest (or trough)."},{"q":"Frequency is measured in which unit?","ch":["Meters","Hertz","Newtons","Seconds"],"ans":1,"exp":"Frequency, the number of wave cycles per second, is measured in Hertz (Hz)."},{"q":"What is the relationship between wave speed, frequency, and wavelength?","ch":["Speed = frequency x wavelength","Speed = frequency / wavelength","Speed = wavelength / frequency","Speed = frequency + wavelength"],"ans":0,"exp":"Wave speed equals frequency multiplied by wavelength."},{"q":"The amplitude of a wave is most closely related to its","ch":["Speed of travel","Direction of travel","Frequency","Energy (intensity) carried by the wave"],"ans":3,"exp":"A wave's amplitude, or maximum displacement from equilibrium, corresponds to the amount of energy it carries."},{"q":"If frequency increases while wave speed stays constant, the wavelength must","ch":["Increase","Decrease","Stay the same","Become zero"],"ans":1,"exp":"Since speed = frequency x wavelength, if speed is constant and frequency rises, wavelength must fall."},{"q":"A wave with a high frequency has","ch":["Fewer crests passing a point per second","A longer wavelength always","More waves passing a given point per second","A smaller amplitude always"],"ans":2,"exp":"Higher frequency means more complete wave cycles pass a fixed point each second."},{"q":"What is the period of a wave?","ch":["The distance between two crests","The height of a crest above equilibrium","The speed of the wave","The time it takes for one complete wave cycle"],"ans":3,"exp":"Period is the time required to complete one full wave cycle, and it is the inverse of frequency."},{"q":"A wave with a greater amplitude but the same frequency carries","ch":["More energy","Less energy","The same energy","No energy"],"ans":0,"exp":"Larger amplitude means the wave's particles move through a greater displacement, which requires and carries more energy."}]},
{"id":"fps37","cat":"Physical Sciences","title":"Basic Environmental Chemistry","diff":"Easy","qs":[{"q":"What is the greenhouse effect?","ch":["The cooling of Earth's surface by ocean currents","The trapping of heat near Earth's surface by atmospheric gases","The depletion of the ozone layer","The process of photosynthesis in plants"],"ans":1,"exp":"The greenhouse effect occurs when gases in the atmosphere trap heat, keeping Earth's surface warmer than it would otherwise be."},{"q":"Which gas released by burning fossil fuels is most associated with the greenhouse effect and climate change?","ch":["Nitrogen","Oxygen","Argon","Carbon dioxide"],"ans":3,"exp":"Carbon dioxide is a major greenhouse gas produced when fossil fuels like coal, oil, and gas are burned."},{"q":"Acid rain is primarily caused by emissions of","ch":["Sulfur dioxide and nitrogen oxides","Carbon dioxide and oxygen","Methane and helium","Water vapor and nitrogen"],"ans":0,"exp":"Sulfur dioxide and nitrogen oxides react with water vapor in the atmosphere to form acidic compounds that fall as acid rain."},{"q":"What does pH measure?","ch":["The temperature of a solution","The color of a solution","The acidity or basicity of a solution","The density of a solution"],"ans":2,"exp":"The pH scale measures how acidic or basic (alkaline) a solution is."},{"q":"A solution with a pH of 3 is considered","ch":["Neutral","Basic (alkaline)","Extremely basic","Acidic"],"ans":3,"exp":"A pH below 7 indicates an acidic solution, and 3 is well below the neutral value of 7."},{"q":"Which layer of the atmosphere absorbs most harmful ultraviolet radiation from the Sun?","ch":["The greenhouse layer","The ozone layer","The troposphere","The ionosphere only"],"ans":1,"exp":"The ozone layer, located in the stratosphere, absorbs the majority of the Sun's harmful UV radiation."},{"q":"What is a common cause of water pollution from agriculture?","ch":["Volcanic eruptions","Solar radiation","Fertilizer and pesticide runoff","Wind erosion of rock"],"ans":2,"exp":"Excess fertilizers and pesticides can wash off farmland into rivers and lakes, polluting the water."},{"q":"Recycling materials like paper, glass, and metal primarily helps to","ch":["Conserve natural resources and reduce waste","Increase the ozone layer's thickness","Directly lower global temperatures overnight","Eliminate the need for water treatment"],"ans":0,"exp":"Recycling reduces the need to extract new raw materials and cuts down on the amount of waste sent to landfills."}]},
{"id":"fps38","cat":"Physical Sciences","title":"Intro to Electromagnetism","diff":"Easy","qs":[{"q":"Like electric charges (for example, two positive charges) will","ch":["Repel each other","Attract each other","Have no effect on each other","Combine into a neutral charge"],"ans":0,"exp":"Like charges repel one another, while opposite charges attract."},{"q":"What creates a magnetic field around a wire?","ch":["The wire's color","The wire's temperature","An electric current flowing through the wire","The wire's length alone"],"ans":2,"exp":"A moving electric current produces a magnetic field around the wire carrying it."},{"q":"Which of these is an example of an electrical insulator?","ch":["Copper","Aluminum","Silver","Rubber"],"ans":3,"exp":"Rubber does not allow electric current to flow easily through it, making it a good insulator, unlike the metals listed."},{"q":"Ohm's Law relates voltage, current, and","ch":["Frequency","Resistance","Wavelength","Momentum"],"ans":1,"exp":"Ohm's Law states that voltage equals current multiplied by resistance (V = IR)."},{"q":"Using Ohm's Law (V = IR), if the voltage is 12 volts and the resistance is 4 ohms, what is the current?","ch":["48 amps","0.33 amps","3 amps","16 amps"],"ans":2,"exp":"Rearranging V = IR gives I = V / R = 12 / 4 = 3 amps."},{"q":"A material that allows electric current to flow through it easily is called a","ch":["Conductor","Insulator","Semiconductor exclusively","Resistor exclusively"],"ans":0,"exp":"Conductors, such as most metals, allow electric charge to move through them easily."},{"q":"What is the unit of electric current?","ch":["Volt","Ampere","Ohm","Watt"],"ans":1,"exp":"Electric current is measured in amperes, often shortened to amps."},{"q":"An electromagnet is created by","ch":["Heating a piece of iron","Rubbing two magnets together","Freezing a metal rod","Wrapping a current-carrying wire around an iron core"],"ans":3,"exp":"Wrapping a wire that carries electric current around an iron core produces a temporary, controllable magnet called an electromagnet."}]},
{"id":"fps39","cat":"Physical Sciences","title":"Physics Vocabulary Review","diff":"Easy","qs":[{"q":"What is velocity?","ch":["The rate of change of position without direction","The total distance traveled","The force acting on an object","Speed in a specific direction"],"ans":3,"exp":"Velocity is a vector quantity describing both how fast an object moves and in what direction."},{"q":"What is acceleration?","ch":["The total distance an object travels","The rate of change of velocity over time","The mass of an object","The force of gravity only"],"ans":1,"exp":"Acceleration measures how quickly an object's velocity changes over time."},{"q":"What is the definition of force?","ch":["The energy stored in an object","The rate at which work is done","A push or pull that can change an object's motion","The resistance of a material to bending"],"ans":2,"exp":"A force is any push or pull that can cause an object to accelerate, stop, or change direction."},{"q":"What is kinetic energy?","ch":["The energy an object has due to its motion","The energy an object has due to its position","The total energy in a closed system","The energy released during a chemical reaction"],"ans":0,"exp":"Kinetic energy is the energy an object possesses because it is moving."},{"q":"What is potential energy?","ch":["Energy of motion","Energy stored due to an object's position or condition","The energy lost as heat","The energy of sound waves"],"ans":1,"exp":"Potential energy is stored energy that depends on an object's position, such as height above the ground."},{"q":"What does \"work\" mean in physics?","ch":["Any activity that requires effort","The rate of energy use","The total mass moved","Force applied over a distance in the direction of motion"],"ans":3,"exp":"In physics, work is done when a force causes an object to move a certain distance in the direction of that force."},{"q":"What is friction?","ch":["A force that opposes motion between two surfaces in contact","A force that always speeds up motion","The force of gravity between planets","The energy released by moving objects"],"ans":0,"exp":"Friction is a force that resists the relative motion of two surfaces that are touching."},{"q":"What is inertia?","ch":["The force that pulls objects toward Earth","The energy an object has due to its speed","An object's tendency to resist changes in its state of motion","The friction between two surfaces"],"ans":2,"exp":"Inertia is the natural tendency of an object to keep doing what it is already doing, whether at rest or in motion, unless acted on by a force."}]},
{"id":"fps40","cat":"Physical Sciences","title":"Chemistry Vocabulary Review","diff":"Easy","qs":[{"q":"What is an atom?","ch":["A group of two or more elements chemically combined","A negatively charged particle","The smallest unit of an element that retains the properties of that element","A mixture of two substances"],"ans":2,"exp":"An atom is the smallest particle of an element that still has the chemical properties of that element."},{"q":"What is a molecule?","ch":["Two or more atoms bonded together","A single proton","An empty region of space","A type of subatomic particle"],"ans":0,"exp":"A molecule forms when two or more atoms bond together, such as two hydrogen atoms and one oxygen atom forming water."},{"q":"What is an element?","ch":["A mixture of two or more compounds","A pure substance made of only one type of atom","A liquid solution","A type of chemical reaction"],"ans":1,"exp":"An element is a pure substance that cannot be broken down into simpler substances and consists of only one type of atom."},{"q":"What is a compound?","ch":["A single atom","A mixture that can be separated by physical means","A pure element","A substance made of two or more elements chemically combined in fixed proportions"],"ans":3,"exp":"A compound forms when two or more different elements bond together chemically in a fixed, definite ratio."},{"q":"What is a solution?","ch":["A homogeneous mixture of two or more substances","A chemical reaction that releases gas","A pure element in liquid form","A solid crystal structure"],"ans":0,"exp":"A solution is a uniform (homogeneous) mixture where one substance is dissolved evenly throughout another."},{"q":"What does the term \"catalyst\" mean?","ch":["A substance that slows down a reaction","A type of chemical bond","A substance that speeds up a reaction without being consumed by it","The energy released in a reaction"],"ans":2,"exp":"A catalyst increases the rate of a chemical reaction without being permanently used up in the process."},{"q":"What is a chemical reaction?","ch":["The physical change of state of a substance","The mixing of two liquids without any change","The separation of a mixture into its parts","A process in which substances are transformed into different substances with new properties"],"ans":3,"exp":"A chemical reaction occurs when the atoms in starting substances rearrange to form new substances with different properties."},{"q":"What is a solute in a solution?","ch":["The substance doing the dissolving","The substance being dissolved in the solvent","The container holding the mixture","The energy released during dissolving"],"ans":1,"exp":"The solute is the substance that gets dissolved, while the solvent is the substance that does the dissolving."}]},
{"id":"fbs01","cat":"Behavioral & Social Sciences","title":"Introduction to Psychology","diff":"Easy","qs":[{"q":"What is psychology best defined as?","ch":["The scientific study of behavior and mental processes","The study of brain anatomy only","The philosophical study of the soul","The study of mental illness only"],"ans":0,"exp":"Psychology is defined as the scientific study of behavior and mental processes, covering far more than just mental illness or brain structure."},{"q":"Which early psychologist opened the first formal psychology laboratory in Germany?","ch":["Sigmund Freud","Wilhelm Wundt","B.F. Skinner","Ivan Pavlov"],"ans":1,"exp":"Wilhelm Wundt established the first psychology laboratory in Leipzig, Germany, in 1879, making him one of the founders of modern psychology."},{"q":"Which perspective in psychology emphasizes unconscious thoughts and early childhood experiences?","ch":["Behaviorism","Cognitive psychology","Psychoanalysis","Humanism"],"ans":2,"exp":"Psychoanalysis, developed by Sigmund Freud, focuses on how unconscious thoughts and early childhood experiences shape behavior."},{"q":"Which branch of psychology focuses on mental processes such as thinking, memory, and problem-solving?","ch":["Behaviorism","Psychoanalysis","Social psychology","Cognitive psychology"],"ans":3,"exp":"Cognitive psychology studies internal mental processes like thinking, memory, and problem-solving."},{"q":"Which psychologist is closely associated with humanistic psychology and the idea of self-actualization?","ch":["Abraham Maslow","John Watson","Ivan Pavlov","Sigmund Freud"],"ans":0,"exp":"Abraham Maslow developed humanistic psychology and the concept of self-actualization, the achievement of one's full potential."},{"q":"In a psychology experiment, what is a hypothesis?","ch":["A proven fact","A testable prediction about the relationship between variables","A random guess with no basis","The final conclusion of a study"],"ans":1,"exp":"A hypothesis is a testable, specific prediction about how variables are expected to relate to one another."},{"q":"Which subfield of psychology studies how people's thoughts, feelings, and behaviors are influenced by others?","ch":["Clinical psychology","Developmental psychology","Social psychology","Cognitive psychology"],"ans":2,"exp":"Social psychology examines how the presence and behavior of others influence an individual's thoughts, feelings, and actions."},{"q":"What does the biopsychosocial model suggest about human behavior?","ch":["Behavior is determined only by genetics","Behavior is determined only by the environment","Behavior is determined only by past experiences","Behavior results from the combination of biological, psychological, and social factors"],"ans":3,"exp":"The biopsychosocial model views behavior as the product of interacting biological, psychological, and social influences, not any single factor alone."}]},
{"id":"fbs02","cat":"Behavioral & Social Sciences","title":"Classical & Operant Conditioning Basics","diff":"Medium","qs":[{"q":"What is classical conditioning?","ch":["Learning through the association of two stimuli","Learning through rewards and punishments only","Learning by observing others","Learning through insight and reasoning"],"ans":0,"exp":"Classical conditioning is a learning process where a neutral stimulus becomes associated with a stimulus that already triggers a response."},{"q":"In Pavlov's famous experiment, what did the dogs learn to associate with food?","ch":["A light","The sound of a bell","A smell","A touch"],"ans":1,"exp":"Ivan Pavlov paired the sound of a bell with food until the dogs salivated at the bell alone, demonstrating classical conditioning."},{"q":"In operant conditioning, what is reinforcement?","ch":["Removing a stimulus to decrease behavior","Pairing two neutral stimuli together","A consequence that increases the likelihood of a behavior","A consequence that always involves punishment"],"ans":2,"exp":"Reinforcement is any consequence that strengthens or increases the likelihood of the behavior it follows."},{"q":"What is negative reinforcement?","ch":["Adding a pleasant stimulus to decrease behavior","Adding an unpleasant stimulus to increase behavior","Removing a pleasant stimulus to decrease behavior","Removing an unpleasant stimulus to increase behavior"],"ans":3,"exp":"Negative reinforcement strengthens a behavior by removing or avoiding an unpleasant stimulus, such as fastening a seatbelt to stop an annoying beep."},{"q":"Who is best known for developing the theory of operant conditioning using rewards and punishments?","ch":["B.F. Skinner","Ivan Pavlov","Sigmund Freud","Jean Piaget"],"ans":0,"exp":"B.F. Skinner developed operant conditioning, showing how consequences like rewards and punishments shape voluntary behavior."},{"q":"What is punishment in operant conditioning?","ch":["A consequence that increases a behavior","A consequence that decreases the likelihood of a behavior","A neutral stimulus with no effect","The same thing as negative reinforcement"],"ans":1,"exp":"Punishment is a consequence that decreases the likelihood that a behavior will occur again, the opposite of reinforcement."},{"q":"What term describes the gradual disappearance of a learned response when it is no longer reinforced?","ch":["Generalization","Discrimination","Extinction","Shaping"],"ans":2,"exp":"Extinction occurs when a conditioned response weakens and eventually disappears because it is no longer followed by reinforcement."},{"q":"What is a conditioned stimulus?","ch":["A stimulus that naturally triggers a response without learning","A response that occurs naturally before conditioning","A reward given after a correct behavior","A previously neutral stimulus that triggers a response after being paired with an unconditioned stimulus"],"ans":3,"exp":"A conditioned stimulus starts out neutral but comes to trigger a learned response after repeated pairing with an unconditioned stimulus."}]},
{"id":"fbs03","cat":"Behavioral & Social Sciences","title":"Human Development Basics","diff":"Easy","qs":[{"q":"What is developmental psychology the study of?","ch":["How people grow and change physically, mentally, and socially across the lifespan","Only how children learn language","Only the aging process in adults","Only brain injuries"],"ans":0,"exp":"Developmental psychology examines physical, cognitive, and social changes that occur throughout the entire human lifespan."},{"q":"According to Jean Piaget, in which stage do infants learn that objects continue to exist even when they cannot be seen?","ch":["Formal operational stage","Sensorimotor stage","Concrete operational stage","Preoperational stage"],"ans":1,"exp":"In Piaget's sensorimotor stage, infants develop object permanence, the understanding that objects still exist even when out of sight."},{"q":"What term describes a strong emotional bond between an infant and a caregiver?","ch":["Temperament","Object permanence","Attachment","Socialization"],"ans":2,"exp":"Attachment refers to the close emotional bond that typically forms between an infant and a primary caregiver."},{"q":"Which psychologist proposed a theory of psychosocial development spanning the entire human lifespan?","ch":["Jean Piaget","Lawrence Kohlberg","Sigmund Freud","Erik Erikson"],"ans":3,"exp":"Erik Erikson proposed eight stages of psychosocial development that extend from infancy through late adulthood."},{"q":"During adolescence, what is a primary developmental task according to Erikson?","ch":["Forming a stable sense of identity","Learning to walk","Developing object permanence","Learning basic language skills"],"ans":0,"exp":"Erikson identified identity formation, figuring out who you are and what you value, as the central task of adolescence."},{"q":"What is the term for the biological changes that occur during puberty?","ch":["Cognitive development","Physical maturation","Moral development","Social referencing"],"ans":1,"exp":"Physical maturation refers to the biological growth and bodily changes that occur during puberty and beyond."},{"q":"Which parenting style is characterized by high warmth and high expectations with clear communication?","ch":["Permissive","Authoritarian","Authoritative","Uninvolved"],"ans":2,"exp":"The authoritative style balances warmth and support with reasonable, clearly communicated expectations for behavior."},{"q":"What describes the ongoing debate about whether development is a gradual, continuous process or occurs in distinct stages?","ch":["Attachment theory","The nurture debate","The critical period hypothesis","Continuity versus stages in development"],"ans":3,"exp":"This debate asks whether development unfolds smoothly and gradually or happens in a series of distinct, qualitatively different stages."}]},
{"id":"fbs04","cat":"Behavioral & Social Sciences","title":"Basic Memory & Cognition","diff":"Medium","qs":[{"q":"What are the three main stages of memory processing?","ch":["Encoding, storage, and retrieval","Sensing, thinking, and forgetting","Input, output, and feedback","Attention, reaction, and response"],"ans":0,"exp":"Memory processing involves encoding information, storing it, and later retrieving it when needed."},{"q":"Which type of memory holds information for only a few seconds unless it is rehearsed?","ch":["Long-term memory","Short-term memory","Procedural memory","Semantic memory"],"ans":1,"exp":"Short-term memory holds a small amount of information for a brief period unless it is actively rehearsed or encoded further."},{"q":"What is the term for memory of how to perform tasks and skills, like riding a bike?","ch":["Episodic memory","Semantic memory","Procedural memory","Working memory"],"ans":2,"exp":"Procedural memory stores knowledge of how to perform skills and tasks, often without conscious effort to recall it."},{"q":"What is encoding in the context of memory?","ch":["Losing information over time","Retrieving information from storage","Combining several memories into one","The process of converting information into a form that can be stored"],"ans":3,"exp":"Encoding is the initial step of memory formation, converting sensory information into a format the brain can store."},{"q":"What is a common strategy for improving memory by organizing information into meaningful groups?","ch":["Chunking","Extinction","Repression","Habituation"],"ans":0,"exp":"Chunking groups individual pieces of information into larger, more meaningful units, making them easier to remember."},{"q":"What is the term for the inability to recall information that was once stored in memory?","ch":["Encoding","Forgetting","Rehearsal","Retrieval"],"ans":1,"exp":"Forgetting refers to the loss or inability to access information that was previously stored in memory."},{"q":"Which type of memory stores general knowledge and facts about the world, such as knowing that Paris is the capital of France?","ch":["Episodic memory","Procedural memory","Semantic memory","Sensory memory"],"ans":2,"exp":"Semantic memory holds general factual knowledge about the world, independent of personal experience."},{"q":"What is cognition?","ch":["The physical process of growth","The formation of emotional attachments","The regulation of hormones in the body","The mental process of thinking, knowing, and understanding"],"ans":3,"exp":"Cognition refers to mental processes such as thinking, knowing, remembering, and understanding."}]},
{"id":"fbs05","cat":"Behavioral & Social Sciences","title":"Emotions — Basic Psychology","diff":"Easy","qs":[{"q":"What are emotions generally considered to include?","ch":["A physiological response, a subjective feeling, and an expressive behavior","Only physical sensations","Only conscious thoughts","Only facial expressions"],"ans":0,"exp":"Emotions typically involve a bodily response, an inner subjective feeling, and an outward expressive behavior together."},{"q":"Which basic emotion is typically identified across nearly all human cultures, alongside anger, sadness, and disgust?","ch":["Nostalgia","Fear","Pride","Guilt"],"ans":1,"exp":"Fear is widely recognized as one of the basic, universal emotions expressed and understood across cultures."},{"q":"According to the James-Lange theory of emotion, what happens first?","ch":["We consciously interpret a situation as emotional","We feel the emotion, then our body reacts","Our body reacts to a stimulus, and then we experience the emotion based on that reaction","Emotion and physical reaction happen with no connection"],"ans":2,"exp":"The James-Lange theory proposes that physiological arousal comes first, and the emotion we feel is our interpretation of that bodily reaction."},{"q":"What is the term for a person's outward display of emotion, such as smiling or frowning?","ch":["Mood","Temperament","Empathy","Facial expression"],"ans":3,"exp":"Facial expression refers to the visible, outward signs of emotion shown through the face, like smiling when happy."},{"q":"What is empathy?","ch":["The ability to understand and share the feelings of another person","The tendency to avoid other people's emotions","A physical reflex to pain","A type of long-term memory"],"ans":0,"exp":"Empathy is the capacity to understand and share in another person's feelings and perspective."},{"q":"Which part of the body is often associated with processing fear and other emotional reactions?","ch":["The cerebellum","The amygdala","The spinal cord","The pituitary gland"],"ans":1,"exp":"The amygdala, a small brain structure, plays a key role in processing fear and other emotional responses."},{"q":"What is the difference between a mood and an emotion?","ch":["Moods are always positive and emotions are always negative","There is no difference between them","Emotions are typically shorter and more intense, while moods last longer and are less intense","Moods only occur during sleep"],"ans":2,"exp":"Emotions tend to be brief and intense reactions to specific events, while moods are longer-lasting and less intense overall states."},{"q":"Why are emotions considered adaptive from an evolutionary perspective?","ch":["They serve no real purpose","They only affect artistic expression","They are unrelated to survival","They can help humans respond quickly to threats and opportunities in their environment"],"ans":3,"exp":"Emotions like fear can trigger quick, useful responses to threats, which has helped humans survive throughout evolution."}]},
{"id":"fbs06","cat":"Behavioral & Social Sciences","title":"Introduction to Sociology","diff":"Easy","qs":[{"q":"What is sociology the study of?","ch":["Human society, social relationships, and social behavior","Only individual mental processes","Only economic systems","Only political systems"],"ans":0,"exp":"Sociology is the scientific study of society, social relationships, and how people behave in groups."},{"q":"What term refers to a society's shared beliefs, values, customs, and behaviors?","ch":["Institution","Culture","Status","Norm"],"ans":1,"exp":"Culture encompasses the shared beliefs, values, customs, and behaviors that characterize a group or society."},{"q":"What is a social institution?","ch":["A single person's personal habits","A random group of strangers","An established pattern of behavior organized around a particular purpose, like family or education","A type of mental illness"],"ans":2,"exp":"Social institutions, such as family, education, and government, are organized systems that fulfill important needs within society."},{"q":"Which sociological perspective views society as a system of interconnected parts that work together to maintain stability?","ch":["Conflict theory","Symbolic interactionism","Feminist theory","Functionalism"],"ans":3,"exp":"Functionalism views society as made up of interdependent parts that each contribute to overall social stability."},{"q":"Which sociological perspective focuses on inequality and competition between social groups for resources and power?","ch":["Conflict theory","Functionalism","Structuralism","Behaviorism"],"ans":0,"exp":"Conflict theory examines how competition and inequality between groups shape society and drive social change."},{"q":"What is a norm in sociology?","ch":["A person's individual personality trait","A shared rule or expectation for behavior in a society","A biological instinct","A type of government"],"ans":1,"exp":"A norm is a shared expectation or rule that guides acceptable behavior within a society or group."},{"q":"What term describes the process by which people learn the values, norms, and behaviors of their society?","ch":["Stratification","Assimilation","Socialization","Deviance"],"ans":2,"exp":"Socialization is the lifelong process through which individuals learn and internalize the values and norms of their society."},{"q":"Who is often credited as one of the founders of sociology as an academic discipline?","ch":["Sigmund Freud","B.F. Skinner","Jean Piaget","Emile Durkheim"],"ans":3,"exp":"Emile Durkheim is widely regarded as one of the founding figures of sociology, studying how societies maintain order."}]},
{"id":"fbs07","cat":"Behavioral & Social Sciences","title":"Social Groups & Roles","diff":"Easy","qs":[{"q":"What is a social group?","ch":["Two or more people who interact and share a sense of identity","Any random collection of people in the same location","A single individual","A type of building"],"ans":0,"exp":"A social group consists of two or more people who interact regularly and share a common sense of identity or belonging."},{"q":"What is the difference between a primary group and a secondary group?","ch":["Primary groups are always larger than secondary groups","Primary groups involve close, personal relationships, while secondary groups are more impersonal and goal-oriented","Secondary groups always meet in person","There is no meaningful difference"],"ans":1,"exp":"Primary groups, like family, involve close and personal bonds, while secondary groups, like coworkers, are more task-focused and impersonal."},{"q":"What is a social role?","ch":["A person's genetic makeup","A permanent personality trait","The set of expected behaviors associated with a particular social position","A type of building structure"],"ans":2,"exp":"A social role is the collection of behaviors expected of someone who holds a particular position, such as student or teacher."},{"q":"What term describes a person's position or rank within a society or group?","ch":["Norm","Culture","Deviance","Status"],"ans":3,"exp":"Status refers to a person's recognized social position or rank within a group or society."},{"q":"What is role conflict?","ch":["A situation where the demands of two or more roles are incompatible","When a person has no assigned roles","When a group has no leader","When two groups compete for resources"],"ans":0,"exp":"Role conflict occurs when the expectations of two or more of a person's roles clash, such as work duties conflicting with family duties."},{"q":"What is an in-group?","ch":["A group a person does not belong to and may feel opposed to","A group a person belongs to and feels loyalty toward","A random gathering of strangers","A type of government institution"],"ans":1,"exp":"An in-group is a group that a person identifies with and feels a sense of belonging and loyalty toward."},{"q":"What is groupthink?","ch":["The tendency of individuals to think independently in a group","A formal decision-making process used by governments","The tendency for a group to make poor decisions because members avoid expressing disagreement","A type of memory disorder"],"ans":2,"exp":"Groupthink happens when a desire for harmony leads group members to suppress disagreement, often resulting in poor decisions."},{"q":"What is a reference group?","ch":["A random list of names","A group with no influence on a person's behavior","A type of secondary memory","A group that people use as a standard for evaluating themselves and their behavior"],"ans":3,"exp":"A reference group provides a standard that individuals use to evaluate their own attitudes, values, and behaviors."}]},
{"id":"fbs08","cat":"Behavioral & Social Sciences","title":"Culture & Society Basics","diff":"Easy","qs":[{"q":"What are values in a culture?","ch":["Shared beliefs about what is good, desirable, or important","Laws written by a government","Random personal opinions with no shared meaning","Physical objects used in daily life"],"ans":0,"exp":"Values are widely shared beliefs within a culture about what is good, desirable, or important."},{"q":"What is material culture?","ch":["A society's shared beliefs and values","The physical objects, tools, and artifacts that a society creates and uses","A type of government system","A person's individual personality"],"ans":1,"exp":"Material culture refers to the tangible objects, tools, and artifacts created and used by members of a society."},{"q":"What is ethnocentrism?","ch":["The belief that all cultures are equally valid with no bias","A neutral, scientific way to study cultures","The tendency to judge other cultures by the standards of one's own culture","A term for cultural exchange programs"],"ans":2,"exp":"Ethnocentrism is the tendency to evaluate other cultures using the standards and values of one's own culture."},{"q":"What is cultural relativism?","ch":["The idea that one's own culture is superior to all others","The refusal to study other cultures","A type of government policy","The practice of understanding a culture on its own terms rather than judging it by another culture's standards"],"ans":3,"exp":"Cultural relativism involves understanding and evaluating a culture based on its own context rather than by outside standards."},{"q":"What is a subculture?","ch":["A smaller group within a larger culture that shares distinct values or customs","A culture that no longer exists","A synonym for an entire nation","A type of language only"],"ans":0,"exp":"A subculture is a smaller group within a larger culture that maintains its own distinct values, customs, or practices."},{"q":"What is globalization?","ch":["The isolation of countries from one another","The increasing interconnection of societies through trade, communication, and culture","A decline in international trade","A term used only in economics with no cultural impact"],"ans":1,"exp":"Globalization describes the growing interconnectedness of societies worldwide through trade, technology, and cultural exchange."},{"q":"What is a cultural norm?","ch":["A rare exception to typical behavior","A law enforced only by police","An accepted standard of behavior within a culture","A random individual habit"],"ans":2,"exp":"A cultural norm is a widely accepted standard or expectation for behavior shared by members of a culture."},{"q":"What term describes the process of adapting to a new culture while retaining aspects of one's original culture?","ch":["Ethnocentrism","Stratification","Deviance","Acculturation"],"ans":3,"exp":"Acculturation describes the process of adapting to a new culture while still keeping elements of one's original cultural identity."}]},
{"id":"fbs09","cat":"Behavioral & Social Sciences","title":"Basic Research Methods — Surveys & Experiments","diff":"Medium","qs":[{"q":"What is the main purpose of a survey in social science research?","ch":["To collect self-reported information from a sample of people","To manipulate variables in a controlled setting","To observe animals in their natural habitat","To analyze historical documents only"],"ans":0,"exp":"Surveys gather self-reported data, such as opinions or behaviors, directly from a sample of people using questions."},{"q":"In an experiment, what is the independent variable?","ch":["The variable that is measured as an outcome","The variable that the researcher deliberately manipulates","A variable that is always kept constant","A variable that has no effect on the study"],"ans":1,"exp":"The independent variable is the factor that a researcher deliberately changes to observe its effect on another variable."},{"q":"What is the dependent variable in an experiment?","ch":["The variable the researcher changes on purpose","A variable unrelated to the study","The variable that is measured to see if it was affected by the independent variable","The group that receives no treatment"],"ans":2,"exp":"The dependent variable is the outcome that researchers measure to see whether it was influenced by the independent variable."},{"q":"What is a control group used for in an experiment?","ch":["To receive an extra-strong version of the treatment","To design the survey questions","To collect qualitative interview data","To provide a baseline for comparison by not receiving the experimental treatment"],"ans":3,"exp":"A control group does not receive the experimental treatment, giving researchers a baseline to compare against the treatment group."},{"q":"What is random assignment in an experiment?","ch":["Assigning participants to groups by chance so each has an equal likelihood of being in any group","Letting participants choose their own group","Assigning participants based on their personal characteristics","A method used only in surveys, not experiments"],"ans":0,"exp":"Random assignment places participants into groups purely by chance, helping ensure the groups are comparable before the treatment begins."},{"q":"What is a major advantage of using a large, representative sample in a survey?","ch":["It guarantees the results will be perfectly accurate","It helps the results better reflect the larger population being studied","It removes the need for informed consent","It eliminates all forms of bias automatically"],"ans":1,"exp":"A large, representative sample helps ensure that survey findings can be more confidently generalized to the broader population."},{"q":"What is an observational study?","ch":["A study where the researcher manipulates variables directly","A study that only uses historical records","A study where researchers watch and record behavior without manipulating variables","A type of survey with no questions"],"ans":2,"exp":"In an observational study, researchers watch and record behavior as it naturally occurs, without manipulating any variables."},{"q":"Why do researchers use informed consent in studies involving human participants?","ch":["To keep participants unaware of the study's purpose","To avoid collecting any data","To require participants to complete the study regardless of comfort","To ensure participants understand the study and voluntarily agree to take part"],"ans":3,"exp":"Informed consent ensures participants understand what a study involves and agree to take part voluntarily, which is a key ethical safeguard."}]},
{"id":"fbs10","cat":"Behavioral & Social Sciences","title":"Nature vs Nurture Basics","diff":"Easy","qs":[{"q":"What does the \"nature\" side of the nature versus nurture debate emphasize?","ch":["The influence of genetics and biology on development","The influence of upbringing and environment","The influence of random chance only","The influence of formal education only"],"ans":0,"exp":"The \"nature\" side emphasizes how inherited genetics and biological factors shape development and behavior."},{"q":"What does the \"nurture\" side of the debate emphasize?","ch":["Inherited genetic traits","The influence of environment, upbringing, and experiences on development","Physical appearance only","Instincts present at birth"],"ans":1,"exp":"The \"nurture\" side emphasizes how environment, upbringing, and life experiences shape a person's development."},{"q":"What do twin studies help researchers understand?","ch":["How to treat mental illness","How memory works","The relative contributions of genetics versus environment to traits and behaviors","How to design surveys"],"ans":2,"exp":"Twin studies compare identical and fraternal twins to help researchers estimate the relative roles of genetics and environment in traits."},{"q":"What is the current scientific consensus on the nature versus nurture debate?","ch":["Nature alone determines all behavior","Nurture alone determines all behavior","The debate has been fully resolved in favor of nature","Most traits and behaviors result from an interaction between genetic and environmental factors"],"ans":3,"exp":"Most psychologists today agree that traits and behaviors emerge from a continuous interaction between genes and environment, not one alone."},{"q":"What is temperament?","ch":["A person's innate, biologically based pattern of emotional and behavioral responses","A skill learned entirely through practice","A type of social institution","A term used only in sociology"],"ans":0,"exp":"Temperament refers to the innate, biologically based tendencies that shape how a person emotionally and behaviorally responds to the world."},{"q":"What term describes how the environment can influence which genes are expressed?","ch":["Genetic determinism","Epigenetics","Social stratification","Cultural relativism"],"ans":1,"exp":"Epigenetics studies how environmental factors can influence whether and how certain genes are expressed, without changing the DNA itself."},{"q":"Which of the following is an example of an environmental (nurture) influence on development?","ch":["Eye color","Blood type","The quality of a child's education","Natural hair texture"],"ans":2,"exp":"The quality of a child's education is an environmental factor, unlike inherited physical traits such as eye color or blood type."},{"q":"Why do most psychologists today avoid framing nature and nurture as an either-or question?","ch":["Because genetics has been proven irrelevant","Because environment has been proven irrelevant","Because the topic is no longer studied","Because research shows genes and environment continuously interact to shape development"],"ans":3,"exp":"Research consistently shows that genes and environment interact throughout development, so treating them as opposing, separate forces is misleading."}]},
{"id":"fbs11","cat":"Behavioral & Social Sciences","title":"Basic Personality Psychology","diff":"Easy","qs":[{"q":"What is personality?","ch":["A person's characteristic pattern of thoughts, feelings, and behaviors","A person's physical appearance only","A temporary mood state","A person's level of intelligence"],"ans":0,"exp":"Personality refers to a person's relatively stable and characteristic patterns of thinking, feeling, and behaving."},{"q":"The Big Five personality model includes openness, conscientiousness, extraversion, agreeableness, and which other trait?","ch":["Impulsivity","Neuroticism","Creativity","Intelligence"],"ans":1,"exp":"Neuroticism, which reflects emotional stability versus tendency toward negative emotions, is the fifth trait in the Big Five model."},{"q":"What does the trait \"extraversion\" describe in the Big Five model?","ch":["A tendency to worry and experience negative emotions","A tendency to be organized and disciplined","A tendency to be outgoing, sociable, and energetic","A tendency to be curious and open to new experiences"],"ans":2,"exp":"Extraversion describes a tendency to be outgoing, sociable, and to gain energy from social interaction."},{"q":"According to Sigmund Freud, which part of personality operates on the \"pleasure principle\" and seeks immediate gratification?","ch":["The superego","The ego","The conscience","The id"],"ans":3,"exp":"Freud described the id as the primitive part of personality that seeks immediate gratification of desires and impulses."},{"q":"What is the id, ego, and superego model part of?","ch":["Freud's psychoanalytic theory of personality","The Big Five trait model","Piaget's stages of development","Behaviorist learning theory"],"ans":0,"exp":"The id, ego, and superego are the three components of personality described in Freud's psychoanalytic theory."},{"q":"What is a personality trait?","ch":["A brief emotional reaction to a single event","A relatively stable characteristic that influences behavior across different situations","A skill learned through formal schooling","A random behavior with no consistency"],"ans":1,"exp":"A personality trait is a relatively stable and enduring characteristic that shapes behavior consistently across many situations."},{"q":"Which Big Five trait describes how organized, responsible, and dependable a person tends to be?","ch":["Openness","Neuroticism","Conscientiousness","Agreeableness"],"ans":2,"exp":"Conscientiousness describes the tendency to be organized, responsible, and dependable in one's actions."},{"q":"What is self-esteem?","ch":["A person's ability to remember facts","A person's genetic makeup","A person's physical strength","A person's overall sense of self-worth and value"],"ans":3,"exp":"Self-esteem refers to a person's overall subjective sense of their own worth and value."}]},
{"id":"fbs12","cat":"Behavioral & Social Sciences","title":"Stress & Mental Health Basics","diff":"Easy","qs":[{"q":"What is stress?","ch":["The body's response to demands or challenges that disrupt balance","A permanent personality trait","A type of mental illness","A random physical symptom with no cause"],"ans":0,"exp":"Stress is the body's natural physical and emotional response to demands or challenges that disrupt a person's usual balance."},{"q":"What is the difference between acute stress and chronic stress?","ch":["Acute stress lasts for years, while chronic stress lasts minutes","Acute stress is short-term, while chronic stress persists over a long period","There is no meaningful difference","Chronic stress only affects children"],"ans":1,"exp":"Acute stress is a brief, short-term reaction to a specific event, while chronic stress persists over weeks, months, or longer."},{"q":"Which of the following is considered a healthy coping strategy for managing stress?","ch":["Avoiding all social contact permanently","Ignoring the problem indefinitely","Regular exercise and talking with supportive friends or family","Increasing isolation from others"],"ans":2,"exp":"Regular physical activity and social support from friends or family are well-established healthy ways to help manage stress."},{"q":"What does it mean to seek professional help, such as talking to a counselor, for a mental health concern?","ch":["It means someone has failed personally","It is only for people with severe conditions","It is a sign of weakness","It is a proactive, healthy step that many people take to support their well-being"],"ans":3,"exp":"Seeking professional support is a proactive and healthy choice that many people make to care for their mental well-being, regardless of severity."},{"q":"What is resilience?","ch":["The ability to adapt and recover well from difficult or stressful experiences","The complete absence of stress in life","A fixed trait that cannot be developed","A medical diagnosis"],"ans":0,"exp":"Resilience is the ability to adapt to and recover from stress, setbacks, and difficult experiences, and it can be developed over time."},{"q":"Why is it important to talk openly about mental health rather than staying silent about struggles?","ch":["Because mental health struggles are rare and unimportant","Because open conversation can reduce stigma and help people get the support they need","Because talking about it makes problems worse","Because it is required by law in all situations"],"ans":1,"exp":"Open conversation about mental health helps reduce stigma and makes it easier for people to seek and receive the support they need."},{"q":"Which of the following is a normal, common human experience rather than a sign of weakness?","ch":["Never feeling stressed","Being immune to sadness","Experiencing stress or anxiety at times during daily life","Having no emotional reactions ever"],"ans":2,"exp":"Experiencing occasional stress or anxiety is a normal part of everyday life for most people and is not a sign of personal weakness."},{"q":"What is one benefit of getting enough sleep for mental health?","ch":["It has no effect on mood or thinking","It only affects physical growth","It weakens memory and concentration","It helps regulate mood, improve concentration, and support overall well-being"],"ans":3,"exp":"Adequate sleep helps regulate mood, supports concentration and memory, and contributes to overall mental well-being."}]},
{"id":"fbs13","cat":"Behavioral & Social Sciences","title":"Basic Neuroscience — the Brain","diff":"Medium","qs":[{"q":"What is the basic building block of the nervous system called?","ch":["A neuron","A hormone","A synapse","A ventricle"],"ans":0,"exp":"The neuron is the basic cell of the nervous system, specialized to transmit electrical and chemical signals."},{"q":"What is the primary function of the cerebellum?","ch":["Processing language","Coordinating balance and movement","Regulating hunger","Storing long-term memories"],"ans":1,"exp":"The cerebellum, located at the back of the brain, primarily coordinates balance, posture, and smooth muscle movement."},{"q":"Which part of the brain is responsible for higher-order thinking, decision-making, and personality, and is located at the front of the brain?","ch":["The brainstem","The occipital lobe","The frontal lobe","The cerebellum"],"ans":2,"exp":"The frontal lobe handles higher-order thinking, decision-making, planning, and aspects of personality."},{"q":"What is a synapse?","ch":["A type of brain cell","A region of the spinal cord","A hormone released by the pituitary gland","The small gap between two neurons where chemical signals are transmitted"],"ans":3,"exp":"A synapse is the small gap between two neurons across which neurotransmitters carry chemical signals."},{"q":"What are neurotransmitters?","ch":["Chemical messengers that transmit signals between neurons","Structural bones that protect the brain","Cells that make up muscle tissue","A type of memory storage"],"ans":0,"exp":"Neurotransmitters are chemical messengers that carry signals across the synapse from one neuron to another."},{"q":"Which lobe of the brain primarily processes visual information?","ch":["Frontal lobe","Occipital lobe","Temporal lobe","Parietal lobe"],"ans":1,"exp":"The occipital lobe, located at the back of the brain, is primarily responsible for processing visual information."},{"q":"What connects the brain to the rest of the body and controls basic life functions like breathing and heart rate?","ch":["The cerebral cortex","The occipital lobe","The brainstem","The hippocampus"],"ans":2,"exp":"The brainstem connects the brain to the spinal cord and controls essential automatic functions like breathing and heart rate."},{"q":"Which brain structure plays a key role in forming new long-term memories?","ch":["The cerebellum","The occipital lobe","The brainstem","The hippocampus"],"ans":3,"exp":"The hippocampus is critical for forming new long-term memories, especially memories of facts and events."}]},
{"id":"fbs14","cat":"Behavioral & Social Sciences","title":"Social Influence — Conformity & Peer Pressure","diff":"Medium","qs":[{"q":"What is conformity?","ch":["Adjusting one's behavior or beliefs to match those of a group","Refusing to interact with any group","A type of memory process","A formal legal requirement"],"ans":0,"exp":"Conformity is the tendency to adjust one's own behavior or beliefs to align with those of a group."},{"q":"In Solomon Asch's classic conformity experiments, what did participants often do when a group unanimously gave an obviously wrong answer?","ch":["They always gave the correct answer regardless of the group","Many participants conformed and gave the same wrong answer as the group","They immediately left the experiment","They reported the group to researchers"],"ans":1,"exp":"In Asch's experiments, a notable portion of participants conformed to the group's incorrect answer at least once, even when the correct answer was obvious."},{"q":"What is peer pressure?","ch":["Pressure from a person's family only","Pressure applied by teachers in a classroom","The influence that people of similar age or status place on one another to think or act a certain way","A type of formal punishment"],"ans":2,"exp":"Peer pressure refers to the influence exerted by people of similar age or status, encouraging someone to think or behave a certain way."},{"q":"What is obedience, as studied in social psychology?","ch":["Acting independently of any authority","A synonym for peer pressure","A type of memory","Behavior that complies with the direct instructions of an authority figure"],"ans":3,"exp":"Obedience refers to behavior that complies with the direct commands or instructions of an authority figure."},{"q":"What is normative social influence?","ch":["Conforming to be liked or accepted by a group","Conforming because you believe the group has accurate information","Refusing to conform under any circumstances","A type of memory storage"],"ans":0,"exp":"Normative social influence involves conforming to fit in, be liked, or gain approval from a group, rather than because you think they are right."},{"q":"What is informational social influence?","ch":["Conforming only to avoid punishment","Conforming because you believe the group's information is correct, especially in an uncertain situation","A type of brain structure","A term unrelated to group behavior"],"ans":1,"exp":"Informational social influence happens when people conform because they believe the group has accurate knowledge, especially in ambiguous situations."},{"q":"Which factor tends to increase the likelihood that a person will conform to a group?","ch":["Being alone rather than in a group","Having strong disagreement from at least one other group member","The group being unanimous in its opinion","Having no interest in the group's approval"],"ans":2,"exp":"Conformity tends to increase when a group is unanimous, since a single dissenting voice can make it much easier to resist group pressure."},{"q":"Why might a teenager go along with a group decision they privately disagree with?","ch":["Because they have no independent thoughts of their own","Because it is legally required","Because they misunderstood the question","Because they want to fit in and avoid social rejection from peers"],"ans":3,"exp":"People, especially teenagers, often conform to group decisions to fit in and avoid the discomfort of social rejection, even when they privately disagree."}]},
{"id":"fbs15","cat":"Behavioral & Social Sciences","title":"Basic Communication Skills","diff":"Easy","qs":[{"q":"What is active listening?","ch":["Fully concentrating on, understanding, and responding thoughtfully to a speaker","Waiting silently for your turn to talk without paying attention","Interrupting frequently to share your own opinion","Listening only to parts of a conversation that interest you"],"ans":0,"exp":"Active listening involves fully focusing on the speaker, understanding their message, and responding thoughtfully."},{"q":"What is nonverbal communication?","ch":["Communication using only written words","Communication through body language, facial expressions, and tone of voice rather than words","Communication that only happens over the phone","A term with no real meaning in psychology"],"ans":1,"exp":"Nonverbal communication conveys meaning through body language, facial expressions, gestures, and tone of voice instead of spoken words."},{"q":"What is empathetic communication?","ch":["Communicating without considering the other person's feelings","Communicating only through text messages","Communicating in a way that acknowledges and understands another person's feelings and perspective","A style of communication used only in formal debates"],"ans":2,"exp":"Empathetic communication involves acknowledging and trying to understand another person's feelings and point of view."},{"q":"What is a common barrier to effective communication?","ch":["Maintaining eye contact","Asking clarifying questions","Paraphrasing what someone said","Making assumptions about what someone means without checking"],"ans":3,"exp":"Assuming you understand what someone means without verifying it is a common barrier that leads to misunderstandings."},{"q":"What does it mean to use \"I\" statements in a conversation, such as \"I feel frustrated when...\"?","ch":["Expressing your own feelings and perspective without blaming the other person","Talking only about yourself and ignoring others","Refusing to admit any personal feelings","A formal grammar rule unrelated to communication"],"ans":0,"exp":"\"I\" statements express a person's own feelings and perspective in a way that reduces blame and defensiveness in the other person."},{"q":"Why is eye contact often considered an important part of communication in many cultures?","ch":["It has no effect on how a conversation is perceived","It can signal attentiveness, confidence, and engagement with the speaker","It is required by law during conversations","It replaces the need for verbal communication entirely"],"ans":1,"exp":"In many cultures, eye contact signals attentiveness, confidence, and genuine engagement with the person speaking."},{"q":"What is assertive communication?","ch":["Communicating in a way that ignores your own needs","Communicating in a way that dominates and disregards others","Expressing your thoughts and needs clearly and respectfully while respecting others","Avoiding all communication about your needs"],"ans":2,"exp":"Assertive communication means clearly and respectfully expressing your own thoughts and needs while also respecting the needs of others."},{"q":"What is feedback in the context of communication?","ch":["A one-way message with no response expected","A formal written document only","An unrelated psychological term","A response that lets the speaker know how their message was received and understood"],"ans":3,"exp":"Feedback is a response that helps the original speaker understand how their message was received and interpreted by the listener."}]},
{"id":"fbs16","cat":"Behavioral & Social Sciences","title":"Introduction to Motivation","diff":"Easy","qs":[{"q":"What term describes doing an activity because it is inherently enjoyable, not for an external reward?","ch":["Extrinsic motivation","Intrinsic motivation","Negative reinforcement","Social facilitation"],"ans":1,"exp":"Intrinsic motivation means engaging in a behavior for the internal satisfaction it provides, rather than for an outside reward."},{"q":"Which of the following is an example of extrinsic motivation?","ch":["Reading a novel because you love the story","Studying hard to earn a scholarship","Painting purely for personal enjoyment","Jogging because it feels relaxing"],"ans":1,"exp":"Extrinsic motivation involves acting in order to gain an external reward, such as a scholarship."},{"q":"According to Maslow's hierarchy of needs, which level must generally be satisfied first?","ch":["Physiological needs","Self-esteem needs","Self-actualization","Belongingness needs"],"ans":0,"exp":"Maslow placed basic physiological needs, like food and water, at the base of the hierarchy, arguing they must be met before higher needs are pursued."},{"q":"Which need, according to Maslow, involves reaching one's fullest potential?","ch":["Safety needs","Belongingness needs","Self-actualization","Physiological needs"],"ans":2,"exp":"Self-actualization sits at the top of Maslow's hierarchy and refers to fulfilling one's unique potential."},{"q":"Drive-reduction theory suggests that motivation arises mainly from:","ch":["A desire for social approval","Observing the behavior of others","Setting long-term personal goals","The need to reduce internal tension caused by unmet biological needs"],"ans":3,"exp":"Drive-reduction theory holds that unmet needs create internal tension, or a drive, that motivates behavior aimed at restoring balance."},{"q":"Which of the following is considered a basic biological drive?","ch":["Hunger","Curiosity about art","Desire for achievement","Need for creativity"],"ans":0,"exp":"Hunger is a biological drive rooted in the body's need for energy, unlike learned or psychological motives."},{"q":"The incentive theory of motivation focuses mainly on:","ch":["Internal tension reduction","Unconscious desires","External rewards that pull behavior toward them","Random chance"],"ans":2,"exp":"Incentive theory explains motivation as being 'pulled' by external rewards or goals rather than 'pushed' by internal drives."},{"q":"A student who works hard mainly to master challenging material and feel a sense of accomplishment is displaying:","ch":["Extrinsic motivation","Drive reduction","Social loafing","Intrinsic motivation"],"ans":3,"exp":"Wanting to master material for the personal satisfaction of accomplishment is a classic example of intrinsic motivation."}]},
{"id":"fbs17","cat":"Behavioral & Social Sciences","title":"Sleep & Consciousness Basics","diff":"Easy","qs":[{"q":"Which stage of sleep is most closely associated with vivid dreaming?","ch":["NREM Stage 1","NREM Stage 3","REM sleep","Being fully awake"],"ans":2,"exp":"REM (rapid eye movement) sleep is the stage in which the most vivid and memorable dreaming occurs."},{"q":"What is a circadian rhythm?","ch":["A sleep disorder","A roughly 24-hour internal biological clock","A brain wave pattern seen only in deep sleep","A stage of deep sleep"],"ans":1,"exp":"A circadian rhythm is the body's internal clock that regulates the sleep-wake cycle over about a 24-hour period."},{"q":"Which hormone, released by the pineal gland, helps promote sleepiness?","ch":["Melatonin","Adrenaline","Insulin","Dopamine"],"ans":0,"exp":"Melatonin is secreted by the pineal gland, especially in darkness, and helps signal to the body that it is time to sleep."},{"q":"In psychology, consciousness is best defined as:","ch":["A permanent state of deep sleep","A type of long-term memory","A stable personality trait","Our awareness of ourselves and our surroundings"],"ans":3,"exp":"Consciousness refers to our ongoing awareness of our own thoughts, feelings, and the environment around us."},{"q":"Which of the following is a common effect of chronic sleep deprivation?","ch":["Improved reaction time","Difficulty concentrating and irritability","Enhanced immune function","Increased short-term memory"],"ans":1,"exp":"Chronic lack of sleep commonly impairs concentration, mood, and overall cognitive functioning."},{"q":"Which stage of sleep is known for producing the deepest, slowest brain waves?","ch":["REM sleep","NREM Stage 1 (light sleep)","NREM Stage 3 (deep sleep)","Wakefulness"],"ans":2,"exp":"NREM Stage 3, often called deep or slow-wave sleep, produces the slowest and highest-amplitude brain waves of the sleep cycle."},{"q":"Most vivid dreaming occurs during which stage of the sleep cycle?","ch":["REM sleep","NREM Stage 3","NREM Stage 1","Wakeful rest"],"ans":0,"exp":"REM sleep is strongly associated with the most frequent and vivid dreaming."},{"q":"Insomnia is best described as:","ch":["A sleepwalking disorder","Excessive daytime sleepiness only","A type of recurring nightmare","Difficulty falling or staying asleep"],"ans":3,"exp":"Insomnia is a sleep disorder characterized by trouble falling asleep, staying asleep, or both."}]},
{"id":"fbs18","cat":"Behavioral & Social Sciences","title":"Perception & the Senses (Psychology)","diff":"Easy","qs":[{"q":"What is 'sensation' in psychology?","ch":["The process of detecting physical stimuli through sense organs","The process of interpreting and organizing sensory information","A long-term memory process","A type of emotional response"],"ans":0,"exp":"Sensation is the raw detection of stimuli, such as light or sound, by the body's sensory receptors."},{"q":"Perception refers to:","ch":["The physical detection of light or sound waves","A reflex reaction to pain","The brain's process of organizing and interpreting sensory information","The storage of sensory information in long-term memory"],"ans":2,"exp":"Perception is the brain's active process of organizing and making sense of the raw information gathered through sensation."},{"q":"The smallest amount of a stimulus a person can detect 50% of the time is called the:","ch":["Difference threshold","Absolute threshold","Sensory adaptation","Perceptual set"],"ans":1,"exp":"The absolute threshold is the minimum stimulus intensity needed for detection about half the time."},{"q":"Why do you eventually stop noticing the feeling of your clothes on your skin?","ch":["Difference threshold changes","Perceptual set","Selective attention","Sensory adaptation"],"ans":3,"exp":"Sensory adaptation occurs when receptors become less responsive to a constant, unchanging stimulus over time."},{"q":"When you see a circle with small gaps and your brain fills them in to perceive a complete circle, this illustrates the Gestalt principle of:","ch":["Proximity","Similarity","Closure","Figure-ground"],"ans":2,"exp":"Closure is the tendency to perceive incomplete shapes as whole by mentally filling in missing information."},{"q":"Which part of the eye contains the rod and cone photoreceptor cells?","ch":["Retina","Cornea","Pupil","Iris"],"ans":0,"exp":"The retina, located at the back of the eye, houses the rods and cones that convert light into neural signals."},{"q":"Which of the following is NOT one of the traditional five senses?","ch":["Vision","Hearing","Taste","Intuition"],"ans":3,"exp":"The traditional five senses are vision, hearing, taste, smell, and touch; intuition is not a physical sense."},{"q":"A tendency to perceive things a certain way based on prior expectations is called:","ch":["Sensory adaptation","Perceptual set","Absolute threshold","Figure-ground"],"ans":1,"exp":"A perceptual set is a mental predisposition that leads people to interpret ambiguous information based on what they expect to see."}]},
{"id":"fbs19","cat":"Behavioral & Social Sciences","title":"Group Dynamics Basics","diff":"Easy","qs":[{"q":"Social loafing refers to the tendency to:","ch":["Work harder in a group than alone","Conform to group opinions","Follow orders from an authority figure","Put in less individual effort when working in a group than when working alone"],"ans":3,"exp":"Social loafing describes reduced individual effort that can occur when people work collectively rather than individually."},{"q":"Groupthink occurs when:","ch":["A group's desire for harmony leads to poor decision-making","A group makes better decisions than individuals working alone","Each member works completely independently","Members compete aggressively against one another"],"ans":0,"exp":"Groupthink happens when the desire to maintain group harmony overrides critical evaluation of alternatives, leading to flawed decisions."},{"q":"Performing simple, well-learned tasks better in the presence of others is known as:","ch":["Social loafing","Deindividuation","Social facilitation","Groupthink"],"ans":2,"exp":"Social facilitation is the tendency for people's performance on simple tasks to improve when others are watching or present."},{"q":"Conformity is best defined as:","ch":["Obeying a direct order from an authority figure","Adjusting one's behavior or beliefs to match a group","Working alone without any input from others","Leading a group toward a shared goal"],"ans":1,"exp":"Conformity involves changing one's behavior or attitudes to align with those of a group."},{"q":"A group that a person does not belong to, and may view less favorably, is called the:","ch":["Out-group","In-group","Reference group","Peer group"],"ans":0,"exp":"The out-group refers to a social group a person does not identify with, as opposed to their own in-group."},{"q":"Losing individual self-awareness and personal responsibility while part of a large group is called:","ch":["Social facilitation","Conformity","Groupthink","Deindividuation"],"ans":3,"exp":"Deindividuation describes the loss of self-awareness and personal accountability that can occur within large groups or crowds."},{"q":"A leadership style that actively involves group members in decision-making is called:","ch":["Autocratic leadership","Democratic leadership","Laissez-faire leadership","Authoritarian leadership"],"ans":1,"exp":"Democratic leadership emphasizes shared input and participation from group members in reaching decisions."},{"q":"When discussing an issue with like-minded people causes a group's initial opinions to become more extreme, this is called:","ch":["Groupthink","Social loafing","Group polarization","Deindividuation"],"ans":2,"exp":"Group polarization refers to the strengthening of a group's shared opinion after discussion among similarly minded members."}]},
{"id":"fbs20","cat":"Behavioral & Social Sciences","title":"Basic Statistics — Mean, Median & Mode","diff":"Medium","qs":[{"q":"What is the mean of the data set: 2, 4, 6, 8, 10?","ch":["5","6","7","8"],"ans":1,"exp":"Adding the values (2+4+6+8+10=30) and dividing by 5 gives a mean of 6."},{"q":"What is the median of the data set: 3, 7, 9, 15, 21?","ch":["7","15","3","9"],"ans":3,"exp":"With the values already in order, the middle number of these five values is 9."},{"q":"What is the mode of the data set: 2, 2, 3, 5, 7, 7, 7?","ch":["7","2","5","3"],"ans":0,"exp":"The mode is the most frequently occurring value; 7 appears three times, more than any other value."},{"q":"What is the range of the data set: 4, 8, 15, 16, 23?","ch":["8","16","19","23"],"ans":2,"exp":"The range is the highest value minus the lowest value: 23 - 4 = 19."},{"q":"What is the median of the data set: 2, 4, 6, 8?","ch":["4","6","2","5"],"ans":3,"exp":"With an even number of values, the median is the average of the two middle numbers: (4+6)/2 = 5."},{"q":"The 'mean' of a data set is calculated by:","ch":["Listing the values in order and picking the middle one","Adding all the values and dividing by the number of values","Finding the value that occurs most often","Subtracting the smallest value from the largest"],"ans":1,"exp":"The mean, or average, is found by summing all values and dividing by how many values there are."},{"q":"The 'mode' of a data set is:","ch":["The middle value when the data is ordered","The average of all the values","The value that appears most frequently","The difference between the highest and lowest values"],"ans":2,"exp":"The mode is defined as the value that occurs most often in a data set."},{"q":"The 'median' of a data set is:","ch":["The middle value when the data is arranged in order","The most frequently occurring value","The sum of all values divided by their count","The largest value minus the smallest value"],"ans":0,"exp":"The median is the middle value once the data has been sorted from smallest to largest."}]},
{"id":"fbs21","cat":"Behavioral & Social Sciences","title":"Self-Esteem & Identity Basics","diff":"Easy","qs":[{"q":"Self-esteem refers to:","ch":["Your ability to recall past experiences","Your physical health status","Your overall sense of self-worth and value","Your level of intelligence"],"ans":2,"exp":"Self-esteem is a person's overall evaluation of their own worth and value."},{"q":"According to Erik Erikson, the primary psychosocial task of adolescence is developing a sense of:","ch":["Identity versus role confusion","Trust versus mistrust","Intimacy versus isolation","Autonomy versus shame"],"ans":0,"exp":"Erikson described adolescence as centered on resolving the conflict between forming a clear identity and experiencing role confusion."},{"q":"Self-concept is best described as:","ch":["A feeling of pride in one's achievements","A fixed, unchanging personality trait","A person's mood in a given moment","The set of beliefs a person holds about who they are"],"ans":3,"exp":"Self-concept refers to the overall collection of beliefs a person has about their own identity and characteristics."},{"q":"A person's belief in their ability to succeed at a specific task is called:","ch":["Self-esteem","Self-efficacy","Self-concept","Self-actualization"],"ans":1,"exp":"Self-efficacy is the confidence a person has in their own ability to accomplish a specific task or goal."},{"q":"The part of a person's identity that comes from belonging to social groups, such as nationality or team membership, is called:","ch":["Social identity","Personal identity","Self-efficacy","Ego identity"],"ans":0,"exp":"Social identity is the portion of one's self-concept derived from membership in social groups."},{"q":"Which of the following is commonly associated with low self-esteem?","ch":["Excessive confidence in all situations","Strong leadership skills","Increased sensitivity to criticism","Higher academic performance"],"ans":2,"exp":"People with low self-esteem often show heightened sensitivity to criticism and negative feedback."},{"q":"An 'identity crisis,' as described by Erikson, refers to:","ch":["A permanent state of low self-esteem","A period of uncertainty while exploring who one is","A medical diagnosis","A conflict between two unrelated people"],"ans":1,"exp":"An identity crisis is a temporary period of exploration and uncertainty as a person works toward a stable sense of self."},{"q":"Which statement about self-esteem is most accurate?","ch":["It is fixed at birth and cannot change","It depends only on physical appearance","It is unrelated to relationships with others","It can change over time based on experiences and relationships"],"ans":3,"exp":"Self-esteem is not fixed; it can shift over a lifetime in response to achievements, feedback, and relationships."}]},
{"id":"fbs22","cat":"Behavioral & Social Sciences","title":"Family & Socialization Basics","diff":"Easy","qs":[{"q":"Socialization is the process by which:","ch":["People learn the norms, values, and behaviors of their society","People develop physical strength","Genes are passed from parents to children","Governments create laws"],"ans":0,"exp":"Socialization is the lifelong process through which individuals learn the expectations and behaviors of their culture."},{"q":"The family is often called the primary agent of socialization because:","ch":["It is the last group a person interacts with","It is usually the first group to teach a child social norms","It has no influence on behavior","It only affects physical development"],"ans":1,"exp":"The family is typically the first and most influential group that teaches children basic norms and values."},{"q":"Besides the family, which of the following is also considered an agent of socialization?","ch":["A person's blood type","A person's height","A person's eye color","Schools and peer groups"],"ans":3,"exp":"Schools and peer groups are important agents of socialization outside the family, teaching norms and social skills."},{"q":"A 'nuclear family' typically refers to:","ch":["A group of unrelated friends living together","Extended relatives spanning several generations","Parents and their children living as one household unit","A community organization"],"ans":2,"exp":"A nuclear family generally consists of parents and their children living together as a single household unit."},{"q":"An 'extended family' includes:","ch":["Only parents and their children","Relatives beyond the nuclear family, such as grandparents, aunts, and uncles","Only children with no adults present","People unrelated by blood or marriage"],"ans":1,"exp":"Extended family refers to relatives beyond parents and children, including grandparents, aunts, uncles, and cousins."},{"q":"The process by which children learn culturally expected behaviors associated with being male or female is called:","ch":["Cognitive development","Physical maturation","Language acquisition","Gender-role socialization"],"ans":3,"exp":"Gender-role socialization is how children learn the behaviors and expectations their culture associates with gender."},{"q":"During adolescence, which agent of socialization typically becomes more influential than in early childhood?","ch":["Peer groups","Grandparents","Physical education teachers only","Infant caregivers"],"ans":0,"exp":"Peer groups tend to gain significant influence over attitudes and behavior during the teenage years."},{"q":"Learning new norms and values that differ from one's previous ones, such as when joining the military, is called:","ch":["Primary socialization","Gender-role socialization","Resocialization","Anticipatory socialization"],"ans":2,"exp":"Resocialization involves discarding previous behavior patterns and adopting new ones, often within a new institution or role."}]},
{"id":"fbs23","cat":"Behavioral & Social Sciences","title":"Basic Abnormal Psychology Concepts","diff":"Easy","qs":[{"q":"A psychological disorder is generally defined as a pattern of thoughts, feelings, or behaviors that:","ch":["Only affects children","Is always inherited genetically","Cannot be treated","Causes significant distress or impairment in daily functioning"],"ans":3,"exp":"Psychological disorders are typically defined by patterns that cause meaningful distress or interfere with a person's daily life."},{"q":"Which of the following is an example of an anxiety disorder?","ch":["Major depressive disorder","Bipolar disorder","Generalized anxiety disorder","Schizophrenia"],"ans":2,"exp":"Generalized anxiety disorder is classified as an anxiety disorder, characterized by excessive, persistent worry."},{"q":"A common symptom of major depressive disorder is:","ch":["Persistent sadness or loss of interest in activities","Excessive energy and euphoria for weeks","Improved concentration","Increased social confidence"],"ans":0,"exp":"Persistent low mood and loss of interest in previously enjoyed activities are hallmark symptoms of major depressive disorder."},{"q":"Which statement best reflects current scientific understanding of mental illness?","ch":["Mental illnesses are a sign of personal weakness","Mental illnesses are real medical conditions that can often be effectively treated","People with mental illness cannot lead successful lives","Mental illness only affects a person's mood, never their body"],"ans":1,"exp":"Modern science treats mental illnesses as legitimate medical conditions that are often manageable or treatable, not personal failings."},{"q":"A phobia is best described as:","ch":["A brief moment of sadness","A memory disorder","An intense, irrational fear of a specific object or situation","A personality trait present at birth"],"ans":2,"exp":"A phobia involves an excessive and persistent fear of a specific object or situation that is out of proportion to actual danger."},{"q":"Which of the following is an accurate statement about seeking mental health treatment?","ch":["Only 'severe' cases should ever seek help","Therapy never helps with everyday stress","Asking for help means someone has failed","Reaching out for professional support is a proactive, healthy step many people take"],"ans":3,"exp":"Seeking professional mental health support is a common, healthy choice, not a sign of failure or weakness."},{"q":"Bipolar disorder is classified as a type of:","ch":["Anxiety disorder","Mood disorder","Personality disorder","Eating disorder"],"ans":1,"exp":"Bipolar disorder involves significant shifts between depressive and manic episodes, placing it in the category of mood disorders."},{"q":"'Stigma' surrounding mental illness refers to:","ch":["Negative stereotypes and judgment directed at people with psychological disorders","A required medical test for diagnosis","A type of therapy technique","A symptom of anxiety disorders"],"ans":0,"exp":"Stigma refers to the unfair negative attitudes and stereotypes society can direct at people who have psychological disorders."}]},
{"id":"fbs24","cat":"Behavioral & Social Sciences","title":"Introduction to Public Health","diff":"Easy","qs":[{"q":"Public health is best defined as the field focused on:","ch":["Treating individual patients in a hospital","Protecting and improving the health of entire populations and communities","Performing surgery","Diagnosing rare genetic diseases only"],"ans":1,"exp":"Public health focuses on protecting and improving the health of whole communities and populations, rather than individual patients alone."},{"q":"Vaccinating healthy children to prevent disease before it occurs is an example of:","ch":["Primary prevention","Secondary prevention","Tertiary prevention","No prevention"],"ans":0,"exp":"Primary prevention aims to stop disease before it starts, and vaccination is a classic example."},{"q":"Screening tests, like a blood pressure check to catch a problem early, are an example of:","ch":["Primary prevention","Tertiary prevention","Secondary prevention","Quaternary prevention"],"ans":2,"exp":"Secondary prevention involves early detection of disease, often through screening, before symptoms become severe."},{"q":"Epidemiology is the study of:","ch":["Individual genetic disorders","The structure of the human skeleton","How to perform surgery","The patterns and causes of disease in populations"],"ans":3,"exp":"Epidemiology examines how diseases are distributed and what causes them within populations."},{"q":"'Social determinants of health' refer to:","ch":["Conditions such as income, education, and environment that affect health outcomes","Only a person's genetic makeup","Medications prescribed by doctors","Hospital equipment standards"],"ans":0,"exp":"Social determinants of health are the social and economic conditions, like income and education, that shape a person's health."},{"q":"When enough of a population is immune to a disease, making its spread unlikely, this is called:","ch":["Quarantine","Herd immunity","Epidemiology","Incidence rate"],"ans":1,"exp":"Herd immunity occurs when a large enough portion of a population is immune, limiting the disease's ability to spread."},{"q":"Rehabilitation programs that help someone manage an existing chronic illness are an example of:","ch":["Primary prevention","Secondary prevention","Screening","Tertiary prevention"],"ans":3,"exp":"Tertiary prevention focuses on managing and reducing the impact of an already-established disease or condition."},{"q":"A disease outbreak that spreads across multiple countries or continents is called a:","ch":["Epidemic","Endemic disease","Pandemic","Outbreak cluster"],"ans":2,"exp":"A pandemic is an outbreak of disease that has spread across a wide geographic area, such as multiple countries or continents."}]},
{"id":"fbs25","cat":"Behavioral & Social Sciences","title":"Basic Research Ethics","diff":"Medium","qs":[{"q":"'Informed consent' in research means that participants:","ch":["Are paid for their participation","Are unaware of the study's purpose until it ends","Are told relevant information about the study and agree to participate voluntarily","Must complete the study once they begin"],"ans":2,"exp":"Informed consent requires that participants receive relevant information about a study and voluntarily agree to take part."},{"q":"Confidentiality in research refers to:","ch":["Publishing participants' names in reports","Sharing data freely with any interested party","Requiring participants to reveal personal secrets","Protecting participants' private information from unauthorized disclosure"],"ans":3,"exp":"Confidentiality means researchers safeguard participants' personal information and do not disclose it without permission."},{"q":"Which principle allows research participants to leave a study at any time without penalty?","ch":["Confidentiality","The right to withdraw","Deception","Debriefing"],"ans":1,"exp":"The right to withdraw ensures participation remains voluntary throughout, letting participants leave at any point without consequence."},{"q":"'Debriefing' after a study involves:","ch":["Explaining the true purpose of the study to participants afterward","Collecting payment from participants","Randomly assigning participants to groups","Publishing results in a journal"],"ans":0,"exp":"Debriefing is the process of informing participants about the study's true purpose and any deception used, once it concludes."},{"q":"An Institutional Review Board (IRB) is responsible for:","ch":["Funding research studies","Writing scientific journal articles","Recruiting participants for a study","Reviewing research proposals to ensure ethical treatment of participants"],"ans":3,"exp":"IRBs evaluate proposed research to make sure participants will be treated ethically and their rights protected."},{"q":"A core ethical principle requiring researchers to avoid causing physical or psychological harm to participants is called:","ch":["Deception","Random sampling","Minimizing harm (nonmaleficence)","Data falsification"],"ans":2,"exp":"Minimizing harm is a fundamental ethical obligation that requires researchers to protect participants from injury or distress."},{"q":"When a study involves minor deception, ethical guidelines typically require that researchers:","ch":["Debrief participants afterward and explain the deception","Never inform participants of the true purpose","Publish the deception in advertising","Avoid getting IRB approval"],"ans":0,"exp":"If deception is used, ethical standards require debriefing participants afterward to explain the true nature of the study."},{"q":"Modern research ethics rules, including strict informed consent requirements, were strengthened in response to historical cases such as:","ch":["Routine classroom quizzes","The Tuskegee syphilis study, where participants were not properly informed","Standard weather forecasting","Ordinary customer satisfaction surveys"],"ans":1,"exp":"The unethical Tuskegee syphilis study, in which participants were not properly informed or treated, helped drive reforms in research ethics."}]},
{"id":"fbs26","cat":"Behavioral & Social Sciences","title":"Social Stratification Basics","diff":"Easy","qs":[{"q":"Social stratification refers to:","ch":["The way society ranks people into hierarchical categories based on factors like wealth or status","A type of government system","The process of learning a language","A method of scientific classification"],"ans":0,"exp":"Social stratification describes how a society is organized into layers or ranks based on factors such as wealth, power, or status."},{"q":"'Social class' typically groups people based on:","ch":["Eye color","Height and weight","Favorite hobbies","Income, wealth, education, and occupation"],"ans":3,"exp":"Social class is usually determined by economic and social factors such as income, wealth, education, and occupation."},{"q":"Social mobility refers to:","ch":["A fixed social position that never changes","Moving to a new country","The ability to move up or down the social hierarchy","A type of government policy"],"ans":2,"exp":"Social mobility is the movement of individuals or groups between different levels of the social hierarchy."},{"q":"A caste system is a form of social stratification in which social position is:","ch":["Based entirely on personal achievement","Determined at birth and generally cannot be changed","Randomly assigned each year","Based on a public vote"],"ans":1,"exp":"In a caste system, a person's social position is fixed at birth and offers little to no opportunity for change."},{"q":"Compared to a caste system, a class system is typically more:","ch":["Rigid and unchangeable","Based solely on family name","Determined by random lottery","Open, allowing movement based on factors like education and income"],"ans":3,"exp":"Class systems are generally more open than caste systems, allowing people to move between social levels based on achievement."},{"q":"A 'meritocracy' is a system in which social status is based mainly on:","ch":["Individual ability and achievement","Family lineage alone","Random assignment","Physical strength alone"],"ans":0,"exp":"A meritocracy assigns social status based on a person's abilities and accomplishments rather than birth or background."},{"q":"The 'poverty line' refers to:","ch":["The average income of the wealthiest households","A set income level below which a person or family is considered unable to meet basic needs","A tax bracket for high earners","A measure of educational attainment"],"ans":1,"exp":"The poverty line is a designated income threshold below which a household is considered unable to afford basic necessities."},{"q":"Income inequality refers to:","ch":["Equal pay for all workers","A government policy banning wages","The uneven distribution of income across individuals or groups in a society","A type of retirement plan"],"ans":2,"exp":"Income inequality describes how unevenly income is spread across a population."}]},
{"id":"fbs27","cat":"Behavioral & Social Sciences","title":"Basic Health Economics Concepts","diff":"Easy","qs":[{"q":"Health insurance is best described as:","ch":["A government agency that trains doctors","A system in which people pay premiums to help cover the cost of medical care","A type of medical procedure","A hospital department"],"ans":1,"exp":"Health insurance is a system where people pay regular premiums in exchange for financial coverage of medical costs."},{"q":"In health insurance, a 'premium' is:","ch":["The amount paid out of pocket during a doctor visit only","A penalty for missing an appointment","The regular amount paid, often monthly, to maintain insurance coverage","The total cost of a hospital stay"],"ans":2,"exp":"A premium is the recurring payment, typically monthly, required to keep an insurance policy active."},{"q":"A health insurance 'deductible' is:","ch":["The amount a person must pay out of pocket before insurance starts covering costs","The monthly fee paid to keep insurance active","A type of medical test","The salary of a doctor"],"ans":0,"exp":"A deductible is the amount an insured person must pay themselves before their insurance plan begins to pay for covered services."},{"q":"In economics, 'opportunity cost' refers to:","ch":["The price printed on a receipt","A tax added to purchases","The interest rate on a loan","The value of the next best alternative given up when making a choice"],"ans":3,"exp":"Opportunity cost is what you give up, or the next best alternative, when you choose one option over another."},{"q":"According to the basic law of supply and demand, if demand for a good increases while supply stays the same, the price will typically:","ch":["Decrease","Stay exactly the same","Increase","Become impossible to determine"],"ans":2,"exp":"When demand rises but supply remains constant, basic economic theory predicts the price will increase."},{"q":"'Scarcity' in economics refers to:","ch":["An unlimited supply of resources","The basic problem that resources are limited while wants are unlimited","A type of currency","A government subsidy"],"ans":1,"exp":"Scarcity is the fundamental economic problem that resources are limited relative to the unlimited wants of people."},{"q":"A 'copay' is:","ch":["The annual limit on insurance coverage","A refund from an insurance company","The full cost of a surgery","A fixed fee a patient pays for a covered service, such as $20 for a doctor visit"],"ans":3,"exp":"A copay is a set, fixed amount a patient pays out of pocket for a specific covered medical service."},{"q":"One economic argument for investing in preventive health care, like regular checkups, is that it can:","ch":["Reduce long-term healthcare costs by catching problems early","Always cost more than treating advanced disease","Eliminate the need for all future doctor visits","Guarantee a cure for every illness"],"ans":0,"exp":"Preventive care can catch health problems early, which is often less costly to treat than advanced disease."}]},
{"id":"fbs28","cat":"Behavioral & Social Sciences","title":"Discrimination & Prejudice Basics","diff":"Easy","qs":[{"q":"Prejudice refers to:","ch":["A specific law against unfair treatment","An action that physically harms someone","A neutral opinion based on facts","An unjustified negative attitude toward a person based on their group membership"],"ans":3,"exp":"Prejudice is an unfair, negative attitude directed at someone simply because of the group they belong to."},{"q":"Unlike prejudice, which is an attitude, 'discrimination' refers to:","ch":["A person's private thoughts","Unfair behavior or actions taken against a person or group","A type of mental illness","A legal contract"],"ans":1,"exp":"Discrimination involves actual unfair behavior or treatment toward a person or group, whereas prejudice is an attitude or belief."},{"q":"A 'stereotype' is best defined as:","ch":["A documented scientific fact","A personal friendship","An oversimplified, generalized belief about a group of people","A government policy"],"ans":2,"exp":"A stereotype is an overly simple, generalized belief applied to all members of a group."},{"q":"The tendency to favor members of one's own group over members of other groups is called:","ch":["In-group bias","Reverse discrimination","Cultural relativism","Social facilitation"],"ans":0,"exp":"In-group bias refers to favoring one's own group over an out-group."},{"q":"When discrimination is built into the policies or practices of organizations rather than just individual attitudes, it is called:","ch":["Interpersonal discrimination","Institutional discrimination","Reverse psychology","Cognitive dissonance"],"ans":1,"exp":"Institutional discrimination refers to unfair treatment embedded in the rules or practices of organizations and institutions."},{"q":"The idea that positive, structured contact between different groups can help reduce prejudice is known as the:","ch":["Bystander effect","Social loafing theory","Fundamental attribution error","Contact hypothesis"],"ans":3,"exp":"The contact hypothesis proposes that well-structured interaction between groups can reduce prejudice over time."},{"q":"Blaming a particular group unfairly for problems they did not cause is called:","ch":["Scapegoating","Debriefing","Socialization","Assimilation"],"ans":0,"exp":"Scapegoating occurs when a group is unfairly blamed for problems or frustrations they did not actually cause."},{"q":"Judging another culture using the standards and values of one's own culture is called:","ch":["Cultural relativism","Institutional discrimination","Ethnocentrism","Social mobility"],"ans":2,"exp":"Ethnocentrism is evaluating another culture through the lens of one's own cultural standards and values."}]},
{"id":"fbs29","cat":"Behavioral & Social Sciences","title":"Study Skills & the Psychology of Learning","diff":"Easy","qs":[{"q":"Studying material across several shorter sessions over time, rather than in one long session, takes advantage of the:","ch":["Spacing effect","Forgetting curve only","Bystander effect","Halo effect"],"ans":0,"exp":"The spacing effect describes how information is remembered better when study sessions are spread out over time rather than crammed together."},{"q":"Testing yourself on material, such as with flashcards, to strengthen memory is called:","ch":["Passive rereading","Cramming","Active recall","Rote imitation"],"ans":2,"exp":"Active recall involves retrieving information from memory, such as through self-testing, which strengthens long-term retention."},{"q":"Giving a student praise immediately after they complete their homework, which increases the likelihood they will do it again, is an example of:","ch":["Punishment","Extinction","Negative reinforcement","Positive reinforcement"],"ans":3,"exp":"Positive reinforcement involves adding a pleasant stimulus, like praise, after a behavior to increase the chance it will be repeated."},{"q":"In classical conditioning, a neutral stimulus that becomes associated with an unconditioned stimulus eventually becomes a:","ch":["Reinforcer","Conditioned stimulus","Punisher","Schedule of reinforcement"],"ans":1,"exp":"Once a neutral stimulus is repeatedly paired with an unconditioned stimulus, it becomes a conditioned stimulus that triggers a learned response."},{"q":"Compared to spaced-out studying, cramming the night before a test tends to result in:","ch":["Better long-term retention","Identical long-term retention","Weaker long-term retention of the material","Permanent memory storage"],"ans":2,"exp":"Cramming generally produces weaker long-term retention compared to studying the same material spaced out over time."},{"q":"'Metacognition' refers to:","ch":["Thinking about and monitoring one's own learning process","A type of long-term memory disorder","The physical structure of the brain","A reflex response"],"ans":0,"exp":"Metacognition is the awareness and understanding of one's own thought and learning processes."},{"q":"Mixing up different topics or types of problems during a single study session, rather than practicing one type repeatedly, is called:","ch":["Massed practice","Interleaving","Extinction","Habituation"],"ans":1,"exp":"Interleaving involves alternating between different topics or problem types during study, which research shows can improve learning."},{"q":"Getting adequate sleep after studying is important because sleep helps with:","ch":["Eliminating the need to review material again","Increasing test anxiety","Immediate forgetting of new material","Consolidating and strengthening newly learned information"],"ans":3,"exp":"Sleep plays an important role in memory consolidation, helping the brain strengthen and retain newly learned information."}]},
{"id":"fbs30","cat":"Behavioral & Social Sciences","title":"Basic Emotional Intelligence","diff":"Easy","qs":[{"q":"Emotional intelligence (EI) is best defined as the ability to:","ch":["Score well on a math test","Memorize large amounts of information quickly","Recognize, understand, and manage one's own and others' emotions","Run faster than average"],"ans":2,"exp":"Emotional intelligence involves the ability to perceive, understand, and manage emotions in oneself and in others."},{"q":"Recognizing and understanding your own emotions as they occur is called:","ch":["Social skills","Self-awareness","Motivation","Empathy"],"ans":1,"exp":"Self-awareness is the emotional intelligence component involving recognition of one's own emotional states."},{"q":"Empathy refers to the ability to:","ch":["Control your own anger","Memorize facts quickly","Avoid social situations","Understand and share the feelings of another person"],"ans":3,"exp":"Empathy is the capacity to understand and share in the feelings and perspective of another person."},{"q":"'Self-regulation' in emotional intelligence involves:","ch":["Managing and controlling one's emotional reactions appropriately","Ignoring emotions completely","Copying other people's behavior","Avoiding all social interaction"],"ans":0,"exp":"Self-regulation refers to the ability to manage and control one's emotional responses in a constructive way."},{"q":"Being able to build positive relationships, communicate clearly, and manage conflict with others reflects the emotional intelligence component of:","ch":["Self-awareness","Social skills","Motivation","Self-regulation"],"ans":1,"exp":"Social skills, one of the core components of emotional intelligence, involve managing relationships and communicating effectively with others."},{"q":"Within emotional intelligence, 'motivation' refers to:","ch":["Getting rewards only from other people","Following orders without question","An inner drive to pursue goals, even in the face of setbacks","Avoiding difficult tasks"],"ans":2,"exp":"In emotional intelligence, motivation describes an internal drive to pursue goals persistently despite obstacles."},{"q":"Higher emotional intelligence is generally associated with:","ch":["Better communication and relationship skills","Lower academic performance","Complete absence of negative emotions","Reduced ability to work in teams"],"ans":0,"exp":"People with higher emotional intelligence tend to communicate more effectively and build stronger relationships."},{"q":"Which statement about emotional intelligence is most accurate?","ch":["It is entirely fixed at birth and cannot improve","It has nothing to do with relationships","It is the same thing as IQ","It can be developed and strengthened with practice over time"],"ans":3,"exp":"Unlike a fixed trait, emotional intelligence can be developed and improved through practice and experience."}]}
];
